(()=>{'use strict';const base=()=>String(window.MIRAE_CONFIG?.SUPABASE_URL||location.origin).replace(/\/$/,'');window.MiraeServerURL=path=>new URL(path,base()+'/').href;const original=window.fetch.bind(window);window.fetch=(input,init)=>{if(typeof input==='string'&&/^\/(?:api|rest)\//.test(input))input=window.MiraeServerURL(input);return original(input,init)};})();

