(()=>{'use strict';let chain=Promise.resolve();
function show(message,options={}){const run=()=>new Promise(resolve=>{const previous=document.activeElement,d=document.createElement('dialog');d.className='mirae-confirm';const head=document.createElement('header'),title=document.createElement('h2'),body=document.createElement('p'),foot=document.createElement('footer');title.textContent=options.title||'확인해 주세요';body.textContent=String(message??'');head.append(title);d.append(head,body);let input;if(options.input){input=document.createElement('input');input.type='text';input.value=String(options.value??'');input.setAttribute('aria-label',options.inputLabel||'입력 내용');d.append(input)}let settled=false;const finish=value=>{if(settled)return;settled=true;d.close();d.remove();previous?.isConnected&&previous.focus?.();resolve(value)};if(!options.alert){const cancel=document.createElement('button');cancel.type='button';cancel.className='btn';cancel.textContent='취소';cancel.onclick=()=>finish(options.input?null:false);foot.append(cancel)}const yes=document.createElement('button');yes.type='button';yes.className='btn primary';yes.textContent=options.ok||'확인';yes.onclick=()=>finish(options.input?input.value:true);foot.append(yes);d.append(foot);d.oncancel=e=>{e.preventDefault();finish(options.input?null:false)};document.body.append(d);d.showModal();(input||foot.firstChild).focus();});const result=chain.then(run,run);chain=result.catch(()=>{});return result}
window.MiraeDialog={confirm:(m,o)=>show(m,o),alert:(m,o)=>show(m,{...o,alert:true}),prompt:(m,v)=>show(m,{input:true,value:v})};
})();

