function art(kind){const marks=kind==='video'?'<rect x="24" y="24" width="72" height="48" rx="8"/><path d="m52 36 20 12-20 12z"/>':kind==='search'?'<circle cx="55" cy="40" r="17"/><path d="m68 53 16 16"/>':kind==='chat'?'<path d="M27 24h66v41H57L40 77V65H27z"/><path d="M41 38h37M41 49h25"/>':kind==='calendar'?'<rect x="29" y="23" width="63" height="53" rx="8"/><path d="M29 38h63M44 17v12M77 17v12M42 51h8M61 51h8M42 63h8"/>':'<path d="M36 17h38l15 15v47H36zM74 17v17h15M47 46h28M47 57h22M47 68h14"/>';return '<svg class="state-art" viewBox="0 0 120 96" aria-hidden="true"><ellipse cx="60" cy="82" rx="45" ry="7" fill="#edf1ec"/><circle cx="60" cy="46" r="42" fill="#f1f5ee"/><g fill="#fff" stroke="#92aa8c" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round">'+marks+'</g><circle cx="96" cy="19" r="4" fill="#c9d8bc"/><circle cx="22" cy="66" r="3" fill="#dce6d5"/></svg>'}
function copy(text,sub){let title=text,detail=sub,kind='document';if(/검색|조건|일치하는/.test(text)){title='검색 결과가 없습니다';detail=detail||'검색어나 선택한 조건을 바꿔 주세요.';kind='search'}else if(/수업 기록/.test(text)){title='아직 공개된 수업 기록이 없습니다';detail=detail||'공개된 수업 기록이 이곳에 모입니다.';kind='calendar'}else if(/강좌|수강/.test(text)){title=text.replace(/\.$/,'');detail=detail||'선택한 학생과 조회 조건을 확인해 주세요.';kind='calendar'}else if(/메시지|대화/.test(text)){title=text.replace(/\.$/,'');detail=detail||'메시지를 이곳에서 확인할 수 있습니다.';kind='chat'}else if(/보충|일정|예약/.test(text)){title=text.replace(/\.$/,'');detail=detail||'일정과 선택한 조회 조건을 확인해 주세요.';kind='calendar'}else if(/영상/.test(text)){title=text.replace(/\.$/,'');detail=detail||'공개된 영상을 이곳에서 확인할 수 있습니다.';kind='video'}else if(/알림/.test(text)){title='새로운 알림이 없습니다';detail=detail||'도착한 알림을 이곳에서 확인할 수 있습니다.';kind='chat'}else if(/없습니다|없어요|비어/.test(text)){title=text.replace(/등록된 |표시할 /,'').replace(/\.$/,'');detail=detail||'새로운 내용이 등록되면 이곳에 표시됩니다.'}return{title,detail,kind}}
function empty(text='아직 등록된 항목이 없습니다',sub=''){const c=copy(text,sub);return '<div class="empty m-state" data-state="empty">'+art(c.kind)+'<strong>'+E(c.title)+'</strong>'+(c.detail?'<p>'+E(c.detail)+'</p>':'')+'</div>'}
function loading(text='내용을 불러오고 있습니다.'){return '<div class="m-state state-loading" role="status"><span class="state-spinner" aria-hidden="true"></span><strong>'+E(text)+'</strong></div>'}
