 function targetCards(targets,edit){return grid(['학생','강사 · 반','구분 · 시간','사유','상태','관리'],targets.map(t=>'<tr><td><strong>'+esc(t.student_name)+'</strong></td><td>'+esc(t.teacher)+' · '+esc(course(t))+'</td><td>'+kind(t.kind)+' · '+t.duration+'분</td>'+reason(t)+'<td>'+(t.assignment_mode==='assigned'?'강사 지정 · ':'')+({completed:'보충 완료',scheduled:'예정',in_progress:'진행 중',unbooked:'신청 대기',cancelled:'해제',invalid:'일정 확인 필요'})[MiraeMakeupPhase.target(t,data.bookings)]+'</td><td class="makeup-row-actions">'+detailsButton(t)+(edit&&t.teacher_id===owner?(MiraeMakeupPhase.target(t,data.bookings)==='unbooked'?'<button class="btn sm" data-manual-target="'+t.id+'">대리 신청 · 등원</button>':MiraeMakeupPhase.booking(t,data.bookings)?.state==='confirmed'?'<button class="btn sm" data-target-complete="'+t.id+'">등원 확인</button>':'')+'<button class="btn sm" data-target-edit="'+t.id+'">수정</button><button class="btn sm ghost" data-target-revoke="'+t.id+'">대상 해제</button>':'')+'</td></tr>'))}
