 function assignmentControls(mode='request',date='',start='14:00'){return '<fieldset class="makeup-assignment-mode"><legend>보충 일정 방식</legend><label><input type="radio" name="assignment_mode" value="request" '+(mode==='request'?'checked':'')+'><span>신청 받기</span><small>학생 · 학부모가 시간 선택</small></label><label><input type="radio" name="assignment_mode" value="assigned" '+(mode==='assigned'?'checked':'')+'><span>강사 지정</span><small>정해진 일정으로 바로 확정</small></label></fieldset><div class="form-grid makeup-assigned-fields" data-assigned-schedule '+(mode==='assigned'?'':'hidden')+'><label class="field"><span data-assigned-start-label>보충 날짜</span><input name="date" type="date" value="'+esc(date||MiraeAttendanceCore.korea().date)+'"></label><label class="field"><span data-assigned-time-label>시작 시간</span><input name="start" type="time" step="1800" value="'+esc(start)+'"></label></div>';}
