 function editTarget(old){if(!old)return batchTargets();const booking=data.bookings.find(b=>b.target_id===old.id&&['confirmed','completed'].includes(b.state));const form=editor('보충 대상 수정',assignmentControls(old.assignment_mode||'request',booking?.date,booking?.start)+roomField(booking?.classroom||old.classroom||'')+'<p class="makeup-fixed-student"><strong>'+esc(old.student_name)+'</strong> · '+esc(data.courses.find(c=>c.id===old.class_id)?.name||'담당 수강반')+'</p><div class="form-grid">'+option('kind','보충 구분 · 학생 화면에 표시하지 않음',[['group','단체보충'],['individual','단일보충']],old.kind)+option('duration','필요 시간',durations(),old.duration)+'</div><label class="field"><span>준비물</span><textarea name="materials" required maxlength="2000" rows="2">'+esc(old.materials)+'</textarea></label><label class="field"><span>보충 사유</span><textarea name="reason" required maxlength="2000" rows="3">'+esc(old.reason)+'</textarea></label>',body=>cfg.api('/api/makeups/target-save',{method:'POST',body:{...body,id:old.id,version:old.version}}));assignmentBind(form);if(booking)form.querySelectorAll('[name=assignment_mode],[name=date],[name=start],[name=kind],[name=duration]').forEach(x=>x.disabled=true)}
 function durations(){return Array.from({length:16},(_,i)=>[(i+1)*30,(i+1)*30+'분'])}
