  function preview(){const values=scheduleValues();form.querySelectorAll('[data-assigned-preview]').forEach(x=>{const r=rows[+x.dataset.assignedPreview],v=values.find(v=>v.student_id===r.id);x.textContent=assigned()&&v?v.date+' '+v.start+' · '+v.duration+'분':'';});form.querySelector('[data-assigned-time-label]').textContent=assigned()&&!isIndividual()&&form.elements.kind.value==='individual'?'첫 시작 시간 · 학생 순서대로':'시작 시간';}
