  function draw(){form.querySelector('[data-batch-students]').innerHTML=rows.map((r,i)=>'<article class="makeup-batch-row"><label class="makeup-batch-person"><input type="checkbox" data-batch-check="'+i+'" '+(r.checked?'checked':'')+' '+(r.existing?'disabled':'')+'><strong>'+esc(r.name)+'</strong><small>'+esc(r.school||'')+' '+esc(r.grade||'')+'</small><span>'+(r.existing?'이미 보충 대상':'')+'</span><small class="assigned-preview" data-assigned-preview="'+i+'"></small></label><div class="makeup-individual" '+(isIndividual()?'':'hidden')+'>'+option('rowkind'+i,'구분',[['group','단체보충'],['individual','단일보충']],r.kind)+option('rowduration'+i,'필요 시간',durations(),r.duration)+'<label class="field"><span>준비물</span><input name="rowmaterials'+i+'" maxlength="2000" value="'+esc(r.materials)+'"></label><label class="field"><span>사유</span><input name="rowreason'+i+'" maxlength="2000" value="'+esc(r.reason)+'"></label><div class="form-grid" data-row-schedule '+(assigned()?'':'hidden')+'><label class="field"><span>날짜</span><input type="date" name="rowdate'+i+'" value="'+esc(r.date||form.elements.date.value)+'"></label><label class="field"><span>시작 시간</span><input type="time" step="1800" name="rowstart'+i+'" value="'+esc(r.start||form.elements.start.value)+'"></label></div></div></article>').join('')||'<div class="empty">이 반에 등록된 학생이 없습니다.</div>';form.querySelectorAll('[data-batch-check]').forEach(b=>b.onchange=()=>{rows[+b.dataset.batchCheck].checked=b.checked;count()});MiraeDrafts.adopt(form.querySelector('[data-batch-students]'));count()}
  function capture(){rows.forEach((r,i)=>{if(form.elements['rowduration'+i])Object.assign(r,{kind:form.elements['rowkind'+i].value,duration:Number(form.elements['rowduration'+i].value),materials:form.elements['rowmaterials'+i].value.trim(),reason:form.elements['rowreason'+i].value.trim(),date:form.elements['rowdate'+i]?.value||form.elements.date.value,start:form.elements['rowstart'+i]?.value||form.elements.start.value,checked:form.querySelector('[data-batch-check="'+i+'"]')?.checked||false})})}
