async function install(){if(standalone()){help('미래탐구 앱','<p>이미 앱으로 사용 중입니다.</p>');return}const c=installContext();if(c.needsExternal||c.ios){showInstallGuide();return}if(installEvent){const event=installEvent;installEvent=null;try{await event.prompt();const choice=await event.userChoice;if(choice.outcome!=='accepted')showInstallGuide()}catch{showInstallGuide()}paintPrompt();return}showInstallGuide()}

