 async function load(fresh=false){const tag=++generation;if(get('start').value>get('end').value){get('status').textContent='시작일과 종료일을 확인해 주세요.';return}get('status').textContent='접속 기록을 확인하고 있습니다.';get('load').disabled=true;try{await P.ensureSession();const data={start:get('start').value,end:get('end').value,roles:roles()},r=await P.rpc('activity',data,{fresh});if(r.history_version!==97||!Array.isArray(r.recent))throw Error('새 SQL94를 적용한 뒤 다시 열어 주세요.');if(!valid()||tag!==generation)return;rows=r.rows;recent=r.recent;get('status').textContent='';const max=Math.max(1,...r.daily.map(x=>Number(x.count)));get('chart').innerHTML=r.daily.map(x=>'<div title="'+esc(x.day)+' · '+x.count+'회"><i style="height:'+Math.max(3,Number(x.count)/max*100)+'%"></i><small>'+esc(x.day.slice(5).replace('-','/'))+'</small><b>'+x.count+'회</b></div>').join('');draw()}catch(e){if(valid()&&tag===generation)get('status').textContent=String(e.message||'').includes('SQL94')?e.message:'기록을 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.'}finally{if(valid()&&tag===generation)get('load').disabled=false}}
