 node.querySelectorAll('[data-history-view]').forEach(b=>b.onclick=()=>{view=b.dataset.historyView;node.querySelectorAll('[data-history-view]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))});draw()});node.querySelectorAll('[data-history-role]').forEach(x=>x.onchange=()=>{draw();void load(true)});get('query').oninput=draw;get('active').onchange=draw;get('quick').onclick=()=>{const n=Math.max(1,Math.min(3650,Number(get('days').value)||30));get('start').value=ago(n-1);get('end').value=ago(0);void load(true)};get('load').onclick=()=>load(true);get('start').onchange=get('end').onchange=()=>load(true);MiraeFastReads.subscribe(node,['mirae_portal_bridge','mirae_workflow'],()=>void load());await load();
