async function retrySite(){const st=ensure(),id=owner;if(st.busy||!st.pendingSite?.length&&!st.pendingRefresh)return;st.busy=true;st.error=null;paint();const progress=window.MiraeProgress?.begin('연락처 갱신과 저장을 마무리하는 중');try{await finishSaved(st,id,progress);if(owner!==id)return;st.error=null;st.result='최신 연락처 확인 완료 · 성공 건은 반영하고 미완료 건은 다시 저장할 수 있습니다.';progress?.done(st.result);cfg.toast(st.result)}catch(e){if(owner===id){st.error=e;st.result='엠스위치 저장 확인 · 갱신과 반영을 다시 시도해 주세요.';progress?.fail(e.message)}}finally{if(owner===id){st.busy=false;notify()}}}

