let cfg={};const P=window.MiraePush,dialogs=new Map(),E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DEFAULT='<$학생명> 학부모님. <$날짜>에 진행한 <$강좌명> · <$수업명>에 대한 수업 레포트가 발행되었습니다.';
const statuses={unrecorded:'미입력',present:'출석',late:'지각',absent:'결석',excused:'인정결석',not_arrived:'미등원',face_makeup:'대면보강',video_makeup:'영상보강',new_enrollment:'신규입반',transfer_in:'전입',transfer_out:'전출',campus_transfer:'센터 이동',withdrawn:'퇴원'};
