      const prior=window.onYouTubeIframeAPIReady;
      const timer=setTimeout(()=>{apiTask=null;reject(Error('영상에 연결하지 못했습니다. 네트워크를 확인하고 다시 열어 주세요.'));},20000);
      window.onYouTubeIframeAPIReady=()=>{try{prior?.();}catch{}clearTimeout(timer);resolve();};
      const script=document.createElement('script');script.src='https://www.youtube.com/iframe_api';script.async=true;
      script.onerror=()=>{clearTimeout(timer);apiTask=null;reject(Error('영상 재생 모듈을 불러오지 못했습니다.'));};document.head.append(script);
