    if(c.duration<1||(!c.pending.length&&!c.retry))return;
    const request=c.retry||{stream:c.stream,seq:c.seq+1,duration:Number(c.duration.toFixed(3)),position:Number(Math.min(c.position,c.duration).toFixed(3)),ranges:c.pending.splice(0,60),rate:1};
