    box.innerHTML='<section class="modal watch-dialog watch-consumer" role="dialog" aria-modal="true" aria-label="영상 시청"><header class="modal-head"><h2>'+esc(result.target.title||'수업 영상')+'</h2><button type="button" class="btn" data-watch-close>닫기</button></header><div class="modal-body"><div class="watch-stage"><div data-watch-player></div><div class="watch-touch-shield" aria-hidden="true"></div></div><div class="watch-controls"><div class="watch-seek-row"><input type="range" min="0" max="1" step="0.1" value="0" data-watch-seek disabled aria-label="재생 위치"><span data-watch-position>0:00 / 0:00</span></div><div class="watch-buttons"><button type="button" class="btn primary" data-watch-play disabled>재생</button><button type="button" class="btn" data-watch-back disabled aria-label="10초 뒤로">−10초</button><button type="button" class="btn" data-watch-forward disabled aria-label="10초 앞으로">+10초</button><button type="button" class="btn" data-watch-mute disabled>음소거</button><button type="button" class="btn" data-watch-captions disabled aria-pressed="false">자막 켜기</button><span class="watch-control-spacer"></span><small data-watch-screen-mode></small><button type="button" class="btn" data-watch-expand>전체화면</button><button type="button" class="btn watch-control-close" data-watch-close>닫기</button></div></div><p data-watch-message role="status" aria-live="polite"></p></div></section>';
    document.body.append(box);
    const c={box,dialog:box.querySelector('.watch-dialog'),who,target:result.target,source:target,recording:result.recording,stream:result.stream,progress:result.progress||{},seq:0,pending:[],retry:null,busy:null,last:null,ready:false,playing:false,closing:false,cancelled:false,blocked:false,saveFatal:false,seeking:false,duration:Number(result.progress?.duration)||0,position:0,pageFit:false,captionWanted:false,captionTrack:null,captionHasPlayed:false,keyboardControls:false,orientationRequested:false};
