async function load(){const id=MiraePush.ownerID?.()||'';if(pending)return pending;pending=call('read').then(r=>{cache=r.templates;owner=id;return r}).finally(()=>pending=null);return pending}
function format(kind,values){let value=cache[kind]||DEFAULTS[kind]||'';for(const[k,v]of Object.entries(values))value=value.replaceAll('<$'+k+'>',String(v??''));return value}
async function settings(node,cfg){node.innerHTML='<div class="page-head"><div><h1>상세설정</h1></div></div><div class="message-settings" data-template-panels></div><p data-settings-status role="status">문구를 확인하는 중</p>';try{const r=await load();if(!node.isConnected)return;node.querySelector('[data-template-panels]').innerHTML=Object.entries(LABELS).map(([kind,label],i)=>'<details class="message-template-panel" '+(!i?'open':'')+'><summary>'+label+'<span>편집 · 미리보기</span></summary><form data-template-form="'+kind+'"><label>안내 문구<textarea class="input" name="template" rows="5" maxlength="3000" required>'+esc(r.templates[kind])+'</textarea></label><div class="template-tokens">'+(kind==='task_due'?['업무내용','완료기한','발신자']:kind==='report'?['학생명','날짜','강좌명','수업명']:['attendance','not_arrived'].includes(kind)?['학생명','반명','시간','날짜']:kind.startsWith('withdrawal_')?['학생명','반명','날짜','센터','발신자','승인자','반려사유']:['학생명','반명','날짜']).map(k=>'<button class="btn sm" type="button" data-token="'+k+'">'+esc('<$'+k+'>')+'</button>').join('')+'</div><div class="template-preview"><small>미리보기</small><p class="preline" data-template-preview></p></div><div class="flex"><button class="btn" type="button" data-template-default>기본 문구</button><button class="btn primary" type="submit">문구 저장</button><span data-template-status role="status"></span></div></form></details>').join('');node.querySelector('[data-settings-status]').textContent='';
for(const form of node.querySelectorAll('[data-template-form]')){const kind=form.dataset.templateForm,text=form.elements.template;let version=r.versions[kind];const preview=()=>{let v=text.value;for(const[k,value]of Object.entries({업무내용:'수업 자료 확인',완료기한:'2026-10-15 18:30',발신자:'김담임',승인자:'이팀장',반려사유:'최종 수업일 확인 필요',센터:'수학',학생명:'김미래',반명:'중2 과학',강좌명:'중2 과학',수업명:'빛의 굴절',날짜:'2026-10-04',시간:'14시 30분'}))v=v.replaceAll('<$'+k+'>',value);form.querySelector('[data-template-preview]').textContent=v};text.oninput=preview;preview();form.querySelector('[data-template-default]').onclick=()=>{text.value=DEFAULTS[kind];preview()};form.querySelectorAll('[data-token]').forEach(b=>b.onclick=()=>{const token='<$'+b.dataset.token+'>';text.setRangeText(token,text.selectionStart,text.selectionEnd,'end');text.focus();preview()});form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]'),status=form.querySelector('[data-template-status]');button.disabled=true;try{const next=await call('save',{kind,template:text.value,version});version=next.version;cache[kind]=next.template;status.textContent='저장완료';cfg.toast?.('저장완료')}catch(e){status.textContent=/TEMPLATE_CHANGED/.test(e.message)?'다른 사람이 문구를 변경했습니다. 화면을 다시 열어 주세요.':e.message}finally{button.disabled=false}}}
}catch(e){node.querySelector('[data-settings-status]').textContent='문구를 불러오지 못했습니다. 관리자에게 문의해 주세요.'}}
