function unread(rows){setOwner();return rows.filter(c=>c.status==='requested'&&JSON.stringify(reads.get(c.id))!==JSON.stringify(snapshot(c))).length}
async function refreshConsultations(force=false){setOwner();if(!['admin','teacher'].includes(cfg.user?.()?.role)||!cfg.can?.('consultations'))return;if(refresh)return refresh;if(!force&&Date.now()-lastRefresh<15000)return;const g=generation;
 const before=new Map(reads);const task=(async()=>{try{const r=await call('mirae_consultation_reads','list');if(g!==generation)return;const next=new Map(r.rows.map(x=>[x.id,x.snapshot]));for(const[id,v]of reads)if(JSON.stringify(before.get(id))!==JSON.stringify(v))next.set(id,v);for(const[id,v]of pending)next.set(id,v);reads=next;lastRefresh=Date.now();cfg.changed?.()}catch{/* The badge still works locally if an older database has not been updated. */}})();refresh=task;try{await task}finally{if(refresh===task)refresh=null}}
async function readConsultation(c){setOwner();const g=generation,old=reads.get(c.id),value=snapshot(c);if(JSON.stringify(old)===JSON.stringify(value))return;reads.set(c.id,value);pending.set(c.id,value);cfg.changed?.();try{await call('mirae_consultation_reads','read',{id:c.id,snapshot:value});if(g===generation){pending.delete(c.id);lastRefresh=0}}catch(e){if(g===generation){old?reads.set(c.id,old):reads.delete(c.id);pending.delete(c.id);cfg.changed?.()}throw e}}
