 const area=node.querySelector('[data-update-list]');const live=()=>node.isConnected&&cfg.user()?.id===currentOwner&&node.querySelector('[data-update-list]')===area;
 function draw(){if(!live())return;const q=node.querySelector('[data-update-search]').value.trim().toLowerCase(),rows=posts.filter(p=>!q||[p.title,p.content].join(' ').toLowerCase().includes(q)).sort((a,b)=>String(a[sort]).localeCompare(String(b[sort]),'ko',{numeric:true})*direction),pages=Math.max(1,Math.ceil(rows.length/pageSize));page=Math.min(page,pages);node.querySelector('[data-update-total]').textContent=rows.length+'개 게시글';const list=node.querySelector('[data-update-list]');list.innerHTML='<table class="one-line-table resource-title-table"><thead><tr><th class="resource-number">번호</th>'+[['title','제목'],['created_at','등록일']].map(([k,l])=>'<th data-update-sort="'+k+'" tabindex="0" aria-sort="'+(sort===k?(direction===1?'ascending':'descending'):'none')+'">'+l+(sort===k?(direction===1?' ↑':' ↓'):'')+'</th>').join('')+(admin?'<th>관리</th>':'')+'</tr></thead><tbody>'+rows.slice((page-1)*pageSize,page*pageSize).map((p,i)=>'<tr class="resource-heading"><td class="resource-number">'+(rows.length-(page-1)*pageSize-i)+'</td><td><button class="resource-text resource-title" data-update-open="'+esc(p.id)+'" aria-expanded="'+opened.has(p.id)+'" aria-controls="update-'+esc(p.id)+'"><span>'+esc(p.title)+'</span><span class="resource-chevron" aria-hidden="true">⌄</span></button></td><td class="resource-date">'+day(p.created_at)+'</td>'+(admin?'<td><button class="btn sm" data-update-edit="'+esc(p.id)+'">수정</button></td>':'')+'</tr><tr class="resource-expanded"><td colspan="'+(admin?4:3)+'"><div class="resource-fold '+(opened.has(p.id)?'is-open':'')+'" id="update-'+esc(p.id)+'" '+(opened.has(p.id)?'':'inert')+'><div class="resource-fold-inner"><div class="board-detail"><p>'+esc(p.content)+'</p></div></div></div></td></tr>').join('')+'</tbody></table>'+(!rows.length?'<div class="board-empty">등록된 게시글이 없습니다.</div>':'')+'<div class="resource-pager"><span>'+rows.length+'개 게시글</span><div><button class="btn sm" data-update-prev '+(page<=1?'disabled':'')+'>이전</button><strong>'+page+' / '+pages+'</strong><button class="btn sm" data-update-next '+(page>=pages?'disabled':'')+'>다음</button></div></div>';
 list.querySelector('[data-update-prev]').onclick=()=>{page--;draw()};list.querySelector('[data-update-next]').onclick=()=>{page++;draw()};list.querySelectorAll('[data-update-sort]').forEach(b=>{const click=()=>{direction=sort===b.dataset.updateSort?-direction:1;sort=b.dataset.updateSort;page=1;draw()};b.onclick=click;b.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();click()}}});list.querySelectorAll('[data-update-edit]').forEach(b=>b.onclick=()=>edit(posts.find(p=>p.id===b.dataset.updateEdit)));list.querySelectorAll('[data-update-open]').forEach(b=>b.onclick=()=>{const id=b.dataset.updateOpen,value=!opened.has(id);value?opened.add(id):opened.delete(id);b.setAttribute('aria-expanded',String(value));const fold=list.querySelector('#update-'+id);MiraeMotion.fold(fold,value);if(value)MiraePlatform.readBoard('updates',id,posts.find(p=>p.id===id))});MiraePlatform.paintBoards();
 }
