(()=>{'use strict';let cfg={},armed=false,leaving=false,lastExit=0,exitTimer,handling=false;const key='miraeAppBack',mobile=()=>document.documentElement.classList.contains('mobile-device')||!!window.MiraePC?.isMobile,enabled=()=>mobile()&&!leaving;
function clearNote(){document.querySelectorAll('.toast').forEach(x=>{if(x.textContent==='한번 더 누르면 어플이 종료됩니다.')x.remove()})}
function arm(){if(!enabled()||armed)return;const base={...history.state,[key]:{guard:false}};history.replaceState(base,'',location.href);history.pushState({...base,[key]:{guard:true}},'',location.href);armed=true;}
function guard(){history.pushState({...history.state,[key]:{guard:true}},'',location.href);armed=true;}
function popup(){const overlays=[...document.querySelectorAll('.modal-overlay,.mc-profile-overlay')].filter(x=>x.offsetWidth||x.offsetHeight).sort((a,b)=>Number(getComputedStyle(a).zIndex||0)-Number(getComputedStyle(b).zIndex||0));const top=overlays.at(-1);if(top&&!top.closest('#modal-root')){const buttons=[...top.querySelectorAll('button')],b=buttons.find(b=>b.matches('[data-profile-close],[data-close],[data-pc-limited],[data-hw-close],[data-inbox-close],[data-video-close]')||/닫기|close|취소/i.test(b.getAttribute('aria-label')||b.textContent.trim()));if(b){b.click();return true;}}
 if(cfg.closeTop?.())return true;
 if(top){top.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));return true;}
 return false;}
function handle(){window.MiraeDrafts?.capture();if(document.fullscreenElement){document.exitFullscreen?.().catch(()=>{});return true;}if(popup())return true;if(document.body.classList.contains('menu-open')){document.body.classList.remove('menu-open');document.querySelector('.sidebar')?.classList.remove('open');return true;}const post=[...document.querySelectorAll('#main details[open]')].at(-1);if(post){post.open=false;return true;}return cfg.screenBack?.()===true;}
addEventListener('popstate',e=>{if(!enabled())return;if(!armed&&lastExit&&Date.now()-lastExit<2200){leaving=true;clearTimeout(exitTimer);return;}const marker=e.state?.[key];if(!marker){armed=false;arm();return;}e.stopImmediatePropagation();armed=false;let handled;handling=true;try{handled=handle()}finally{handling=false}if(handled){lastExit=0;clearNote();guard();return;}lastExit=Date.now();cfg.toast?.('한번 더 누르면 어플이 종료됩니다.');clearTimeout(exitTimer);exitTimer=setTimeout(()=>{if(enabled()&&!armed){lastExit=0;clearNote();guard();}},2200);},true);
for(const event of ['pointerdown','keydown'])document.addEventListener(event,()=>{if(enabled()&&!armed){lastExit=0;clearTimeout(exitTimer);clearNote();arm();}},{passive:true});
window.MiraeBack={VERSION:'261027_2',enabled,configure(c){cfg=c;arm()},reset(){lastExit=0;clearTimeout(exitTimer);clearNote();if(!handling)arm()},get state(){return{armed,leaving,lastExit}}};
})();

