(()=>{'use strict';
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const definitions={
 classes:{label:'담당반',target:'평가 기간에 겹치는 담당·부담임 강좌 수',done:'그중 진행 중 상태인 강좌 수',high:'실제 운영 중인 강좌의 운영 상태와 개강·종강일을 정확히 관리하세요.',low:'평가 기간에 종강·중지 상태의 강좌가 포함되면 이 항목의 달성률이 낮아질 수 있습니다.'},
 lessons:{label:'수업기록',target:'휴강을 제외한 실제 수업일 수',done:'수업기록을 등록한 서로 다른 수업일 수',high:'실제 수업일마다 수업기록을 남기세요. 같은 날짜의 기록을 여러 개 만들어도 달성률은 늘지 않습니다.',low:'실제 진행한 수업일에 수업기록이 빠진 경우 점수가 낮아집니다.'},
 exams:{label:'시험',target:'휴강을 제외한 실제 수업일 수',done:'시험을 등록한 서로 다른 시험일 수',high:'평가자가 정한 시험 운영 주기에 맞춰 시험 기록을 관리하세요.',low:'현재 계산은 수업일 수를 시험 목표로 사용합니다. 매회 시험을 진행하지 않는 과목은 평가자가 이 항목 비율을 조정하는 것이 적절합니다.'},
 scores:{label:'성적',target:'조회 기간 중 수업이 있는 주 수 · 월요일~일요일',done:'시험을 1회 이상 등록한 주 수',high:'수업이 있는 주마다 1회 이상 시험을 등록하세요.',low:'해당 주에 시험이 없을 때만 낮아집니다. 학생의 미응시·성적 미입력은 점수를 낮추지 않습니다.'},
 comments:{label:'코멘트',target:'등록된 수업기록별 해당 날짜의 수강 학생 수 합계',done:'공란이 아닌 코멘트를 입력한 수업·학생 조합 수',high:'수업마다 학생별로 확인할 수 있는 구체적인 코멘트를 남기세요.',low:'수업기록은 있지만 학생별 코멘트가 비어 있는 조합이 많을수록 점수가 낮아집니다.'},
 attendance:{label:'출결',target:'실제 수업일별 해당 날짜의 수강 학생 수 합계',done:'공란이 아닌 출결을 저장한 날짜·학생 조합 수',high:'수강 기간 안의 모든 실제 수업일에 출결을 기록하세요. 결석도 기록하면 입력 실적에 포함됩니다.',low:'출석부의 미입력 칸이 남아 있으면 점수가 낮아집니다. 수강 기간 밖의 신규입반·전입·전출 표시는 입력 실적에 넣지 않습니다.'},
 plans:{label:'강의계획',target:'휴강을 제외한 실제 수업일 수',done:'수업내용이 입력된 강의계획서 수업일 수',high:'실제 수업일별 강의계획서의 수업내용을 작성하고 저장하세요.',low:'강의계획서의 날짜만 있거나 수업내용이 비어 있으면 점수가 낮아집니다.'},
 recent:{label:'최근입력',target:'담당·부담임 강좌 수',done:'각 강좌의 최근성 점수 합계: max(0, 1 − 경과일 ÷ 30)',high:'실제 수업·시험·학생 기록을 수업 흐름에 맞춰 꾸준히 갱신하세요.',low:'마지막 갱신 후 매일 최근성 점수가 줄어듭니다. 30일 이상 갱신이 없는 강좌의 최근성은 0입니다. 최근 시각에는 강좌 설정 갱신도 포함됩니다.'}
};
const num=x=>x==null?'—':Number(x).toFixed(1).replace(/\.0$/,''),max=(row,w,k)=>{const den=Object.keys(w).reduce((s,p)=>s+(Number(row.expected?.[p])>0?Number(w[p]):0),0);return den&&Number(row.expected?.[k])>0?Number(w[k])*100/den:0};
function dialog(title,html){document.querySelector('[data-score-guide-overlay]')?.remove();const focused=document.activeElement,box=document.createElement('div');box.className='modal-overlay score-guide-overlay';box.dataset.scoreGuideOverlay='';box.innerHTML='<section class="modal score-guide-modal" role="dialog" aria-modal="true" aria-labelledby="score-guide-title"><header class="modal-head"><h2 id="score-guide-title">'+E(title)+'</h2><button type="button" class="btn" data-score-close>닫기</button></header><div class="modal-body">'+html+'</div></section>';document.body.append(box);document.body.classList.add('modal-open');const close=()=>{box.remove();document.removeEventListener('keydown',keys,true);if(!document.querySelector('.modal-overlay'))document.body.classList.remove('modal-open');if(focused?.isConnected)focused.focus()};const keys=e=>{if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();close()}if(e.key==='Tab'){const els=[...box.querySelectorAll('button,a,input,select,textarea')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}};document.addEventListener('keydown',keys,true);box.querySelector('[data-score-close]').onclick=close;box.querySelector('button').focus();return box}
function method(k,w,rows=[]){const d=definitions[k];if(!d)return;const low=rows.filter(r=>Number(r.expected?.[k])>0&&Number(r.rates?.[k])<100).sort((a,b)=>(a.rates[k]??0)-(b.rates[k]??0)).slice(0,3);dialog(d.label+' · 평가방식','<div class="score-formula">기여점수 = min(실적 ÷ 대상, 1) × 적용 배점</div><dl class="score-definition"><div><dt>평가 대상</dt><dd>'+E(d.target)+'</dd></div><div><dt>입력 실적</dt><dd>'+E(d.done)+'</dd></div><div><dt>설정 비율</dt><dd>'+num(w[k])+'%</dd></div></dl><p>대상이 있는 항목의 비율 합계를 100점으로 환산합니다. 대상이 없는 항목의 비율은 나머지 항목에 재분배됩니다.</p><section class="score-advice"><h3>고득점하려면</h3><p>'+E(d.high)+'</p></section><section class="score-advice"><h3>점수가 낮아지는 이유</h3><p>'+E(d.low)+'</p></section>'+(low.length?'<section class="score-low-list"><h3>현재 확인할 입력 현황</h3>'+low.map(r=>'<div><strong>'+E(r.name)+'</strong><span>실적 '+num(r.done?.[k])+' / 대상 '+num(r.expected?.[k])+' · '+num(r.rates[k])+'%</span></div>').join('')+'</section>':''))}
function course(c,period={}){const w=c.weights||{},keys=Object.keys(definitions),missing=keys.map(k=>({k,left:max(c,w,k)-Number(c.points?.[k]||0)})).filter(x=>x.left>.05).sort((a,b)=>b.left-a.left).slice(0,3);dialog(c.name+' · 점수 구성','<div class="score-total-detail"><strong>'+num(c.score)+'<small>점</small></strong><span>'+E(period.start||'')+' ~ '+E(period.end||'')+'</span></div><p class="score-formula">총점 = 각 항목의 기여점수 합계</p><div class="score-parts-detail">'+keys.map(k=>{const m=max(c,w,k),rate=c.rates?.[k],d=definitions[k];return '<article><header><strong>'+d.label+'</strong><span>기준 '+num(w[k])+'% · 적용 '+num(m)+'점</span></header><div class="score-part-values"><span>실적 '+num(c.done?.[k])+' / 대상 '+num(c.expected?.[k])+'</span><b>'+num(c.points?.[k])+' / '+num(m)+'점</b></div><div class="score-progress"><i style="width:'+Math.max(0,Math.min(100,Number(rate)||0))+'%"></i></div><small>'+(rate==null?'평가 대상 없음 · 배점 재분배':'달성률 '+num(rate)+'%')+'</small></article>'}).join('')+'</div><section class="score-advice"><h3>고득점하려면</h3>'+(missing.length?missing.map(({k})=>'<p><strong>'+definitions[k].label+'</strong> · '+E(definitions[k].high)+'</p>').join(''):'<p>대상이 있는 항목을 모두 채웠습니다. 실제 수업에 맞춰 기록을 이어가세요.</p>')+'</section>')}
window.MiraeScoreGuide={method,course,definitions};
})();

