function fitPrint(doc){for(const sheet of doc.querySelectorAll('.print-sheet')){const area=sheet.querySelector('.print-area'),table=sheet.querySelector('table');let size=8,pad=1.4;for(let i=0;i<12;i++){const scale=Math.min(1,area.clientHeight/table.getBoundingClientRect().height,area.clientWidth/table.scrollWidth);if(scale>.998)break;size*=scale*.975;pad*=scale*.9;table.style.setProperty('--size',size+'pt');table.style.setProperty('--pad',pad+'mm')}sheet.dataset.fits=String(table.getBoundingClientRect().height<=area.clientHeight+1&&table.scrollWidth<=area.clientWidth+1)}}
