 result.push({id:w.processed_by,number:'✓',name:'상담실 처리',actor:rejected?reject?.actor_name:process?.actor_name,status:rejected?'반려':w.status==='processed'||w.status==='cancelled'?'처리 완료':w.status==='ready'?'근무자 확인 대기':'승인 후 진행',tone:rejected?'rejected':process||w.status==='processed'||w.status==='cancelled'?'done':w.status==='ready'?'current':'',at:rejected?reject?.at:process?.at||w.processed_at||null,note:rejected?reject?.note||'':'',finished:rejected||w.status==='processed'||w.status==='cancelled'});
