function options(rows,value='',blank=''){return(blank?'<option value="">'+E(blank)+'</option>':'')+rows.map(([k,v])=>'<option value="'+E(k)+'" '+(k===value?'selected':'')+'>'+E(v)+'</option>').join('')}
function modal(title,html,key){const n=cfg.modal(title,html);MiraeDrafts.actions(n);if(key){n.querySelector('.modal').dataset.draftKey=key;n.querySelector('.modal').dataset.modelKey=key}return n}
function formDraft(n,key,initial={}){const f=n.querySelector('form'),data={...initial,...MiraeDrafts.getModel(key)};for(const el of f.elements){el.dataset.draftIgnore='';if(el.name&&data[el.name]!==undefined)el.type==='checkbox'?el.checked=!!data[el.name]:el.value=data[el.name]}function save(){MiraeDrafts.setModel(key,Object.fromEntries([...f.elements].filter(e=>e.name&&e.type!=='submit'&&(e.type!=='radio'||e.checked)).map(e=>[e.name,e.type==='checkbox'?e.checked:e.value])))}f.addEventListener('input',save);f.addEventListener('change',save);n.querySelector('.modal')._draftCapture=save;return {f,data,save}}
