const person=(w,id)=>w.approver_people?.find(p=>p.id===id)?.name||cfg.base().accounts?.find(p=>p.id===id)?.name||'지정 승인자';
function progress(w){return '<ol class="cw-progress">'+MiraeWithdrawalTimeline.rows(w).map(r=>'<li class="'+E(r.tone)+'"><span>'+E(r.number)+'</span><strong>'+E(r.name||person(w,r.id))+(r.actor?' <em>'+E(r.actor)+'</em>':'')+'</strong><small>'+E(r.status)+(r.finished?' · '+(r.at?'<time datetime="'+E(r.at)+'">'+E(stamp(r.at))+'</time>':'시각 미기록'):'')+'</small>'+(r.note?'<p class="cw-step-note">'+E(r.note)+'</p>':'')+'</li>').join('')+'</ol>'}
