 async function save(e){e.preventDefault();if(busy||!dirty.size||!node.querySelector('[data-sg-form]').reportValidity())return;const current=selected,rows=[...dirty.values()],id=owner;busy=true;const controls=[...node.querySelectorAll('.sg-period input,.sg-period select,[data-sg-form] input,[data-sg-form] button')].map(x=>[x,x.disabled]);controls.forEach(([x])=>x.disabled=true);updateSave();node.querySelector('[data-sg-error]').textContent='';status('저장 중');try{const r=await rpc('save',{...period,class_id:current,rows});if(id!==identity()||disposed)return;const map=entryMap(data);for(const x of r.entries)map.set(key(x.student_id,x.subject),x);data.entries=[...map.values()];dirty.clear();MiraeDrafts.clearModel(draftKey());cache.set(period.year+'|'+period.term,{at:Date.now(),data:clone(data)});drawClasses();reconcile();status('저장 완료');window.MiraeGradeHistory?.invalidate();cfg.toast?.('성적을 저장했습니다.')}catch(ex){if(disposed)return;node.querySelector('[data-sg-error]').textContent=error(ex);status('저장되지 않았습니다.',true);if(/GRADE_CHANGED|GRADE_OTHER_AUTHOR|GRADE_CLASS_CLOSED|GRADE_SCOPE/.test(ex.message))await load(true)}finally{busy=false;controls.forEach(([x,v])=>{if(x.isConnected)x.disabled=v});updateSave()}}
