 ids=ids||[...document.querySelectorAll('[data-phone-review]')].map(b=>b.dataset.phoneReview);
 const fresh=!!MiraeMSCache.snapshot&&!MiraeMSCache.snapshot._stale&&MiraeMSCache.fresh();const op=window.MiraeProgress?.begin('엠스위치 연락처',{running:'최신 연락처 확인 중',failed:'연락처 갱신 확인 필요'});
