/* School terms, not insertion order, define comparison. No-exam never means zero. */
(()=>{'use strict';let cfg={},owner='',cache=new Map(),pending=new Map();const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),TERMS={'1_mid':'1학기 중간','1_final':'1학기 기말','2_mid':'2학기 중간','2_final':'2학기 기말'},ORDER=Object.keys(TERMS),BASIS={math:'수학',science:'과학',combined:'수학·과학 합계'};
const family=()=>['student','parent'].includes(cfg.user?.()?.role);
function identity(){const id=cfg.user?.()?.id||'';if(id!==owner){owner=id;cache.clear();pending.clear()}return id}
function periods(entries){const map=new Map();for(const e of entries){if(e.status==='blank')continue;const k=e.exam_year+'|'+e.exam_term;if(!map.has(k))map.set(k,{year:e.exam_year,term:e.exam_term,label:e.exam_year+' '+TERMS[e.exam_term]});map.get(k)[e.subject]=e}return[...map.values()].sort((a,b)=>a.year-b.year||ORDER.indexOf(a.term)-ORDER.indexOf(b.term))}
function trend(entries,basis){const ps=periods(entries).filter(p=>basis==='combined'||p[basis]),latest=ps.at(-1);if(!latest)return{tone:'empty',label:'입력 전',detail:BASIS[basis]+' 기준'};const val=p=>basis==='combined'?(p.math?.status==='score'&&p.science?.status==='score'?Number(p.math.score)+Number(p.science.score):null):p[basis]?.status==='score'?Number(p[basis].score):null,v=val(latest);if(v===null){const no=basis==='combined'?[latest.math,latest.science].every(x=>x?.status==='no_exam'):latest[basis]?.status==='no_exam';return{tone:'empty',label:no?'시험 없음':'입력 확인 중',detail:latest.label+' · '+BASIS[basis]}}const prior=ps.slice(0,-1).filter(p=>val(p)!==null).at(-1);if(!prior)return{tone:'new',label:'새로 입력 · '+v+'점',detail:latest.label+' · '+BASIS[basis]};const delta=Math.round((v-val(prior))*100)/100;return{tone:delta>0?'up':delta<0?'down':'same',label:delta>0?'↑ '+delta+'점 상승':delta<0?'↓ '+Math.abs(delta)+'점 하락':'변동 없음',detail:BASIS[basis]+' · '+prior.label+' '+val(prior)+' → '+latest.label+' '+v+'점'}}
function badge(sid,basis=cfg.basis?.()||'combined'){if(family())return '';return'<button type="button" class="grade-history-badge" data-school-history="'+E(sid)+'" data-grade-basis="'+E(basis)+'"><strong>확인 중</strong><small>'+BASIS[basis]+' 기준</small></button>'}
function update(){for(const b of document.querySelectorAll('[data-school-history]')){const item=cache.get(b.dataset.schoolHistory),t=item?.error?{tone:'error',label:'다시 확인',detail:'내신 기록을 불러오지 못했습니다.'}:item?trend(item.entries,b.dataset.gradeBasis):{tone:'empty',label:'확인 중',detail:BASIS[b.dataset.gradeBasis]+' 기준'};b.className='grade-history-badge gh-'+t.tone;b.querySelector('strong').textContent=t.label;b.querySelector('small').textContent=BASIS[b.dataset.gradeBasis]+' 기준';b.title=t.detail+' · 전체 내신성적 보기'}}
async function read(ids,force=false){if(family())return;const id=identity();ids=[...new Set(ids)].filter(Boolean);const want=ids.filter(s=>force||!cache.has(s)||Date.now()-cache.get(s).at>20000);if(!want.length){update();return}const key=want.sort().join('|');if(pending.has(key))return pending.get(key);const task=(async()=>{try{const auth=await MiraePush.ensureSession();for(let i=0;i<want.length;i+=500){const part=want.slice(i,i+500),r=await MiraeStore.rpc('mirae_school_grade_history',{p_session:auth.session,p_data:{student_ids:part}});if(identity()!==id)return;for(const sid of part)cache.set(sid,{entries:r.entries.filter(e=>e.student_id===sid),at:Date.now()})}update()}catch(e){if(identity()===id){for(const sid of want)cache.set(sid,{error:e.message,entries:[],at:Date.now()});update()}}finally{pending.delete(key)}})();pending.set(key,task);return task}
function paint(){if(family())return;identity();const ids=[...document.querySelectorAll('[data-school-history]')].map(x=>x.dataset.schoolHistory);update();if(ids.length)void read(ids)}
async function open(sid){if(family())return;const id=identity(),s=cfg.student(sid),wrap=cfg.modal((s.name||'학생')+' · 내신성적','<div class="gh-loading">내신성적을 확인하는 중입니다.</div>','',{wide:true});await read([sid],true);if(!wrap.isConnected||identity()!==id)return;const item=cache.get(sid),box=wrap.querySelector('.modal-body');if(item?.error){box.innerHTML=MiraeStates.empty('내신성적을 불러오지 못했습니다.',/mirae_school_grade_history|PGRST202/.test(item.error)?'관리자에게 문의해 주세요.':item.error);return}const ps=periods(item?.entries||[]),cell=(p,sub)=>{const e=p[sub];return e?.status==='score'?'<strong>'+E(e.score)+'<small>점</small></strong><i class="gh-track '+sub+'"><b style="width:'+Number(e.score)+'%"></b></i>':'<span class="gh-muted">'+(e?.status==='no_exam'?'시험 없음':'입력 전')+'</span>'};box.innerHTML='<div class="gh-intro"><div><strong>'+E(s.name)+'</strong><span>'+E([s.school,s.grade].filter(Boolean).join(' · '))+'</span></div><span class="gh-legend"><i></i>수학 <i></i>과학</span></div>'+(ps.length?'<div class="gh-table" role="table"><div class="gh-row gh-heading" role="row"><span>시험</span><span>수학</span><span>과학</span></div>'+ps.map(p=>'<div class="gh-row" role="row"><div><strong>'+p.year+'</strong><span>'+TERMS[p.term]+'</span></div><div>'+cell(p,'math')+'</div><div>'+cell(p,'science')+'</div></div>').join('')+'</div>':MiraeStates.empty('아직 입력된 내신성적이 없습니다.','성적이 등록되면 수학·과학 기록을 함께 볼 수 있습니다.'))+'<span role="button" tabindex="0" class="ui-help72" aria-label="도움말 설명 보기" data-help-title72="도움말" data-help72="시험 순서대로 표시합니다. 시험 없음은 0점으로 계산하지 않습니다. 수학·과학 합계는 두 과목 점수가 모두 있는 시험끼리 비교합니다." >?</span>'}
document.addEventListener('click',e=>{const b=e.target.closest('[data-school-history]');if(b){e.preventDefault();e.stopPropagation();void open(b.dataset.schoolHistory)}},true);
window.MiraeGradeHistory={configure(c){cfg=c},paint,badge,open,trend,periods,invalidate(){cache.clear();paint()}};
})();

