async function loadClasses(force=false){if(classTask)return classTask;if(!force&&classes.length)return classes;const who=owner,era=epoch;const p=job('classes',{refresh:force,include_future:force}).then(r=>{if(owner===who&&epoch===era){classes=r.classes||[];codes=r.codes||[];classTime=r.fetched_at;onDemand89=r.on_demand===true;if(force){searches89.clear();searchStates89.clear()}if(r.partial)mark('일부 날짜별 반을 확인하지 못했습니다. 명단 갱신으로 다시 확인할 수 있습니다.',true)}return r.classes||[]}).finally(()=>{if(classTask===p)classTask=null});classTask=p;return p}
async function roster(c,force=false){const k=key(c),hit=rosters.get(k);if(!force&&hit)return hit;if(rosterTasks.has(k))return rosterTasks.get(k);const who=owner,era=epoch;const p=job('students',{center:c.ACAD_CD,class:c.CLASS_CD,refresh:force}).then(r=>{if(owner===who&&epoch===era){rosters.set(k,r);directory=directory.filter(s=>key(s)!==k).concat(r.students||[]);indexDirectory()}return r}).finally(()=>{if(rosterTasks.get(k)===p)rosterTasks.delete(k)});rosterTasks.set(k,p);return p}
function currentClass(){return classes.find(c=>key(c)===selected)}
function currentStudents(){return [...(rosters.get(selected)?.students||[])].sort((a,b)=>Number(withdrawn(a))-Number(withdrawn(b))||nameOrder.compare(a.NM||'',b.NM||'')||nameOrder.compare(a.SCH_NM||'',b.SCH_NM||'')||nameOrder.compare(a.STD_NO||'',b.STD_NO||''))}
function stamp(t){if(!t)return '미조회';const d=new Date(t);return Number.isNaN(+d)?'미조회':d.toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Seoul'})}
function mark(text,bad=false){if(!node?.isConnected)return;const n=node.querySelector('[data-tn-state]');if(n){n.innerHTML=(!bad&&text?'<span class="state-spinner"></span>':'')+'<span>'+E(text)+'</span>';n.classList.toggle('tn-alert',bad)}paintTimes()}
function button(label,attr,primary=false){return'<button type="button" class="btn '+(primary?'primary':'')+'" '+attr+'>'+label+'</button>'}
const refreshGlyph='<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M16 7a6.3 6.3 0 1 0 .2 5M16 3v4h-4"/></svg>';
function paintTimes(){if(!node?.isConnected)return;for(const [type,value]of [['directory',directoryTime],['history',historyTime]]){const b=node.querySelector('[data-refresh-'+type+']');if(!b)continue;const busy=type==='directory'?(initializing>0||!!directoryTask||!!classTask):historyRefreshing||historyTasks.size>0||rosterTasks.size>0;const disabled=saving||busy||(type==='history'&&(view==='history'?!currentClass():!drafts.get('all')?.rows.some(r=>matchRow(r))));b.querySelector('time').textContent=busy?'불러오는 중':stamp(value);b.classList.toggle('is-loading',busy);b.setAttribute('aria-busy',String(busy));b.title=busy?'정보를 가져오고 있습니다.':value?new Date(value).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})+' · 다시 갱신':'다시 갱신';b.disabled=disabled}}

function fitWorkspace(){if(!node?.isConnected)return;const nav=document.querySelector('.mobile-app-nav'),rect=nav?.getBoundingClientRect(),bottom=rect&&rect.height>0&&getComputedStyle(nav).position==='fixed'?Math.max(0,innerHeight-rect.top):0;node.style.height=Math.max(220,innerHeight-Math.max(0,node.getBoundingClientRect().top)-bottom)+'px'}
window.addEventListener('resize',()=>requestAnimationFrame(fitWorkspace));window.addEventListener('mirae-pc-state',()=>requestAnimationFrame(fitWorkspace));
async function refreshHistory(){if(saving||historyRefreshing)return;if(view==='history'){const c=currentClass(),content=node?.querySelector('[data-tn-content]');if(!c||!content)return;historyRefreshing=true;paintTimes();try{await ensureRecency(c,content,true);if(selected===key(c))await showHistory(currentStudents().find(s=>s.STD_NO===student),c,true)}finally{historyRefreshing=false;paintTimes()}return}const targets=new Map();for(const row of draft().rows){const r=resolveRow(row);if(r.class&&r.student)targets.set(key(r.class)+'|'+r.student.STD_NO,{c:r.class,s:r.student})}if(!targets.size)return;const list=[...targets.entries()],who=owner,era=epoch;historyRefreshing=true;paintTimes();let at=0;try{await Promise.all(Array.from({length:Math.min(3,list.length)},async()=>{while(at<list.length){const [k,{c,s}]=list[at++];const r=await job('history',{center:c.ACAD_CD,class:c.CLASS_CD,student_no:s.STD_NO});if(owner!==who||epoch!==era)return;histories.set(k,r);historyTime=r.fetched_at}}));mark('')}catch(e){mark(error(e),true)}finally{if(owner===who&&epoch===era){historyRefreshing=false;paintTimes()}}}
function mount(el){identity();MiraeCounselOverview.configure({...cfg,rpc,job});if(!cfg.can('consultation_edit'))view='history';node=el;serial++;node.innerHTML='<div class="tn-module" data-draft-ignore><header class="tn-heading"><div><h1>타임넷 상담 기록</h1><span class="tn-state" data-tn-state role="status"></span></div><div class="tn-head-actions"><button class="tn-refresh-chip" data-refresh-directory><span>타임넷 명단</span><time></time>'+refreshGlyph+'</button><button class="tn-refresh-chip" data-refresh-history><span>상담 기록</span><time></time>'+refreshGlyph+'</button>'+button('개인 타임넷 연결','data-tn-account')+'</div></header><div class="tn-tabs"><div class="seg-tabs" role="tablist" aria-label="상담기록 메뉴">'+(cfg.can('consultation_edit')?'<button role="tab" data-tn-tab="write">타임넷 상담 기록</button>':'')+'<button role="tab" data-tn-tab="history">상담 조회</button>'+(cfg.can('counsel_overview')?'<button role="tab" data-tn-tab="overview">종합상담취합</button>':'')+'</div><span class="tn-inline-status" data-tn-directory-count></span></div><div class="tn-workspace"><aside class="tn-classes"><div class="tn-side-title"><strong>타임넷 반</strong><span data-tn-class-count></span></div><input class="input" type="search" data-tn-class-query placeholder="반 검색" aria-label="반 검색"><div data-tn-classes></div></aside><section class="tn-content" data-tn-content></section></div></div>';
 node.querySelector('[data-tn-account]').onclick=openAccount;node.querySelector('[data-tn-class-query]').oninput=drawClasses;node.querySelector('[data-refresh-directory]').onclick=()=>void initialize(true);node.querySelector('[data-refresh-history]').onclick=()=>void refreshHistory();node.querySelectorAll('[data-tn-tab]').forEach(b=>b.onclick=()=>{view=b.dataset.tnTab;drawContent();if(view!=='overview'&&!directoryTime)void initialize();else if(view==='history'&&selected&&!rosters.has(selected))void chooseClass(selected)});paintConnection();drawClasses();drawContent();requestAnimationFrame(fitWorkspace);void initialize();
}
async function loadDirectory(force=false){if(directoryTask)return directoryTask;if(!force&&directoryTime)return directory;const who=owner,era=epoch;const p=job('students',{}, {progress:p=>mark(p)}).then(r=>{if(owner!==who||epoch!==era)return[];directory=r.students||[];indexDirectory();directoryTime=r.fetched_at;rosters.clear();for(const c of classes){const rows=directory.filter(s=>s.ACAD_CD===c.ACAD_CD&&s.CLASS_CD===c.CLASS_CD);if(!onDemand89||rows.length)rosters.set(key(c),{students:rows,fetched_at:directoryTime,recency_checked:true})};return directory}).finally(()=>{if(directoryTask===p)directoryTask=null;paintTimes()});directoryTask=p;paintTimes();return p}
async function initialize(force=false){if(saving||view==='overview')return;const who=owner,era=epoch,el=node;initializing++;mark('타임넷 명단을 가져오는 중');try{const a=await getAccount(force);if(owner!==who||epoch!==era||el!==node||!el.isConnected)return;if(!a.configured){mark('');if(view==='overview')return;node.querySelector('[data-tn-content]').innerHTML=empty('본인의 타임넷 계정을 연결해 주세요.','연결을 마치면 학생 이름으로 상담을 기록할 수 있습니다.')+'<div class="tn-empty-action">'+button('개인 타임넷 연결','data-connect',true)+'</div>';node.querySelector('[data-connect]').onclick=openAccount;return}if(view==='overview')return;if(!directoryTime)node.querySelector('[data-tn-content]').innerHTML='<div class="tn-loading" role="status"><span class="state-spinner"></span><strong>타임넷 학생 명단을 가져오는 중</strong></div>';await start(force);if(view==='overview')return;if(owner!==who||epoch!==era||el!==node||!el.isConnected)return;if(!classes.some(c=>key(c)===selected))selected=classes[0]?key(classes[0]):'';drawClasses();drawContent();mark('')}catch(e){if(el===node&&owner===who&&epoch===era){mark(error(e),true);if(!directoryTime&&view!=='overview')node.querySelector('[data-tn-content]').innerHTML=empty('타임넷 명단을 확인하지 못했습니다.',error(e))}}finally{if(owner===who&&epoch===era){initializing=Math.max(0,initializing-1);paintTimes()}}}
function drawClasses(){if(!node?.isConnected)return;const q=node.querySelector('[data-tn-class-query]').value.trim().toLowerCase();node.querySelector('[data-tn-class-count]').textContent=classes.length+'개';const list=node.querySelector('[data-tn-classes]');const rows=classes.filter(c=>(c.CLASS_NM+' '+c.HM_TCHR_NM).toLowerCase().includes(q));list.innerHTML=rows.length?rows.map(c=>'<button class="tn-class '+(key(c)===selected?'active':'')+'" data-class="'+E(key(c))+'" title="'+E(c.CLASS_NM)+'"><span>'+E(c.CLASS_NM)+'</span><small>'+E(c.HM_TCHR_NM||c.GRD_NM)+'</small></button>').join(''):empty(classes.length?'일치하는 반이 없습니다.':'조회된 반이 없습니다.');list.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>void chooseClass(b.dataset.class))}
