function saveOverlay(total,resume){document.querySelector('.tn-save-overlay')?.remove();const el=document.createElement('div');el.className='tn-save-overlay';el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');el.setAttribute('aria-labelledby','tn-save-title');el.innerHTML='<section class="tn-save-panel"><div class="tn-save-orbit"><span></span><b data-save-count>0<small> / '+total+'</small></b></div><h2 id="tn-save-title">'+(resume?'저장 결과 확인 중':'상담 저장 중')+'</h2><p data-save-label role="status">전송을 준비하고 있습니다.</p><div class="tn-save-track"><i></i></div><div class="tn-save-totals" data-save-totals></div><button class="btn" data-save-background>화면으로 돌아가기</button></section>';document.body.append(el);el.querySelector('[data-save-background]').onclick=()=>el.remove();el.querySelector('button').focus();const progress=(label,p={})=>{batchStatus(label,true);if(!el.isConnected)return;const done=Number(p.done)||0;el.querySelector('[data-save-count]').innerHTML=done+'<small> / '+total+'</small>';el.querySelector('[data-save-label]').textContent=p.total?'':label;const totals=el.querySelector('[data-save-totals]');totals.innerHTML=[['saved','저장'],['unknown','확인 필요'],['failed','실패']].filter(([k])=>Number(p[k])>0).map(([k,t])=>'<span class="'+k+'">'+t+' <b>'+Number(p[k])+'</b></span>').join('');el.querySelector('.tn-save-track i').style.width=Math.min(100,done/total*100)+'%'};return{progress,remove(){el.remove()}}}
async function saveBatch(d,resume=false){if(saving)return;const who=owner,era=epoch,k='all';if(!resume){if(!cfg.can('consultation_edit'))return;const matches=d.rows.map(resolveRow);if(matches.some(x=>!x.student||!x.class)||d.rows.some(r=>!r.content.trim()))return cfg.toast('학생·수강반·상담 내용을 확인해 주세요.',true);if(!(await MiraeDialog.confirm(d.rows.length+'명의 상담을 타임넷에 기록할까요?')))return;d.request={id:uuid(),payload:{items:d.rows.map((r,i)=>({row_id:r.id,center:matches[i].class.ACAD_CD,class:matches[i].class.CLASS_CD,student_no:matches[i].student.STD_NO,name:matches[i].student.NM,date:r.date,time:r.time,method:r.method,target:r.target,type:r.type,detail:r.detail,content:r.content}))}};remember()}saving=true;drawContent();const overlay=saveOverlay(d.rows.length,resume);batchOps.get(k)?.remove();const op=MiraeProgress.begin('타임넷 상담기록',{running:resume?'상담 결과 확인 중':'타임넷 상담 저장 중',done:'상담 저장 완료',failed:'상담 결과 확인 필요'});batchOps.set(k,op);const progress=(text,p={})=>{overlay.progress(text,p);op.update({...p,status_text:text})};try{let r;if(resume){const status=await rpc('status',{id:d.request.id});if(['queued','running'].includes(status.state))r=await job('save',{}, {id:d.request.id,statusOnly:true,progress});else if(status.result?.ok&&!(status.result.items||[]).some(r=>r.state==='unknown'))r=status.result;else r=await job('reconcile',{source_id:d.request.id},{progress})}else r=await job('save',d.request.payload,{id:d.request.id,progress});if(owner!==who||epoch!==era)return;for(const row of d.rows)row.result=(r.items||[]).find(i=>i.row_id===row.id)||{state:'unknown',message:'결과를 확인하지 못했습니다.'};for(const row of d.rows){if(row.result.state==='saved'){const item=d.request?.payload.items.find(x=>x.row_id===row.id);if(item)markSaved(item)}}const count=d.rows.filter(r=>r.result.state==='saved').length,unknown=d.rows.some(r=>r.result.state==='unknown'),failed=d.rows.filter(r=>['error','failed'].includes(r.result.state)).length;const defaults=d.rows.at(-1);if(!unknown){d.request=null;d.rows=d.rows.filter(r=>r.result.state!=='saved');if(!d.rows.length)d.rows=[newRow(defaults)]}remember();histories.clear();historyTime=r.fetched_at||new Date().toISOString();const text=count+'명 저장 완료'+(failed?' · '+failed+'명 입력 확인 필요':unknown?' · 일부 결과 확인 필요':'');if(unknown||failed){op.fail(text);op.setDetail(text)}else op.done(text);batchStatus(text);cfg.toast(text,!!failed)}catch(e){if(owner===who&&epoch===era){if(e.definitive){d.request=null;remember()}op.fail(error(e));op.setDetail(error(e));batchStatus(error(e));cfg.toast(error(e),true)}}finally{overlay.remove();if(owner===who&&epoch===era){saving=false;const text=node?.querySelector('[data-batch-status]')?.textContent;drawContent();if(text)batchStatus(text)}}}

function dateNumber(value){const v=String(value||'').replace(/-/g,'').slice(0,8);if(!/^\d{8}$/.test(v))return null;const y=+v.slice(0,4),m=+v.slice(4,6),d=+v.slice(6,8),t=Date.UTC(y,m-1,d);const check=new Date(t);return check.getUTCFullYear()===y&&check.getUTCMonth()===m-1&&check.getUTCDate()===d?t:null}
function recency(s,today=MiraeAttendanceCore.korea().date){if(withdrawn(s))return{label:'퇴원',tone:'withdrawn',title:'퇴원 · 상담 기록 조회'};if(s.recency_state!=='ready')return{label:s.recency_state==='error'?'확인 필요':'확인 중',tone:'pending',title:'내 마지막 상담 확인'};if(!s.last_counsel_date)return{label:'내 기록 없음',tone:'none',title:'내 상담 기록 없음'};const at=dateNumber(s.last_counsel_date),now=dateNumber(today);if(at===null||now===null)return{label:'확인 필요',tone:'pending',title:'상담 날짜 확인 필요'};const days=Math.floor((now-at)/86400000),tone=days>=60?'purple':days>=30?'red':days>=15?'orange':'recent';return{label:days<0?'예정':days===0?'오늘':days+'일 전',tone,title:'내 마지막 상담 '+String(s.last_counsel_date).replace(/^(\d{4})(\d{2})(\d{2})$/,'$1.$2.$3')}}
function markSaved(item){const k=item.center+'|'+item.class,date=item.date.replace(/-/g,'');for(const s of [...directory,...(rosters.get(k)?.students||[])])if(key(s)===k&&s.STD_NO===item.student_no&&!withdrawn(s)){if(s.recency_state==='ready')s.last_counsel_date=[s.last_counsel_date||'',date].sort().at(-1);else{const hit=rosters.get(k);if(hit)hit.recency_checked=false}}}
async function ensureRecency(c,content,force=false){const k=key(c),hit=rosters.get(k);if(!force&&hit?.recency_checked)return;try{const r=await roster(c,true);if(content.isConnected&&selected===k&&view==='history'){historyTime=r.fetched_at;paintTimes();content._paintMembers?.()}}catch(e){if(selected===k){for(const s of hit?.students||[])if(!withdrawn(s))s.recency_state='error';content._paintMembers?.();mark(error(e),true)}}}
