async function showHistory(s,c,force=false){if(!s||!c)return;const target=node.querySelector('[data-history]'),k=key(c)+'|'+s.STD_NO,who=owner,era=epoch;const paint=r=>{if(!target.isConnected||selected!==key(c)||student!==s.STD_NO)return;target.innerHTML='<div class="tn-history-title"><div><h2>'+E(s.NM)+'</h2><span>'+E(s.SCH_NM)+' · '+E(s.GRD_NM)+'</span></div><span class="tn-sync">'+E(stamp(r.fetched_at))+'</span></div>'+(r.records.length?'<div class="tn-timeline">'+r.records.map(r=>'<article class="tn-record"><div class="tn-record-head"><strong>'+E(String(r.CNSL_DT).replace(/^(\d{4})(\d{2})(\d{2})$/,'$1.$2.$3'))+'</strong><span>'+E(r.CNSL_PSN_EMP_NM)+'</span><small>'+E(String(r.CNSL_TM).slice(0,4).replace(/^(\d{2})(\d{2})$/,'$1:$2'))+'</small></div><div class="tn-record-tags">'+[r.CNSL_MTHD_NM,r.CNSL_OBJ_NM,r.CNSL_DETAIL_TYPE_NM||r.CNSL_TYPE_NM].filter(Boolean).map(t=>'<span>'+E(t)+'</span>').join('')+'</div><p>'+E(r.CNSL_CONT)+'</p>'+(r.CLASS_NM?'<small class="tn-record-class">'+E(r.CLASS_NM)+'</small>':'')+'</article>').join('')+'</div>':empty('상담 기록이 없습니다.'))};const hit=histories.get(k);if(hit){paint(hit);historyTime=hit.fetched_at;paintTimes();if(!force)return;}else target.innerHTML='<div class="tn-loading" role="status"><span class="state-spinner"></span><strong>상담 이력 수신 중</strong></div>';mark('최신 상담 이력 확인 중');try{if(!historyTasks.has(k)){const p=job('history',{center:c.ACAD_CD,class:c.CLASS_CD,student_no:s.STD_NO}).finally(()=>{if(historyTasks.get(k)===p)historyTasks.delete(k);paintTimes()});historyTasks.set(k,p);paintTimes()}const r=await historyTasks.get(k);if((owner!==who||epoch!==era))return;histories.set(k,r);if(selected===key(c)&&student===s.STD_NO)historyTime=r.fetched_at;paintTimes();paint(r);if(selected===key(c)&&student===s.STD_NO)mark('')}catch(e){if(target.isConnected&&selected===key(c)&&student===s.STD_NO){mark(error(e),true);if(!hit)target.innerHTML=empty('상담 이력을 확인하지 못했습니다.',error(e))}}}
