async function xlsx(c){const Zip=await MiraeShiftImport.zipLibrary(),z=new Zip(),rs=rows(c),text=(v,ref,style=0)=>'<c r="'+ref+'" t="inlineStr" s="'+style+'"><is><t xml:space="preserve">'+xml(v)+'</t></is></c>';
z.file('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>');
z.file('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
z.file('xl/workbook.xml','<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="강의계획서" sheetId="1" r:id="rId1"/></sheets><definedNames><definedName name="_xlnm.Print_Titles" localSheetId="0">\'강의계획서\'!$1:$5</definedName></definedNames></workbook>');
z.file('xl/_rels/workbook.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');
const palettes=['253B32','B33F42','3262A6','397650'];z.file('xl/styles.xml','<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="8">'+[false,true].flatMap(b=>palettes.map(co=>'<font><sz val="11"/><name val="맑은 고딕"/><color rgb="FF'+co+'"/>'+(b?'<b/>':'')+'</font>')).join('')+'</fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="8">'+Array.from({length:8},(_,i)=>'<xf numFmtId="0" fontId="'+i+'" fillId="0" borderId="0" xfId="0" applyFont="1" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf>').join('')+'</cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>');
const title=[c.name+' · 강의계획서','담당강사 '+(c.teacher_name||'미배정'),c.start_date+' ~ '+c.end_date+' · 실제 수업 '+rs.filter(r=>!r.holiday).length+'회'];z.file('xl/worksheets/sheet1.xml','<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetPr><pageSetUpPr fitToPage="1"/></sheetPr><sheetViews><sheetView workbookViewId="0"><pane ySplit="5" topLeftCell="A6" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="1" width="8" customWidth="1"/><col min="2" max="2" width="16" customWidth="1"/><col min="3" max="3" width="65" customWidth="1"/><col min="4" max="4" width="28" customWidth="1"/></cols><sheetData>'+title.map((t,i)=>'<row r="'+(i+1)+'">'+text(t,'A'+(i+1),4)+'</row>').join('')+'<row r="5">'+['회차','수업일','수업내용','비고'].map((v,i)=>text(v,'ABCD'[i]+'5',4)).join('')+'</row>'+rs.map((r,i)=>{const n=i+6,style=Math.max(0,Object.keys(colors).indexOf(r.color||'black'))+(r.bold?4:0);return'<row r="'+n+'">'+[r.sequence,r.date,r.holiday?'휴강':r.content||'',r.holiday?r.holiday_reason||'':r.note||''].map((v,j)=>text(v,'ABCD'[j]+n,style)).join('')+'</row>'}).join('')+'</sheetData><mergeCells count="3"><mergeCell ref="A1:D1"/><mergeCell ref="A2:D2"/><mergeCell ref="A3:D3"/></mergeCells><pageMargins left="0.4" right="0.4" top="0.5" bottom="0.5" header="0.2" footer="0.2"/><pageSetup paperSize="9" orientation="portrait" fitToWidth="1" fitToHeight="0"/></worksheet>');return z.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',compression:'DEFLATE'})}
async function canvases(c){await document.fonts.ready;const pages=[],width=1240,height=1754,left=64,right=1176,bottom=1660,line=32;let canvas,ctx,y;const font=(bold=false)=>{ctx.font=(bold?'700':'400')+' 24px MiraeSans,"Malgun Gothic",sans-serif'},wrap=(text,w)=>{const lines=[];for(const raw of String(text??'').split('\n')){let buf='';for(const ch of raw){if(buf&&ctx.measureText(buf+ch).width>w){lines.push(buf);buf=''}buf+=ch}lines.push(buf)}return lines};
function page(){canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.fillStyle='#253b32';ctx.font='700 36px MiraeSans,"Malgun Gothic",sans-serif';const names=wrap(c.name,1112);names.forEach((t,i)=>ctx.fillText(t,left,90+i*44));y=115+names.length*44;font();ctx.fillStyle='#62736a';ctx.fillText('담당강사 '+(c.teacher_name||'미배정'),left,y);ctx.fillText(c.start_date+' ~ '+c.end_date+' · 실제 수업 '+rows(c).filter(r=>!r.holiday).length+'회',left,y+38);y+=75;ctx.fillStyle='#edf3ee';ctx.fillRect(left,y,1112,55);ctx.fillStyle='#315141';font(true);['회차','수업일','수업내용','비고'].forEach((t,i)=>ctx.fillText(t,[76,160,340,950][i],y+36));y+=55;pages.push(canvas)}
page();for(const r of rows(c)){font(r.bold);let content=wrap(r.holiday?'휴강':r.content||'',590),note=wrap(r.holiday?r.holiday_reason||'':r.note||'',214),offset=0,total=Math.max(content.length,note.length);while(offset<total){if(bottom-y<58)page();const count=Math.max(1,Math.min(total-offset,Math.floor((bottom-y-20)/line))),h=Math.max(58,count*line+20);ctx.fillStyle=r.holiday?'#f4f5f2':'#fff';ctx.fillRect(left,y,1112,h);ctx.fillStyle=r.holiday?'#859087':colors[r.color||'black'];font(r.bold);if(!offset){ctx.fillText(String(r.sequence),76,y+34);ctx.fillText(r.date,160,y+34)}for(let i=0;i<count;i++){ctx.fillText(content[offset+i]||'',340,y+34+i*line);ctx.fillText(note[offset+i]||'',950,y+34+i*line)}ctx.strokeStyle='#dce4dc';ctx.beginPath();ctx.moveTo(left,y+h);ctx.lineTo(right,y+h);ctx.stroke();y+=h;offset+=count;if(offset<total)page()}await new Promise(r=>setTimeout(r,0))}
pages.forEach((p,i)=>{const g=p.getContext('2d');g.fillStyle='#738277';g.font='20px MiraeSans,"Malgun Gothic",sans-serif';g.fillText('미래탐구 · 강의계획서',left,1710);g.fillText((i+1)+' / '+pages.length,1080,1710)});return pages}
function pdf(pages){const parts=[],offsets=[0];let position=0;const put=v=>{const b=typeof v==='string'?enc.encode(v):v;parts.push(b);position+=b.length},obj=(id,body)=>{offsets[id]=position;put(id+' 0 obj\n');put(body);put('\nendobj\n')};put('%PDF-1.4\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Count '+pages.length+' /Kids ['+pages.map((_,i)=>(3+i*3)+' 0 R').join(' ')+'] >>');pages.forEach((canvas,i)=>{const n=3+i*3,data=Uint8Array.from(atob(canvas.toDataURL('image/jpeg',.94).split(',')[1]),c=>c.charCodeAt(0)),stream='q 595.28 0 0 841.89 0 0 cm /Im0 Do Q';obj(n,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im0 '+(n+1)+' 0 R >> >> /Contents '+(n+2)+' 0 R >>');offsets[n+1]=position;put((n+1)+' 0 obj\n<< /Type /XObject /Subtype /Image /Width '+canvas.width+' /Height '+canvas.height+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+data.length+' >>\nstream\n');put(data);put('\nendstream\nendobj\n');obj(n+2,'<< /Length '+enc.encode(stream).length+' >>\nstream\n'+stream+'\nendstream')});const xref=position;put('xref\n0 '+offsets.length+'\n0000000000 65535 f \n');for(const n of offsets.slice(1))put(String(n).padStart(10,'0')+' 00000 n \n');put('trailer\n<< /Size '+offsets.length+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF');return new Blob(parts,{type:'application/pdf'})}
async function open(id){const owner=cfg.user()?.id,n=cfg.modal('강의계획서','<div class="sl-loading" role="status"><span class="state-spinner"></span>강의계획서를 불러오는 중</div>');try{const r=await call('detail',{id});if(!n.isConnected||owner!==cfg.user()?.id)return;const body=n.querySelector('.modal-body')||n.querySelector('.modal-content');body.innerHTML='<div class="sl-exportbar"><span role="status" data-sl-export-state></span><button class="btn" data-sl-export="pdf">PDF</button><button class="btn" data-sl-export="png">PNG</button><button class="btn" data-sl-export="xlsx">XLSX</button><button class="btn sl-print" data-sl-export="print">출력하기</button></div><article class="sl-paper">'+summary(r.class)+table(r.class)+'</article>';body.querySelectorAll('[data-sl-export]').forEach(b=>b.onclick=async()=>{const buttons=[...body.querySelectorAll('button')],status=body.querySelector('[data-sl-export-state]');buttons.forEach(x=>x.disabled=true);status.innerHTML='<span class="state-spinner"></span>파일 준비 중';try{const {class:c}=await call('detail',{id}),type=b.dataset.slExport,name=c.name+'_강의계획서';if(type==='print')await print(c);else if(type==='xlsx')download(await xlsx(c),name+'.xlsx');else{const pages=await canvases(c);if(type==='pdf')download(pdf(pages),name+'.pdf');else if(pages.length===1)download(await new Promise(resolve=>pages[0].toBlob(resolve,'image/png')),name+'.png');else{const Zip=await MiraeShiftImport.zipLibrary(),z=new Zip();for(let i=0;i<pages.length;i++)z.file(name+'_'+String(i+1).padStart(2,'0')+'.png',await new Promise(resolve=>pages[i].toBlob(resolve,'image/png')));download(await z.generateAsync({type:'blob'}),name+'_PNG.zip')}}status.textContent='준비 완료'}catch(e){status.textContent=message(e)}finally{buttons.forEach(x=>x.disabled=false)}})}catch(e){if(n.isConnected)(n.querySelector('.modal-body')||n.querySelector('.modal-content')).innerHTML=MiraeStates.empty('강의계획서를 확인하지 못했습니다.',message(e))}}
async function mount(node){const owner=cfg.user()?.id;node.innerHTML='<div class="page-head"><h1>강의계획서 모아보기</h1><span class="badge" data-sl-count></span></div><section class="sl-library"><div class="sl-filter">'+Object.entries(labels).map(([k,l])=>'<label class="check-label"><input type="checkbox" data-sl-state="'+k+'" '+(k!=='ended'?'checked':'')+'>'+l+'</label>').join('')+'</div><div class="sl-search"><input class="input" type="search" data-sl-query placeholder="반명 검색" aria-label="반명 검색"><input class="input" type="search" data-sl-teacher placeholder="강사명 검색" aria-label="강사명 검색"></div><div data-sl-results><div class="sl-loading" role="status"><span class="state-spinner"></span>강좌를 불러오는 중</div></div></section>';const target=node.querySelector('[data-sl-results]');try{const r=await call('list');if(!target.isConnected||node.querySelector('[data-sl-results]')!==target||owner!==cfg.user()?.id)return;const paint=()=>{const state=new Set([...node.querySelectorAll('[data-sl-state]:checked')].map(x=>x.dataset.slState)),q=node.querySelector('[data-sl-query]').value.trim().toLocaleLowerCase(),t=node.querySelector('[data-sl-teacher]').value.trim().toLocaleLowerCase(),list=r.rows.filter(c=>state.has(c.state)&&c.name.toLocaleLowerCase().includes(q)&&c.teacher_name.toLocaleLowerCase().includes(t));node.querySelector('[data-sl-count]').textContent=list.length+'개 강좌';node.querySelector('[data-sl-results]').innerHTML=list.length?'<div class="sl-list-scroll"><table class="sl-list"><thead><tr>'+['반명','담당강사','개강일','종강일','실제 수업',''].map(t=>'<th>'+t+'</th>').join('')+'</tr></thead><tbody>'+list.map(c=>'<tr><td><strong>'+E(c.name)+'</strong><span class="sl-state">'+labels[c.state]+'</span></td><td>'+E(c.teacher_name||'미배정')+'</td><td>'+E(c.start_date)+'</td><td>'+E(c.end_date)+'</td><td>'+c.lesson_count+'회</td><td><button class="btn sm" data-sl-open="'+E(c.id)+'">강의계획서 보기</button></td></tr>').join('')+'</tbody></table></div>':MiraeStates.empty('일치하는 강좌가 없습니다.');node.querySelectorAll('[data-sl-open]').forEach(b=>b.onclick=()=>void open(b.dataset.slOpen))};node.querySelectorAll('input').forEach(x=>x.addEventListener(x.type==='checkbox'?'change':'input',paint));paint()}catch(e){if(target.isConnected&&node.querySelector('[data-sl-results]')===target)target.innerHTML=MiraeStates.empty('강의계획서를 불러오지 못했습니다.',message(e))}}
window.MiraeSyllabusLibrary={configure(c){cfg=c},mount,rows,xlsx,canvases,pdf};
