/* roster-integrity.261027_2.js */
(()=>{'use strict';
let cfg={},owner='',generation=0,pending=null,timer;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kinds={enrollments:'수강 이력',attendance:'출결',feedback:'수업 평가',scores:'시험 성적',school_grades:'내신성적',consultations:'상담',submissions:'숙제',video_progress:'영상 시청'};
const labels={date:'날짜',joined_on:'첫 수업일',left_on:'마지막 수업일',status:'상태',score:'점수',absent:'미응시',homework_grade:'과제 평가',attendance:'출결',comment:'코멘트',private_note:'강사 메모',note:'메모',reason:'상담 내용',staff_reply:'답변',content:'제출 내용',link:'첨부 주소',exam_year:'연도',exam_term:'시험',subject:'과목',position_seconds:'시청 위치',duration_seconds:'영상 길이'};
const values={present:'출석',late:'지각',absent:'결석',enrolled:'수강 중',inactive:'이전 배정',completed:'완료',withdrawn:'퇴원',transfer_in:'전입',transfer_out:'전출',unrecorded:'공란',score:'점수 입력',no_exam:'시험 없음',blank:'공란',math:'수학',science:'과학','1_mid':'1학기 중간','1_final':'1학기 기말','2_mid':'2학기 중간','2_final':'2학기 기말',submitted:'제출 완료',requested:'신청',scheduled:'예정',cancelled:'취소'};
function reset(){owner='';generation++;pending=null;clearTimeout(timer)}
async function rpc(action,data={}){const auth=await MiraePush.ensureSession();return MiraeStore.rpc('mirae_roster_integrity',{p_session:auth.session,p_action:action,p_data:data})}
async function settle(g){if(g!==generation||cfg.user()?.id!==owner)return;if(cfg.busy()){timer=setTimeout(()=>{void settle(g).catch(e=>{if(g===generation)MiraeFastReads.report('학생 목록 갱신',e)})},500);return}await cfg.reload();}
function start(){const u=cfg.user();if(!u||!['teacher','admin'].includes(u.role)||owner===u.id)return pending;owner=u.id;const g=++generation;
 pending=rpc('login').then(async r=>{if(g!==generation||cfg.user()?.id!==u.id)return;
  if(r.changed){MiraeFastReads.invalidate();MiraeStore.lastRefresh=0;await settle(g)}
  if(r.issues?.length)MiraeFastReads.report('학생 중복 확인',Error(r.issues.map(x=>x.name+' · '+x.reason).join('\n')));
 }).catch(e=>{if(g===generation)MiraeFastReads.report('학생 중복 확인',e)}).finally(()=>{if(g===generation)pending=null});return pending;
}
async function history(sid){cfg.modal('기록 통합 이력','<div class="workspace-loading" role="status"><span class="activity-orb"></span><span>기록을 불러오는 중</span></div>','');const node=cfg.editor().node,g=generation;
 try{const r=await rpc('history',{student_id:sid});if(!node.isConnected||g!==generation)return;const body=node.querySelector('.modal-body');const seen=new Set(),rows=r.rows.filter(x=>{const key=JSON.stringify([x.kind,x.record]);if(seen.has(key))return false;seen.add(key);return true});
  body.innerHTML=rows.length?'<div class="merge-history-list">'+rows.map(x=>{const fields=Object.entries(labels).filter(([k])=>x.record[k]!==undefined&&x.record[k]!==null&&x.record[k]!=='');return '<article><header><strong>'+esc(kinds[x.kind]||'기록')+'</strong><span>'+esc(cfg.className(x.class_id)||'')+'</span></header><dl>'+fields.map(([k,l])=>'<div><dt>'+l+'</dt><dd>'+esc(values[x.record[k]]??(typeof x.record[k]==='boolean'?(x.record[k]?'예':'아니오'):x.record[k]))+'</dd></div>').join('')+'</dl></article>'}).join('')+'</div>':'<div class="board-empty"><strong>통합된 기록이 없습니다.</strong></div>';
 }catch(e){if(node.isConnected)node.querySelector('.modal-body').innerHTML='<div class="alert" role="alert">'+esc(e.message)+'</div>'}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-merge-history]');if(b){e.preventDefault();void history(b.dataset.mergeHistory)}});
window.MiraeRosterIntegrity={configure(c){cfg=c},start,reset,history};
})();

