/* admissions.261027_2.js */
(()=>{'use strict';
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const subjects={math:'수학',science:'주말과학',gifted:'영재',science_high:'과고'},today=()=>MiraeAttendanceCore.korea().date,stamp=x=>new Date(x).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
let cfg={},generation=0,context=null;
function allowed(){return ['admin','teacher'].includes(cfg.user?.()?.role)&&(cfg.can?.('admission_receive')||MiraeCounsel.context()?.counselor===true)}
async function call(action,data={},fresh=false){const auth=await MiraePush.ensureSession();return MiraeStore.rpc('mirae_admissions',{p_session:auth.session,p_action:action,p_data:data},{fresh})}
function error(e){const m=String(e.message||e);return /ADMISSION_FORBIDDEN/.test(m)?'입학 테스트 권한이 없습니다. 권한 또는 상담실 근무자 지정을 확인해 주세요.':/ADMISSION_RECIPIENT/.test(m)?'수신자의 권한·담당 과목이 변경되었습니다. 화면을 다시 열어 주세요.':/ADMISSION_CHANGED/.test(m)?'같은 전송 요청의 내용이 변경되었습니다. 화면을 다시 열어 주세요.':/ADMISSION_INPUT/.test(m)?'입력 내용과 수신 대상자 1~3명을 확인해 주세요.':m}
function modal(title,html,key){const n=cfg.modal(title,html);n.querySelector('.modal').dataset.draftKey=key;MiraeDrafts.actions(n);return n}
async function mount(node){const owner=cfg.user()?.id,g=generation;let rows=[],offset=0,more=false,request=0;node.innerHTML='<div class="page-head"><h1>입학 테스트</h1><button class="btn primary" data-admission-create hidden>결과 보내기</button></div><p data-admission-status role="status">불러오는 중입니다.</p><section class="section"><form class="admission-toolbar"><label>시작일<input class="input" type="date" name="start" value="'+new Date(Date.now()-30*86400000).toISOString().slice(0,10)+'" required></label><label>종료일<input class="input" type="date" name="end" value="'+today()+'" required></label><label>과목<select class="input" name="subject"><option value="">전체 과목</option>'+Object.entries(subjects).map(([k,l])=>'<option value="'+k+'">'+l+'</option>').join('')+'</select></label><label>학생 · 학교 · 테스트지<input class="input" name="query" maxlength="200" placeholder="검색"></label><label class="check-label"><input type="checkbox" name="confirmed_only" value="true">입반 확정자만 조회</label><button class="btn" type="submit">조회</button></form><p class="muted" data-admission-scope></p><div class="platform-kpis" data-admission-summary></div><div class="admission-list" data-admission-list></div><div class="compact-filters"><button class="btn" data-admission-prev>이전</button><span data-admission-page></span><button class="btn" data-admission-next>다음</button></div></section>';
const valid=()=>g===generation&&node.isConnected&&cfg.user()?.id===owner,status=x=>{if(valid())node.querySelector('[data-admission-status]').textContent=x};
async function load(){const seq=++request,f=node.querySelector('form');status('불러오는 중입니다.');try{const r=await call('list',{...Object.fromEntries(new FormData(f)),offset,limit:50},true);if(!valid()||seq!==request)return;rows=r.rows;more=r.more;node.querySelector('[data-admission-list]').dataset.listStart=String(offset+1);status('');node.querySelector('[data-admission-summary]').innerHTML=[['전체 입학 테스트',r.total+'건'],['입반 확정',r.confirmed+'건'],['입반 확정 비율',r.confirmed_rate+'%']].map(([k,v])=>'<article><span>'+k+'</span><strong>'+v+'</strong></article>').join('');node.querySelector('[data-admission-list]').innerHTML=rows.map(t=>'<button type="button" class="admission-row" data-admission-id="'+E(t.id)+'"><span><strong>'+E(stamp(t.created_at).split(' ').slice(0,3).join(' '))+'</strong><small>'+E(subjects[t.subject])+'</small></span><span><strong>'+E(t.student_name)+' · '+E(t.school)+' '+E(t.grade)+'</strong><small>'+E(t.test_type)+' · '+E(t.sender_name)+' → '+E(t.recipients.map(r=>r.name).join(', '))+'</small><small>댓글 '+t.replies.length+'건'+(t.confirmed_at?' · 입반 확정':'')+'</small></span><span class="admission-score"><strong>'+E(t.score)+'점</strong><small>상세 보기</small></span></button>').join('')||'<div class="empty">해당 기간의 입학 테스트가 없습니다.</div>';node.querySelectorAll('[data-admission-id]').forEach(b=>b.onclick=()=>detail(b.dataset.admissionId,load));node.querySelector('[data-admission-prev]').disabled=offset===0;node.querySelector('[data-admission-next]').disabled=!more;node.querySelector('[data-admission-page]').textContent=(offset/50+1)+'페이지'}catch(e){status(error(e))}}
node.querySelector('form').onsubmit=e=>{e.preventDefault();offset=0;load()};node.querySelector('[data-admission-prev]').onclick=()=>{offset=Math.max(0,offset-50);load()};node.querySelector('[data-admission-next]').onclick=()=>{offset+=50;load()};
try{context=await call('context',{},true);if(!valid())return;node.querySelector('[data-admission-create]').hidden=!context.can_send;node.querySelector('[data-admission-create]').onclick=()=>compose(load);node.querySelector('[data-admission-scope]').textContent=(context.can_all||context.counselor?'모든 과목의 입학 테스트':'본인 과목의 모든 입학 테스트')+' · 날짜별 최신순, 같은 날짜는 과목별로 표시합니다. 확정 비율은 조회 기간·과목·검색 조건의 전체 건수를 기준으로 계산합니다.';await load();const id=new URL(location.href).searchParams.get('item');if(valid()&&id&&/^[0-9a-f-]{36}$/i.test(id))await detail(id,load)}catch(e){status(error(e))}}
function compose(refresh){const n=modal('입학 테스트 결과 보내기','<form data-admission-form><input type="hidden" name="id" value="'+crypto.randomUUID()+'"><div class="form-grid"><label class="field"><span>학생명</span><input class="input" name="student_name" maxlength="100" required></label><label class="field"><span>학교명</span><input class="input" name="school" maxlength="100" required></label><label class="field"><span>학년</span><select class="input" name="grade">'+['초5','초6','중1','중2','중3'].map(g=>'<option>'+g+'</option>').join('')+'</select></label><label class="field"><span>과목</span><select class="input" name="subject">'+Object.entries(subjects).map(([k,l])=>'<option value="'+k+'">'+l+'</option>').join('')+'</select></label><label class="field"><span>테스트지 종류</span><input class="input" name="test_type" maxlength="120" required></label><label class="field"><span>테스트지 성적</span><input class="input" type="number" min="0" max="1000000" step="any" name="score" required></label></div><label class="field"><span>상세 내용</span><textarea class="input" name="detail" rows="4" maxlength="5000" required></textarea></label><fieldset><legend>수신 대상자 · 1~3명</legend><div class="admission-recipients">'+context.recipients.map(r=>'<label data-admission-person="'+E(r.id)+'"><input type="checkbox" name="recipients" value="'+E(r.id)+'">'+E(r.name)+'</label>').join('')+'</div><p class="muted" data-admission-count></p></fieldset><p class="inline-error" data-admission-error role="alert"></p><div data-dialog-actions><button class="btn primary" type="submit">결과 보내기</button></div></form>','admission-compose');const f=n.querySelector('form');
function people(){let count=0;for(const label of n.querySelectorAll('[data-admission-person]')){const r=context.recipients.find(x=>x.id===label.dataset.admissionPerson),c=label.querySelector('input'),visible=r.subjects.includes(f.elements.subject.value)||r.subjects.includes('all');label.hidden=!visible;c.disabled=!visible;if(!visible)c.checked=false;if(c.checked)count++}n.querySelector('[data-admission-count]').textContent=count+' / 3명 선택 · 선택한 과목의 수신 권한이 있는 직원만 표시합니다.';return count}
f.elements.subject.onchange=people;n.querySelectorAll('[name=recipients]').forEach(c=>c.onchange=()=>{if(people()>3){c.checked=false;people();cfg.toast('수신 대상자는 최대 3명입니다.',true)}});people();setTimeout(people,0);
f.onsubmit=async e=>{e.preventDefault();if(f.dataset.busy||!f.reportValidity())return;if(people()<1||people()>3){n.querySelector('[data-admission-error]').textContent='수신 대상자를 1~3명 선택하세요.';return}const owner=cfg.user()?.id;f.dataset.busy='1';cfg.busy(true,n);n.querySelector('[type=submit]').disabled=true;try{const d=Object.fromEntries(new FormData(f));d.score=Number(d.score);d.recipient_ids=[...f.querySelectorAll('[name=recipients]:checked')].map(x=>x.value);delete d.recipients;await call('create',d);if(cfg.user()?.id!==owner)return;MiraeDrafts.clear(n);cfg.close();cfg.toast('입학 테스트 결과를 보냈습니다.');await refresh()}catch(e){if(n.isConnected)n.querySelector('[data-admission-error]').textContent=error(e)}finally{delete f.dataset.busy;cfg.busy(false,n);n.querySelector('[type=submit]').disabled=false}}}
async function detail(id,refresh){const owner=cfg.user()?.id;try{const r=await call('read',{id},true);if(owner!==cfg.user()?.id)return;const t=r.test,n=modal(t.student_name+' · 입학 테스트','<div class="admission-detail-grid">'+[['학생',t.student_name],['학교 · 학년',t.school+' '+t.grade],['과목 · 테스트지',subjects[t.subject]+' · '+t.test_type],['성적',t.score+'점'],['등록',t.sender_name+' · '+stamp(t.created_at)],['수신자',t.recipients.map(x=>x.name).join(', ')]].map(([k,v])=>'<div><small>'+E(k)+'</small><strong>'+E(v)+'</strong></div>').join('')+'</div><div class="admission-description">'+E(t.detail)+'</div>'+(t.confirmed_at?'<p class="badge">입반 확정 · '+E(t.confirmed_name)+' · '+E(stamp(t.confirmed_at))+'</p>':r.can_confirm?'<p><button class="btn primary" data-admission-confirm>입반 확정</button><span class="inline-error" data-confirm-error></span></p>':'')+'<h3>댓글</h3><div class="admission-thread">'+t.replies.map(x=>'<article class="admission-reply"><header><strong>'+E(x.author_name)+'</strong><time>'+E(stamp(x.created_at))+'</time></header><p>'+E(x.content)+'</p></article>').join('')+(!t.replies.length?'<span role="button" tabindex="0" class="ui-help72" aria-label="도움말 설명 보기" data-help-title72="도움말" data-help72="아직 댓글이 없습니다." >?</span>':'')+'</div>'+(r.can_reply?'<form data-admission-reply><input type="hidden" name="id" value="'+crypto.randomUUID()+'"><label class="field"><span>댓글 작성</span><textarea class="input" name="content" rows="3" maxlength="5000" required></textarea></label><span role="button" tabindex="0" class="ui-help72" aria-label="도움말 설명 보기" data-help-title72="도움말" data-help72="상담실 댓글은 수신자에게, 수신자 댓글은 현재 근무 중인 상담실 직원 모두에게 앱푸시로 알립니다. 근무자가 없으면 상담실 직원의 다음 로그인 시 받은 알림에 표시합니다." >?</span><p class="inline-error" data-admission-error role="alert"></p><div data-dialog-actions><button class="btn primary" type="submit">댓글 보내기</button></div></form>':''),'admission-reply-'+id);
n.querySelector('[data-admission-confirm]')?.addEventListener('click',async e=>{const b=e.currentTarget;b.disabled=true;cfg.busy(true,n);try{await call('confirm',{id:t.id,version:t.version});if(owner!==cfg.user()?.id)return;cfg.busy(false,n);cfg.close();cfg.toast('입반을 확정했습니다.');if(refresh)await refresh();await detail(id,refresh)}catch(e){n.querySelector('[data-confirm-error]').textContent=error(e);b.disabled=false}finally{cfg.busy(false,n)}});const f=n.querySelector('form');if(f)f.onsubmit=async e=>{e.preventDefault();if(f.dataset.busy||!f.reportValidity())return;f.dataset.busy='1';cfg.busy(true,n);n.querySelector('[type=submit]').disabled=true;try{await call('reply',{id:f.elements.id.value,test_id:id,content:f.elements.content.value});if(owner!==cfg.user()?.id)return;MiraeDrafts.clear(n);cfg.close();cfg.toast('댓글을 보냈습니다.');if(refresh)await refresh();await detail(id,refresh)}catch(e){if(n.isConnected)n.querySelector('[data-admission-error]').textContent=error(e)}finally{delete f.dataset.busy;cfg.busy(false,n);n.querySelector('[type=submit]').disabled=false}}}catch(e){cfg.toast(error(e),true)}}
function openURL(url){const u=new URL(url,location.href);if(u.origin!==location.origin||u.searchParams.get('screen')!=='admissions')return;history.replaceState(history.state,'',u.href);cfg.navigate('admissions')}
window.MiraeAdmissions={VERSION:'261027_2',allowed,mount,openURL,configure(c){cfg=c},reset(){generation++;context=null}};
})();

