(()=>{'use strict';const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function normalize(v){v=String(v||'').trim();if(/^\d{3,4}$/.test(v))v=v.padStart(4,'0').slice(0,2)+':'+v.padStart(4,'0').slice(2);if(/^\d{1,2}:\d{2}$/.test(v))v=v.padStart(5,'0');return v}
function valid(v){return /^(09|1\d|2[01]):[0-5]0$|^22:00$/.test(v)}
function html(f,v){return '<div class="course-time"><input class="input" type="text" inputmode="numeric" name="'+f.key+'" value="'+E(v)+'" placeholder="09:00" maxlength="5" required autocomplete="off" aria-label="'+E(f.label)+'"><button class="btn" type="button" data-time-open aria-label="'+E(f.label)+' 선택">시간 선택</button><div class="course-time-picker" hidden><strong>오전 9시 ~ 오후 10시 · 10분 단위</strong><div class="course-time-hours">'+Array.from({length:14},(_,i)=>i+9).map(h=>'<button type="button" data-time-hour="'+h+'">'+String(h).padStart(2,'0')+'시</button>').join('')+'</div><div class="course-time-minutes">'+[0,10,20,30,40,50].map(m=>'<button type="button" data-time-minute="'+m+'">'+String(m).padStart(2,'0')+'분</button>').join('')+'</div></div></div>'}
function mount(form,prior={}){form.querySelectorAll('.course-time').forEach(box=>{const input=box.querySelector('input'),panel=box.querySelector('.course-time-picker');let hour=Number(input.value.split(':')[0])||9;function paint(){box.querySelectorAll('[data-time-hour]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.timeHour)===hour));box.querySelectorAll('[data-time-minute]').forEach(b=>b.disabled=hour===22&&Number(b.dataset.timeMinute)!==0)}box.querySelector('[data-time-open]').onclick=()=>{panel.hidden=!panel.hidden;paint()};box.querySelectorAll('[data-time-hour]').forEach(b=>b.onclick=()=>{hour=Number(b.dataset.timeHour);paint();if(hour===22)choose(0)});box.querySelectorAll('[data-time-minute]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.timeMinute)));function choose(minute){input.value=String(hour).padStart(2,'0')+':'+String(minute).padStart(2,'0');input.setCustomValidity('');input.dispatchEvent(new Event('input',{bubbles:true}));panel.hidden=true;input.focus()}input.onblur=()=>{input.value=normalize(input.value);input.setCustomValidity(!input.value||valid(input.value)||input.value===prior[input.name]?'':'09:00~22:00 사이의 10분 단위 시간을 입력하세요.')};input.oninput=()=>input.setCustomValidity('');input.addEventListener('keydown',e=>{if(e.key==='Escape'){panel.hidden=true;e.stopPropagation()}});paint()})}
function validate(form,prior={}){for(const input of form.querySelectorAll('.course-time input')){input.value=normalize(input.value);if(!valid(input.value)&&input.value!==prior[input.name])throw Error('수업 시간은 09:00~22:00 사이에서 10분 단위로 입력하세요.')}}
window.MiraeTimeInput={html,mount,valid,normalize,validate};
})();

