async function open(sid,cid=''){const actor=identity();if(!staff())return;let rows;try{rows=visible(await read([sid],true),cid)}catch(e){return cfg.toast?.(e.message,true)}if(identity()!==actor)return;const student=cfg.base?.()?.students?.find(s=>s.id===sid),box=document.createElement('div');box.className='modal-overlay membership-remove67';box.style.zIndex='1600';box.innerHTML='<section class="modal" role="dialog" aria-modal="true" aria-label="원생 삭제 · 반에서 제거"><header class="modal-head"><h2>'+E(student?.name||'학생')+' · 원생 삭제</h2><button class="btn" data-membership-close>닫기</button></header><form class="modal-body"><p>제거할 반을 선택하세요. <b>학생·학부모 계정과 다른 반의 배정은 보존</b>합니다. 퇴원으로 집계하지 않습니다.</p><div class="membership-choices">'+rows.map(r=>'<label><input type="radio" name="enrollment" value="'+E(r.id)+'" required '+(!r.can_remove?'disabled':'')+'><span><strong>'+E(r.class_name)+'</strong><small>'+E(r.reason||'이 반의 수강 배정만 해제')+'</small></span></label>').join('')+'</div><p class="inline-error" data-membership-error role="alert"></p><div data-dialog-actions><button class="btn danger" type="submit">선택한 반에서 제거</button></div></form></section>';document.body.append(box);const options=[...box.querySelectorAll('[name=enrollment]:not(:disabled)')];if(options.length===1)options[0].checked=true;if(!options.length)box.querySelector('[type=submit]').disabled=true;box.querySelector('[data-membership-close]').onclick=()=>box.remove();box.querySelector('form').onsubmit=async e=>{e.preventDefault();if(!e.target.reportValidity())return;const row=rows.find(r=>r.id===new FormData(e.target).get('enrollment')),b=box.querySelector('[type=submit]');b.disabled=true;try{row.request_id||=crypto.randomUUID();await rpc('remove',{id:row.id,class_id:row.class_id,student_id:row.student_id,version:row.version,request_id:row.request_id});if(identity()!==actor)return;box.remove();cache.clear();cfg.toast?.('선택한 반에서 제거했습니다. 계정은 보존했습니다.');await cfg.saved?.()}catch(ex){box.querySelector('[data-membership-error]').textContent=/MEMBERSHIP_BILLABLE_RECORDS/.test(ex.message)?'이 반에 출석·지각·영상보강·대면보강 기록이 있어 제거할 수 없습니다.':/MEMBERSHIP_CHANGED/.test(ex.message)?'수강 배정이 변경되었습니다. 닫고 다시 선택하세요.':ex.message;b.disabled=false}};}
