async function pickBulk(sid,cid){if(bulkBusy)return;bulkBusy=true;try{if(chosen.has(sid)){chosen.delete(sid);bulkRequest='';return}const actor=identity(),rows=visible(await read([sid],true),cid);if(!bulk||identity()!==actor)return;const allowed=rows.filter(r=>r.can_remove);if(!allowed.length)return info102('원생 삭제 불가',rows.map(r=>r.class_name+' · '+r.reason).join('\n')||'현재 화면 범위에 제거할 수강 배정이 없습니다.');let row=allowed[0];if(rows.length>1){row=await new Promise(resolve=>{const d=document.createElement('dialog');d.className='membership-dialog102';d.innerHTML='<h2>제거할 반 선택</h2>'+rows.map(r=>'<button type="button" class="btn" data-enrollment102="'+E(r.id)+'" '+(!r.can_remove?'disabled':'')+'>'+E(r.class_name)+(r.reason?'<small>'+E(r.reason)+'</small>':'')+'</button>').join('')+'<button type="button" data-cancel102 class="btn">취소</button>';let selected=null;document.body.append(d);d.showModal();d.querySelectorAll('[data-enrollment102]').forEach(b=>b.onclick=()=>{selected=rows.find(r=>r.id===b.dataset.enrollment102);d.close()});d.querySelector('[data-cancel102]').onclick=()=>d.close();d.addEventListener('close',()=>{d.remove();resolve(selected)},{once:true})})}if(row&&bulk&&identity()===actor){chosen.set(sid,row);bulkRequest=''}}catch(e){info102('삭제 가능 여부 확인',e.message)}finally{bulkBusy=false;paintBulk()}}
