function paintBulk(){if(!staff())return;const ctx=cfg.bulkContext?.();if(!ctx||ctx.view!=='students'){if(bulk)endBulk();return}const signature=owner+'|'+ctx.class_id+'|'+(ctx.scope||'');if(bulkContext!==signature){bulkContext=signature;if(bulk)endBulk()}
 const grid=document.querySelector('#data-grid');if(!grid)return;let action=document.querySelector('[data-member-bulk102]');const heading=grid.querySelector('th[data-col="_remove"]'),place=heading||document.querySelector('#grid-zone .table-tools');if(place&&!action){action=document.createElement('button');action.className='btn sm';action.type='button';action.dataset.memberBulk102='';place.append(action);action.onclick=e=>{e.preventDefault();e.stopPropagation();if(bulkBusy)return;if(bulk)endBulk();else{bulk=true;chosen.clear();bulkRequest='';paintBulk()}}}if(action){const label=bulk?'선택 취소':'다중 삭제';if(action.textContent!==label)action.textContent=label;action.disabled=bulkBusy}
 grid.classList.toggle('membership-mode102',bulk);grid.closest('.table-shell')?.classList.toggle('membership-page102',bulk);for(const row of grid.querySelectorAll('[data-row-id]')){const sid=row.dataset.rowId;row.classList.toggle('member-selected102',bulk&&chosen.has(sid));let check=row.querySelector('[data-member-pick102]');if(bulk&&!check){check=document.createElement('input');check.type='checkbox';check.dataset.memberPick102=sid;check.dataset.draftIgnore='';check.setAttribute('aria-label',(cfg.base?.()?.students?.find(s=>s.id===sid)?.name||'학생')+' 삭제 선택');(row.querySelector('.check-cell')||row.querySelector('td')||row).prepend(check)}if(check){check.checked=chosen.has(sid);check.disabled=bulkBusy}}
 let bar=document.querySelector('.membership-bar102');if(bulk&&!bar){bar=document.createElement('div');bar.className='membership-bar102';bar.innerHTML='<div><strong>한번에 삭제할 인원을 클릭하세요</strong><span role="status"></span></div><button class="btn danger" type="button" data-member-delete102></button>';document.querySelector('#grid-footer').after(bar);bar.querySelector('button').onclick=removeBulk}if(bar){const rect=grid.getBoundingClientRect();bar.style.left=Math.max(12,rect.left)+'px';bar.style.right=Math.max(12,innerWidth-rect.right)+'px';const count=chosen.size,text=count+'명 선택';if(bar.querySelector('span').textContent!==text)bar.querySelector('span').textContent=text;const b=bar.querySelector('button'),label='선택한 '+count+'명 삭제';if(b.textContent!==label)b.textContent=label;b.disabled=bulkBusy||!count}}
