  const body=r.rows.length?r.rows.map((row,i)=>{
   const title='<b>'+esc(row.name)+'</b>'+(row.context?'<small>'+esc(row.context)+'</small>':'');
   const cells=s.view==='classes'?[title,n(row.exams)+'회',n(row.attempts)+'건',n(row.students)+'명',average(row.average),esc(row.last_date||'—')]:s.view==='exams'?[title,n(row.attempts)+'명',row.published?'공개':'미공개',average(row.average),esc(row.last_date||'—')]:[title,n(row.attempts)+'회',average(row.average),esc(row.last_date||'—')];
   return '<tr><td>'+((s.page-1)*50+i+1)+'</td>'+cells.map((v,j)=>'<td data-label="'+esc(titles[j])+'">'+v+'</td>').join('')+'</tr>';
  }).join(''):'<tr><td colspan="'+(titles.length+1)+'"><p class="muted">조건에 맞는 기록이 없습니다.</p></td></tr>';
