  s.host.querySelectorAll('[data-paper-view]').forEach(b=>b.onclick=()=>{s.view=b.dataset.paperView;s.page=1;loadDetail(s);});
  const form=s.host.querySelector('[data-paper-filters]');if(form)form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;const f=Object.fromEntries(new FormData(form));if(f.date_from&&f.date_to&&f.date_from>f.date_to){s.detailError='조회 기간을 확인해 주세요.';s.loading=false;draw(s);return;}s.filters=f;s.page=1;loadDetail(s);};
