(()=>{'use strict';
const collator=new Intl.Collator('ko-KR',{numeric:true,sensitivity:'base'});
const filename=r=>String(r.filename||r.name||r.title||'');
const sort=rows=>[...rows].sort((a,b)=>collator.compare(filename(a),filename(b))||collator.compare(a.title||'',b.title||'')||String(a.id).localeCompare(String(b.id)));
const date=v=>v?new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v)):'';
function tabs(host,onChange){host.innerHTML='<div class="data-scope78" role="tablist" aria-label="자료 공개 범위"><button type="button" role="tab" aria-selected="true" data-scope78="private">개인</button><button type="button" role="tab" aria-selected="false" data-scope78="shared">공용</button></div>';let current='private';host.querySelectorAll('[data-scope78]').forEach(b=>b.onclick=()=>{current=b.dataset.scope78;host.querySelectorAll('[data-scope78]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));onChange(current)});return()=>current}
function filters(host,onChange){host.innerHTML='<div class="data-filters78" role="group" aria-label="불러올 자료 범위"><label><input type="checkbox" data-scope-private78 checked> 개인</label><label><input type="checkbox" data-scope-shared78> 공용</label></div>';const allow=r=>host.querySelector(r.shared?'[data-scope-shared78]':'[data-scope-private78]').checked;host.querySelectorAll('input').forEach(x=>x.onchange=onChange);return allow}
function paperFilter(select,rows,selected){
 const host=document.createElement('div');select.closest('label').after(host);select.hidden=true;select.setAttribute('aria-hidden','true');const filtersHost=document.createElement('div'),search=document.createElement('input'),list=document.createElement('div');search.type='search';search.className='input paper-search95';search.placeholder='시험지 이름 · 폴더 검색';search.setAttribute('aria-label','시험지 검색');list.className='paper-choices95';host.append(filtersHost,search,list);let allow;
 const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function draw(){const current=select.value||selected||'',q=search.value.trim().toLowerCase(),visible=sort(rows.filter(r=>allow(r)&&(!q||(r.name+' '+(r.folder_path||'바탕화면')).toLowerCase().includes(q))));select.replaceChildren(new Option('연결하지 않음',''),...rows.map(r=>new Option(r.name,r.id)));select.value=current;if(!select.value)select.value='';const active=rows.find(r=>r.id===select.value);list.innerHTML='<button type="button" class="paper-choice95" data-paper-choice95="" aria-pressed="'+(!select.value)+'">연결하지 않음</button>'+visible.map(r=>'<button type="button" class="paper-choice95" data-paper-choice95="'+escape(r.id)+'" aria-pressed="'+(select.value===r.id)+'"><b>'+escape(r.name)+'</b><small class="library-path95">'+escape(r.folder_path||'바탕화면')+' · '+(r.shared?'공용':'개인')+'</small></button>').join('')+(active&&!visible.some(r=>r.id===active.id)?'<div class="library-path95">현재 연결: '+escape(active.name)+' · '+escape(active.folder_path||'바탕화면')+'</div>':'');list.querySelectorAll('[data-paper-choice95]').forEach(b=>b.onclick=()=>{select.value=b.dataset.paperChoice95;selected=select.value;select.dispatchEvent(new Event('change',{bubbles:true}));draw()})}
 allow=filters(filtersHost,draw);search.oninput=draw;draw();select.addEventListener('change',()=>{selected=select.value});
}
window.MiraeDataScope78={sort,date,tabs,filters,paperFilter};
})();

