 toggle.onchange=()=>{pick.hidden=!toggle.checked;if(!toggle.checked){selected.clear();pick.querySelectorAll('input').forEach(i=>i.checked=false)}};form.querySelectorAll('[data-class-day]').forEach(i=>i.addEventListener('change',drawRooms));form.elements.teacher_id?.addEventListener('change',drawTwins);drawRooms();drawTwins();
