 function scores(){const box=body.querySelector('[data-unified-scores]'),points=data.exams.filter(x=>x.class_id===graphClass).slice(-8).map(e=>({e,s:data.scores.find(s=>s.exam_id===e.id)}));if(!points.length){box.innerHTML='<div class="empty">등록된 시험이 없습니다.</div>';return}const W=480,H=210,left=32,right=16,top=16,bottom=42,x=i=>left+(W-left-right)*(points.length===1?.5:i/(points.length-1)),pct=p=>p.s&&!p.s.absent&&p.s.score!=null&&p.s.score!==''&&Number(p.e.max_score)>0?Math.max(0,Math.min(100,Number(p.s.score)/Number(p.e.max_score)*100)):null,y=v=>top+(H-top-bottom)*(1-v/100);let path='',lastPoint=false;points.forEach((p,i)=>{if(pct(p)==null){lastPoint=false;return}path+=(lastPoint?' L':' M')+x(i)+','+y(pct(p));lastPoint=true});box.innerHTML='<svg class="student-score-svg" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="최근 시험 성적, 만점 대비 백분율">'+[0,50,100].map(n=>'<text x="3" y="'+(y(n)+4)+'">'+n+'</text><line x1="'+left+'" x2="'+(W-right)+'" y1="'+y(n)+'" y2="'+y(n)+'"/>').join('')+'<path d="'+path+'"/>'+points.map((p,i)=>'<g><text x="'+x(i)+'" y="'+(H-18)+'" text-anchor="middle">'+E(p.e.exam_date?.slice(5)||'')+'</text>'+(pct(p)==null?'':'<circle tabindex="0" role="button" aria-label="'+E(p.e.title)+' '+N(p.s.score)+'점" data-point="'+i+'" cx="'+x(i)+'" cy="'+y(pct(p))+'" r="6"/>')+'</g>').join('')+'</svg><div class="student-score-detail" data-score-detail></div>';const show=i=>{const p=points[i];box.querySelector('[data-score-detail]').innerHTML='<strong>'+E(p.e.title)+'</strong><span>'+E(p.e.exam_date)+'</span><b>'+(p.s?.absent?'미응시':p.s?.score==null||p.s.score===''?'미입력':N(p.s.score)+' / '+N(p.e.max_score)+'점')+'</b>'};show(points.length-1);box.querySelectorAll('[data-point]').forEach(p=>{p.onclick=()=>show(+p.dataset.point);p.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();show(+p.dataset.point)}}})}
