const age=v=>{if(!v)return'저장된 목록 없음';const m=Math.max(0,Math.floor((Date.now()-new Date(v).getTime())/60000));return m<1?'방금 전':m<60?m+'분 전':m<1440?Math.floor(m/60)+'시간 전':Math.floor(m/1440)+'일 전'};
