function studentMetrics(sid){const cache=derivedCache();if(cache.metrics.has(sid))return cache.metrics.get(sid);const ex=new Map(S.data.exams.filter(x=>reportClassAllowed(x.class_id)).map(x=>[x.id,x]));const scored=S.data.scores.filter(s=>s.student_id===sid&&!s.absent&&s.score!==null&&s.score!==''&&ex.has(s.exam_id)).map(s=>({...s,exam:ex.get(s.exam_id),pct:Number(s.score)/Number(ex.get(s.exam_id).max_score)*100})).sort((a,b)=>a.exam.exam_date.localeCompare(b.exam.exam_date)||a.exam.id.localeCompare(b.exam.id));const pts=scored.map(s=>s.pct),hw=expectedHomework().filter(h=>h.student.id===sid&&reportClassAllowed(h.lesson.class_id)),due=hw.filter(h=>new Date(h.due_at)<new Date()),feedback=S.data.feedback.filter(f=>f.student_id===sid&&reportClassAllowed(S.data.lessons.find(l=>l.id===f.lesson_id)?.class_id)),delta=pts.length>=6?avg(pts.slice(-3))-avg(pts.slice(-6,-3)):pts.length>=2?pts.at(-1)-pts[0]:null;const result={sid,scored,average:avg(pts),latest:pts.at(-1)??null,delta,count:pts.length,missing:due.filter(h=>!h.submission||h.status==='missing').length,submitted:hw.filter(h=>h.submission&&h.status!=='missing').length,homework:hw.length,passed:hw.filter(h=>h.status==='passed').length,passRate:hw.length?hw.filter(h=>h.status==='passed').length/hw.length*100:null,absence:reportAttendance73(sid).absence,attendance:reportAttendance73(sid).rate,feedback};cache.metrics.set(sid,result);return result}
function reportRows(){const ids=new Set(S.base.enrollments.filter(e=>reportClassAllowed(e.class_id)&&(!S.classId||e.class_id===S.classId)&&(!S.criteria.currentOnly||e.status==='enrolled')).map(e=>e.student_id));return S.base.students.filter(s=>ids.has(s.id)).map(s=>{const m=studentMetrics(s.id),c=S.criteria,checks=[];if(c.averageOn)checks.push({hit:m.count>=c.minimum&&m.average!==null&&m.average<c.average,label:'평균 미달'});if(c.dropOn)checks.push({hit:m.count>=c.minimum&&m.delta!==null&&m.delta<=-c.drop,label:'성적 하락'});if(c.missingOn)checks.push({hit:m.missing>=c.missing,label:'과제 누락'});if(c.absenceOn)checks.push({hit:m.absence>=c.absence,label:'결석 누적'});const matched=checks.length>0&&(c.logic==='all'?checks.every(x=>x.hit):checks.some(x=>x.hit));return {...s,...m,reasons:checks.filter(x=>x.hit).map(x=>x.label),matched,signal:matched?checks.filter(x=>x.hit).length:0}})}
function spark(values){if(!values.length)return'—';const x=i=>values.length<2?42:2+i/(values.length-1)*80,y=v=>27-v/100*24;return`<svg viewBox="0 0 86 30" class="tiny-chart" aria-label="성적 추이"><path d="${values.map((v,i)=>(i?'L':'M')+x(i)+','+y(v)).join(' ')}" stroke="#819bef" stroke-width="1.8" fill="none"/><circle cx="${x(values.length-1)}" cy="${y(values.at(-1))}" r="2.4" fill="#5276e5"/></svg>`}
