function clearClientCaches(){MiraeWatch?.reset();window.MiraeAdmissions?.reset();window.MiraeRosterIntegrity?.reset();window.MiraeTimeNetCounsel?.reset();window.MiraeSchoolGrades?.reset();window.MiraeFastReads?.reset();window.MiraeMSCache?.reset();window.MiraeDrafts?.resetOwner();window.MiraeContacts?.reset();window.MiraePhoneReview?.reset();stopDirectorySync();window.MiraeAttendance?.reset();timenetPending=null;window.MiraeSMS?.reset();stopPresence();resetEasyPC();inflightReads.clear();photoCache.clear();photoBytes=0;directoryCache=null}
async function api(path,options={}){
 if(options.method==='POST'&&new URL(path,'https://browser.invalid').pathname==='/api/makeups/stats')return apiRequest(path,options);
 const read=(!options.method||options.method==='GET')&&!options.signal;
 if(!read){const ticket=MiraeDrafts.ticket(M?.node.querySelector('.modal')||$('#main'));const result=await apiRequest(path,options);MiraeDrafts.commit(ticket);db.lastRefresh=0;return result;}
 const key=(options.fresh?'fresh|':'')+S.token+'|'+S.studentId+'|'+path;
 if(inflightReads.has(key))return inflightReads.get(key);
 const request=apiRequest(path,options);inflightReads.set(key,request);
 try{return await request}finally{if(inflightReads.get(key)===request)inflightReads.delete(key)}
}
async function apiRequest(path,options={}){return browserRequest(path,options)}
async function reload(full=false){
 const generation=++S.generation;MiraeStudentRemoval.invalidate();S.loading=true;$('#refresh-button')?.classList.add('loading-body');
 try{
  const query=new URLSearchParams({class_id:S.classId,start:S.start,end:S.end});
  if(full){
   const result=await api('/api/workspace?'+query);if(generation!==S.generation)return;
   S.base=result.base;S.user=result.base.user;S.studentId=result.base.selected_student_id||((isFamily()&&result.base.students[0])?result.base.students[0].id:'');S.classId=result.class_id||'';S.data=result.data;
   if(result.data.range){S.start=result.data.range.start;S.end=result.data.range.end}
   if(S.user.preferences?.criteria)S.criteria={...S.criteria,...S.user.preferences.criteria};
  }else if(S.view!=='parents'){
   const d=await api('/api/data?'+query);if(generation!==S.generation)return;S.data=d;
  }
  if(S.view==='parents'){const d=await api('/api/parents');if(generation!==S.generation)return;S.parents=d.rows}
  if(S.view==='accounts'){const d=await api('/api/accounts');if(generation!==S.generation)return;S.accounts=d.rows}
  
  render();MiraeAttention88.invalidate();
  // Warm only a successful cached directory, after the actual classroom is visible.
  if(full&&!isFamily()&&S.base.timenet_meta?.updated_at)loadDirectory().catch(()=>{});window.MiraePolish.refreshConsultations();
 }catch(e){if(generation===S.generation){if(e.code==='STUDENT_ACCESS_CHANGED'&&isFamily()&&S.studentId){S.studentId='';S.classId='';S.base={students:[],classes:[],enrollments:[],teachers:[]};S.data={lessons:[],exams:[],scores:[],feedback:[],submissions:[],attachments:[],lesson_files:[],consultations:[],videos:[],video_progress:[],exam_stats:{}};closeAll();clearClientCaches();await reload(true);toast('학생 배정이 변경되어 목록을 다시 확인했습니다.');return}if(S.user)render();toast(e.message,true)}}
 finally{if(generation===S.generation){S.loading=false;$('#refresh-button')?.classList.remove('loading-body');startPresence()}}
}
