function renderDashboard(){const oldBase=S.base,oldData=S.data;try{S.base=MiraeViewScope.base(oldBase);S.data=MiraeViewScope.data(oldData);unscopedDashboard()}finally{S.base=oldBase;S.data=oldData}}
