async function baseOpenEditor(entity=S.view,id=null,override={}){if(entity==='classes')return classEditor(id,override);if(entity==='lessons')return lessonEditor(id,override);const student=isFamily();if(student)return;if(entity==='classes'&&S.user.role==='admin'&&!S.accounts.length){try{S.accounts=(await api('/api/accounts')).rows}catch(e){toast(e.message,true);return}}const collection=['students','classes'].includes(entity)?S.base[entity]:entity==='accounts'?S.accounts:S.data[entity]||[];const old=id?collection.find(x=>x.id===id):null;const v={...(old||{}),...override};const classField={key:'class_id',label:'강좌',type:'select',options:classOptions(),default:currentClass(),required:true,wide:true,disabled:!!old};const statusField=(opts,def)=>({key:'status',label:'상태',type:'select',options:opts.map(x=>[x,badges[x]?.[0]||x]),default:def});let fields=[];if(entity==='students')fields=[{key:'name',label:'학생명',required:true},{key:'student_no',label:'원생번호',required:true,disabled:!!old},{key:'school',label:'학교'},{key:'grade',label:'학년'},...(!old?[{...classField,key:'__class_id',label:'등록할 강좌'},{key:'__joined_on',label:'첫 수업일',type:'select',options:[],required:true}]:S.user.role==='admin'?[{key:'active',label:'학생 자료 열람 허용',type:'checkbox',default:true}]:[])];if(entity==='classes')fields=[{key:'name',label:'강좌명',required:true,wide:true},{key:'subject',label:'과목',default:'과학'},{key:'teacher_id',label:'담당 강사',type:'select',options:(S.user.role==='admin'?S.accounts.filter(a=>a.status==='active'&&a.role==='teacher'):[S.user]).map(t=>[t.id,t.name]),default:S.user.id,required:true},{key:'start_date',label:'개강일',type:'date',default:today(),required:true},{key:'end_date',label:'종강일',type:'date',default:addDays(today(),90),required:true},statusField(['active','archived'],'active'),{key:'description',label:'강좌 안내',type:'textarea',wide:true}];if(entity==='lessons')fields=[classField,{key:'lesson_date',label:'수업일',type:'date',default:today(),required:true},{key:'title',label:'수업 제목',required:true},{key:'progress',label:'수업 진도',type:'textarea',wide:true,placeholder:'오늘 학습한 내용'},{key:'homework',label:'과제',type:'textarea',wide:true,placeholder:'과제 범위와 준비물'},{key:'online_required',label:'사진으로 온라인 제출하는 과제',type:'checkbox',wide:true},{key:'due_at',label:'제출 마감 (한국 시간)',type:'datetime-local',wide:true},{key:'video_link_text',label:'수업 영상 링크 · 한 줄에 제목 | 주소',type:'textarea',wide:true},{key:'material_link_text',label:'추가 자료 링크 · 한 줄에 제목 | 주소',type:'textarea',wide:true},{key:'notice',label:'강좌 전체 공지',type:'textarea',wide:true},{key:'published',label:'학생 · 학부모에게 공개',type:'checkbox',default:true,wide:true}];if(entity==='exams')fields=[classField,{key:'lesson_id',label:'수업 기록 연결 · 과제 검사 함께 입력',type:'select',wide:true,options:[['','연결 안 함'],...S.data.lessons.filter(l=>l.class_id===(v.class_id||currentClass())).map(l=>[l.id,l.lesson_date+' · '+l.title])]}, {key:'title',label:'시험명',required:true},{key:'exam_date',label:'시험일',type:'date',default:today(),required:true},{key:'subject',label:'과목',default:'과학'},{key:'unit',label:'단원'},{key:'max_score',label:'만점',type:'number',default:100,required:true,step:0.1,min:0.1},{key:'published',label:'성적 공개',type:'checkbox',default:true}];if(entity==='videos')fields=[classField,{key:'title',label:'영상 제목',required:true,wide:true},{key:'youtube_url',label:'YouTube 링크',type:'url',required:true,wide:true,default:old?'https://www.youtube.com/watch?v='+old.youtube_id:''},{key:'video_date',label:'수업일',type:'date',required:true,default:today()},{key:'lesson_id',label:'수업 기록 연결',type:'select',options:[['','연결 안 함'],...S.data.lessons.filter(l=>l.class_id===(v.class_id||currentClass())).map(l=>[l.id,l.lesson_date+' '+l.title])],default:''},{key:'published',label:'학생 · 학부모에게 공개',type:'checkbox',default:true}];if(entity==='accounts')fields=[{key:'name',label:'강사명',required:true},{key:'login_id',label:'로그인 아이디',required:true},{key:'password',label:old?'새 초기 비밀번호 (변경 시)':'초기 비밀번호',type:'password',required:!old},{key:'role',label:'권한',type:'select',options:[['teacher','강사'],['admin','최종관리자']],default:'teacher'},statusField(['active','inactive','departed'],'active'),{key:'can_edit_login',label:'로그인 화면 · 메인 문구 · 홍보 버튼 편집 허용',type:'checkbox',wide:true}];if(!fields.length)return;const values={...v};if(entity==='lessons')values.due_at=localTime(v.due_at);const title=(old?'수정 · ':'새로 등록 · ')+({students:'학생',classes:'반',lessons:'수업',exams:'시험',videos:'영상',accounts:'강사'})[entity];modal(title,`<form id="edit-form">${fieldsHtml(fields,values)}<div id="form-error"></div></form>`,`${old&&entity==='lessons'?btn('학생별 출석 · 코멘트','lesson-feedback',`data-id="${old.id}"`,''):''}${old&&entity==='exams'?btn('점수 입력','score-entry',`data-id="${old.id}"`,''):''}${btn('취소','close-modal')}${btn('저장','save-editor','','primary','check')}`,{wide:entity==='lessons'});if(entity==='students'&&!old)MiraeAttendanceCore.bindLessonSelect($('#edit-form'),S.base.classes,'__class_id','__joined_on');const updateDeadline=()=>{const check=$('[name=online_required]',M.node),input=$('[name=due_at]',M.node);if(check&&input){input.closest('.field').classList.toggle('hidden',!check.checked);input.required=check.checked;if(!check.checked)input.value=''}};updateDeadline();if(entity==='exams')$('[name=class_id]',M.node)?.addEventListener('change',ev=>{const select=$('[name=lesson_id]',M.node);select.innerHTML='<option value="">연결 안 함</option>'+S.data.lessons.filter(l=>l.class_id===ev.target.value).map(l=>`<option value="${l.id}">${esc(l.lesson_date+' · '+l.title)}</option>`).join('')});$('[name=online_required]',M.node)?.addEventListener('change',updateDeadline);M.save=async()=>{const form=$('#edit-form');if(!form.reportValidity())return;const payload=collect();for(const f of fields.filter(f=>f.disabled))if(old)payload[f.key]=old[f.key];if(entity==='lessons')payload.due_at=payload.online_required?toISO(payload.due_at):null;if(['videos','exams'].includes(entity)&&!payload.lesson_id)payload.lesson_id=null;if(old){payload.id=old.id;payload.version=old.version}const button=$('[data-action=save-editor]',M.node);button.disabled=true;try{await api('/api/manage/'+entity+'/bulk',{method:'POST',body:{rows:[payload]}});closeModal(true);await reload(true);toast('저장완료')}catch(e){errorBox(e.message);button.disabled=false}};$('#edit-form').addEventListener('submit',e=>{e.preventDefault();M.save()})}
async function saveGrid(){if(!S.pending.size)return;const rows=[...S.pending].map(([id,changes])=>{const original=rowsForView().find(r=>r.id===id);return{id,version:original.version,...changes}});try{await api('/api/manage/'+S.view+'/bulk',{method:'POST',body:{rows}});S.pending.clear();MiraeDrafts.data.delete('grid|'+S.user.id+'|'+S.view+'|'+MiraeViewScope.signature());S.undo=[];await reload(true);toast('저장완료')}catch(e){toast(e.message,true)}}
function studentDetail(id){const s=getStudent(id),es=S.base.enrollments.filter(e=>e.student_id===id);modal(s.name,`<div class="flex between"><div>${studentCell(s)}<div class="tagline">${badge(s.active?'active':'inactive')}<span class="badge">${esc(s.school)} ${esc(s.grade)}</span></div></div>${btn('학습 리포트','student-report',`data-id="${s.id}"`,'','reports')}</div><div class="family-assignment-strip"><span>학부모 계정 · <b>${esc((S.base.parents||[]).find(p=>p.id===s.parent_id)?.login_id||'미배정')}</b></span>${btn('학부모 정보 · 배정','parent-for-student',`data-id="${s.id}"`,'sm','students')}</div><div class="form-section-title">수강 이력 <button class="btn ghost sm" data-merge-history="${esc(s.id)}">기록 통합 이력</button></div>${es.length?simpleTable([{key:'class',label:'강좌',render:e=>`<span class="primary-text">${esc(getClass(e.class_id).name)}</span><small>${getClass(e.class_id).start_date} ~ ${getClass(e.class_id).end_date}</small>`},{key:'status',label:'상태',render:e=>badge(e.status)},{key:'snapshot',label:'당시 학교 · 학년',render:e=>esc(e.school_at_entry||'')+' '+esc(e.grade_at_entry||'')},{key:'date',label:'수강 시작',render:e=>dateText(e.joined_on,true)},{key:'action',label:'',render:e=>btn('변경','enrollment-edit',`data-id="${e.id}"`,'ghost sm','edit')+(!isFamily()&&e.status==='enrolled'?MiraeStudentRemoval.button(e.student_id,e.class_id):'')}],es):empty('수강 이력이 없습니다.')}`,`${btn('다른 반에 등록','add-enrollment',`data-id="${s.id}"`,'','plus')}${btn('학생 정보 수정','edit-student',`data-id="${s.id}"`,'primary','edit')}${!isFamily()?MiraeStudentRemoval.button(s.id):''}`,{wide:true})}
function enrollmentEditor(id,studentId){const old=S.base.enrollments.find(e=>e.id===id);if(old?.status==='withdrawn'){toast('퇴원 처리된 수강입니다. 다시 입반하려면 다른 반에 등록을 사용하세요.',true);return}const fields=[{key:'class_id',label:'강좌',type:'select',options:classOptions(),default:currentClass(),disabled:!!old,required:true,wide:true},{key:'status',label:'수강 상태',type:'select',options:['enrolled','inactive','completed'].map(s=>[s,badges[s][0]]),default:'enrolled'},{key:'joined_on',label:'첫 수업일',type:'select',options:[],required:true},{key:'left_on',label:'수강 종료일',type:'date'}];modal(old?'수강 상태 변경':'다른 반에 등록',`<form id="enroll-form">${fieldsHtml(fields,old||{})}</form>`,btn('저장','save-editor','','primary','check'));MiraeAttendanceCore.bindLessonSelect($('#enroll-form'),S.base.classes,'class_id','joined_on',old?.joined_on);M.save=async()=>{if(!$('#enroll-form').reportValidity())return;const d=collect();d.left_on=d.left_on||null;if(old){d.id=old.id;d.version=old.version;d.class_id=old.class_id;d.student_id=old.student_id}else d.student_id=studentId;try{await api('/api/manage/enrollments/bulk',{method:'POST',body:{rows:[d]}});closeAll();await reload(true);toast('수강 상태를 저장했습니다.')}catch(e){errorBox(e.message)}}}
function bulkStatus(){const view=S.view;let options;if(view==='students'){if(!S.classId){toast('수강 상태를 변경할 반을 먼저 선택해 주세요.',true);return}options=['enrolled','inactive','completed']}else if(view==='classes')options=['active','archived'];else if(view==='accounts')options=['active','inactive','departed'];else if(view==='homework')options=['submitted','poor','passed','missing'];else return;modal('선택 항목 상태 변경',fieldsHtml([{key:'status',label:'변경할 상태',type:'select',options:options.map(s=>[s,badges[s][0]])},...(view==='students'?[{key:'left_on',label:'수강 종료일',type:'date',default:today()}]:[])]),btn(S.selected.size+'개 변경','save-editor','','primary','check'));M.save=async()=>{const d=collect();let entity=view,rows=[];if(view==='students'){entity='enrollments';rows=S.base.enrollments.filter(e=>e.class_id===S.classId&&S.selected.has(e.student_id)).map(e=>({id:e.id,version:e.version,status:d.status,left_on:['withdrawn','completed'].includes(d.status)?d.left_on||today():null}))}else if(view==='homework'){entity='submissions';rows=expectedHomework().filter(h=>S.selected.has(h.id)&&h.submission).map(h=>({id:h.submission.id,version:h.submission.version,status:d.status}));if(rows.length<S.selected.size){errorBox('아직 사진을 제출하지 않은 학생은 제출 내역이 없어 일괄 상태를 바꿀 수 없습니다. 제출된 항목만 선택해 주세요.');return}}else rows=rowsForView().filter(r=>S.selected.has(r.id)).map(r=>({id:r.id,version:r.version,status:d.status}));try{await saveChunks(entity,rows);closeModal(true);S.selected.clear();await reload(true);toast('상태를 변경했습니다.')}catch(e){errorBox(e.message)}}}
async function saveChunks(entity,rows){if(!rows.length)throw new Error('저장할 변경 내용이 없습니다.');if(rows.length>200)throw new Error('한 번에 200행 이하로 선택해 주세요.');return api('/api/manage/'+entity+'/bulk',{method:'POST',body:{rows}})}

// Flexible, quote-aware spreadsheet import; imported data are never evaluated as formulas.
function parseDelimited(text,delimiter){text=String(text).replace(/^\uFEFF/,'').replace(/\r\n/g,'\n');delimiter=delimiter||(text.includes('\t')?'\t':',');let out=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else if(quoted||!cell)quoted=!quoted;else cell+=c}else if(c===delimiter&&!quoted){row.push(cell);cell=''}else if(c==='\n'&&!quoted){row.push(cell);out.push(row);row=[];cell=''}else cell+=c}row.push(cell);out.push(row);return out.filter(r=>r.some(x=>x.trim()!==''))}
const importDefinitions={students:[['name','학생명','학생명|이름|학생|성명|원생명|name'],['student_no','원생번호','원생번호|학생번호|고유번호|student_no'],['school','학교','학교|학교명'],['grade','학년','학년'],['__class_name','등록할 반','반명|강좌|반']],classes:[['name','반명','반명|강좌|반'],['subject','과목','과목'],['start_date','개강일','개강일|시작일|개강'],['end_date','종강일','종강일|종료일|종강'],['__teacher','담임','강사|담당|담당강사|담임'],['__assistant','부담임','부담임|보조강사'],['description','반 안내','안내|설명']],exams:[['title','시험명','시험명|시험|제목'],['exam_date','시험일','시험일|날짜|일자'],['max_score','만점','만점|총점'],['subject','과목','과목'],['unit','단원','단원|영역'],['__class_name','강좌','반명|강좌|반']],videos:[['title','영상 제목','영상명|제목|영상제목'],['youtube_url','YouTube 링크','링크|url|유튜브|영상주소'],['video_date','수업일','날짜|수업일|일자'],['__class_name','강좌','반명|강좌|반']]};
function importDate(v){v=String(v||'').trim();if(/^\d{5}$/.test(v))return new Date(Date.UTC(1899,11,30)+Number(v)*86400000).toISOString().slice(0,10);const m=v.match(/^(\d{2,4})[.\-/년 ]+\s*(\d{1,2})[.\-/월 ]+\s*(\d{1,2})/);if(m)return(m[1].length===2?'20':'')+m[1]+'-'+m[2].padStart(2,'0')+'-'+m[3].padStart(2,'0');return v}
function openImport(entity=S.view){if(entity==='students')return registration();const defs=importDefinitions[entity];if(!defs)return;let raw=[],hasHeader=true,mapping=[];modal(titleFor(entity)+' 일괄 입력',`<div class="import-toolbar"><label class="btn">${icon('file')}CSV · TSV 파일<input type="file" id="import-file" accept=".csv,.tsv,.txt" hidden></label><label class="check-label"><input type="checkbox" id="import-header" checked>첫 줄은 제목</label>${entity!=='classes'?`<select id="import-class">${classOptions().map(o=>`<option value="${o[0]}" ${o[0]===currentClass()?'selected':''}>${esc(o[1])}</option>`).join('')}</select>`:''}</div><textarea id="paste-source" class="paste-box" rows="5" placeholder="엑셀에서 여러 행과 열을 복사해 여기에 붙여넣으세요. 열 순서는 자유롭게 연결할 수 있습니다."></textarea><div class="flex between" style="margin:12px 0"><span role="button" tabindex="0" class="ui-help72" aria-label="도움말 설명 보기" data-help-title72="도움말" data-help72="최대 200행씩 저장" >?</span>${btn('붙여넣은 내용 확인','parse-import','','','grid')}</div><div id="import-preview"></div>`,btn('취소','close-modal')+btn('검사 후 저장','save-import','','primary','check'),{wide:true});const node=M.node;const parse=()=>{raw=parseDelimited($('#paste-source',node).value);hasHeader=$('#import-header',node).checked;if(!raw.length){$('#import-preview',node).innerHTML=empty('붙여넣은 내용이 없습니다.');return}const count=Math.max(...raw.map(r=>r.length));mapping=Array.from({length:count},(_,i)=>{const h=hasHeader?(raw[0][i]||'').replace(/\s/g,'').toLowerCase():'';return defs.find(d=>new RegExp('^(?:'+d[2]+')$','i').test(h))?.[0]||(!hasHeader?defs[i]?.[0]||'':'')});preview()};const preview=()=>{let rows=hasHeader?raw.slice(1):raw;$('#import-count',node).textContent=rows.length+'행 · '+mapping.length+'열';$('#import-preview',node).innerHTML=`<div class="table-scroll import-matrix"><table class="data-table"><thead><tr><th>#</th>${mapping.map((m,i)=>`<th><small>${esc(hasHeader?raw[0][i]||'빈 열':String.fromCharCode(65+i))}</small><select data-map="${i}"><option value="">가져오지 않음</option>${defs.map(d=>`<option value="${d[0]}" ${m===d[0]?'selected':''}>${d[1]}</option>`).join('')}</select></th>`).join('')}</tr></thead><tbody>${rows.slice(0,200).map((r,n)=>`<tr><td>${n+1}</td>${mapping.map((m,i)=>`<td><input data-import-r="${n+(hasHeader?1:0)}" data-import-c="${i}" value="${esc(r[i]||'')}" aria-label="${n+1}행 ${i+1}열"></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;$$('[data-map]',node).forEach(x=>x.onchange=()=>mapping[+x.dataset.map]=x.value);$$('[data-import-r]',node).forEach(x=>x.oninput=()=>raw[+x.dataset.importR][+x.dataset.importC]=x.value)};node.querySelector('[data-action=parse-import]').onclick=parse;$('#import-header',node).onchange=parse;$('#paste-source',node).addEventListener('paste',()=>setTimeout(parse,0));$('#import-file',node).onchange=async e=>{const f=e.target.files[0];if(!f)return;const b=await f.arrayBuffer();let text=new TextDecoder('utf-8').decode(b);if(text.includes('\ufffd'))text=new TextDecoder('euc-kr').decode(b);$('#paste-source',node).value=text;parse()};node.querySelector('[data-action=save-import]').onclick=async()=>{if(!raw.length)parse();const source=hasHeader?raw.slice(1):raw;if(!source.length)return errorBox('붙여넣은 데이터를 확인해 주세요.');if(source.length>200)return errorBox('200행 이하로 나누어 저장해 주세요.');const used=mapping.filter(Boolean);if(new Set(used).size!==used.length)return errorBox('같은 항목에 두 개의 열을 연결할 수 없습니다.');let rows=[];try{for(let n=0;n<source.length;n++){const d={};mapping.forEach((k,i)=>{if(k)d[k]=(source[n][i]||'').trim()});const cid=$('#import-class',node)?.value;const cls=d.__class_name?S.base.classes.filter(c=>c.name===d.__class_name):null;if(cls&&cls.length!==1)throw Error(`${n+1}행: 반명이 일치하는 반을 하나로 찾지 못했습니다.`);const rowClass=cls?.[0]?.id||cid;delete d.__class_name;if(entity==='students'){d.__class_id=rowClass;d.__joined_on=today();if(!d.student_no||!d.name)throw Error(`${n+1}행: 학생명 · 원생번호를 확인해 주세요.`)}if(entity==='classes'){const teacher=d.__teacher?S.base.teachers.filter(t=>t.role==='teacher'&&(t.name===d.__teacher||t.login_id===d.__teacher)):[];if(d.__teacher&&teacher.length!==1)throw Error(`${n+1}행: 담당 강사를 찾을 수 없거나 이름이 중복되었습니다.`);if(S.user.role==='admin'&&!teacher.length)throw Error(`${n+1}행: 관리자 등록에는 담임을 입력해야 합니다.`);if(S.user.role==='teacher'&&teacher.length&&teacher[0].id!==S.user.id)throw Error(`${n+1}행: 강사가 추가하는 반의 담임은 본인입니다.`);d.teacher_id=S.user.role==='teacher'?S.user.id:teacher[0].id;const assistant=d.__assistant?S.base.teachers.filter(t=>t.role==='teacher'&&t.status==='active'&&(t.name===d.__assistant||t.login_id===d.__assistant)):[];if(d.__assistant&&assistant.length!==1)throw Error(`${n+1}행: 부담임을 한 명으로 찾을 수 없습니다.`);d.assistant_teacher_id=assistant[0]?.id||null;delete d.__teacher;delete d.__assistant;d.start_date=importDate(d.start_date);d.end_date=importDate(d.end_date);d.status='active'}if(entity==='exams'){d.class_id=rowClass;d.exam_date=importDate(d.exam_date||today());d.max_score=d.max_score===''||d.max_score===undefined?100:Number(d.max_score);d.published=true}if(entity==='videos'){d.class_id=rowClass;d.video_date=importDate(d.video_date||today());d.published=true}rows.push(d)}await saveChunks(entity,rows);closeModal(true);await reload(true);toast(rows.length+'행을 저장했습니다.')}catch(e){errorBox(e.message)}}}

function scoreEntry(id){scoreEntryV16(id);MiraeOptionalTools.scoreTools(M?.node,S.data.exams.find(e=>e.id===id))}
function lessonDetail(id){lessonDetailV16(id);if(isFamily()&&M?.node)for(const b of M.node.querySelectorAll('[data-action=exam-detail]'))MiraeOptionalTools.summary(b.closest('.material-row').parentElement,b.dataset.id,childID())}
function lessonFeedback(id){return lessonEditor(id)}

function newConsult(){const requestID=crypto.randomUUID();modal('상담 신청',`<form id="consult-form">${fieldsHtml([{key:'class_id',label:'강좌',type:'select',options:classOptions(),default:currentClass(),required:true,wide:true},{key:'category',label:'상담 주제',type:'select',options:['학습 · 성적','숙제 · 학습 습관','수업 · 반 이동','진학 · 진로','출결 · 일정','기타']},{key:'contact_method',label:'희망 상담 방법',type:'select',options:['전화 상담','대면 상담','메시지']},{key:'preferred_at',label:'희망 일시',type:'datetime-local',wide:true},{key:'reason',label:'상담 내용',type:'textarea',required:true,wide:true,rows:5,placeholder:'상담하고 싶은 내용을 적어 주세요.'}])}</form>`,btn('신청하기','save-editor','','primary','consultations'));M.save=async()=>{if(!$('#consult-form').reportValidity())return;const d=collect();d.request_id=requestID;d.preferred_at=toISO(d.preferred_at);try{await api('/api/consultations',{method:'POST',body:d});closeModal(true);await reload();toast('상담을 신청했습니다.')}catch(e){errorBox(e.message)}}}
function consultDetail(id){const c=S.data.consultations.find(x=>x.id===id);if(!c)return;const staff=!isFamily(),editable=staff&&can('consultation_edit');modal(getStudent(c.student_id).name+' · 상담',`<div class="tagline">${badge(c.status)}<span>${esc(c.category)} · ${esc(c.contact_method)}</span></div><small>${timeText(c.created_at)} 신청 · ${esc(getClass(c.class_id).name)}</small><p class="preline detail-text">${esc(c.reason)}</p>${editable?fieldsHtml([{key:'status',label:'처리 상태',type:'select',options:['requested','scheduled','completed','cancelled'].map(s=>[s,badges[s][0]])},{key:'preferred_at',label:'상담 일시',type:'datetime-local'},{key:'staff_reply',label:'학부모에게 보이는 답변',type:'textarea',wide:true,rows:4},{key:'private_note',label:'강사용 메모',type:'textarea',wide:true}],{...c,preferred_at:localTime(c.preferred_at)}):`<div class="detail-section"><h3>희망 상담 일시</h3><p>${timeText(c.preferred_at)}</p></div><div class="detail-section"><h3>선생님의 답변</h3><p class="preline">${esc(c.staff_reply)||'선생님이 확인 중입니다.'}</p></div>`}`,editable?btn('저장','save-editor','','primary','check'):!staff&&['requested','scheduled'].includes(c.status)?btn('신청 취소','cancel-consult',`data-id="${c.id}"`,'danger'):'',{drawer:true});if(staff&&can('consultation_delete')){let footer=M.node.querySelector('.modal-footer');if(!footer){footer=document.createElement('footer');footer.className='modal-footer';M.node.querySelector('.modal').append(footer)}footer.insertAdjacentHTML('afterbegin',btn('상담 삭제','consult-delete',`data-id="${c.id}"`,'danger'));}if(staff)window.MiraePolish.readConsultation(c).catch(e=>toast(e.message,true));if(editable)M.save=async()=>{if(M.busy)return;const editor=M;editor.busy=true;try{const d=collect();d.preferred_at=toISO(d.preferred_at);await saveChunks('consultations',[{id:c.id,version:c.version,...d}]);closeModal(true);await reload();toast('상담 내용을 저장했습니다.')}catch(e){errorBox(e.message)}finally{editor.busy=false}}}
let ytPromise=null;
function loadYouTube(){if(window.YT?.Player)return Promise.resolve(window.YT);if(ytPromise)return ytPromise;ytPromise=new Promise((resolve,reject)=>{window.onYouTubeIframeAPIReady=()=>resolve(window.YT);const s=document.createElement('script');s.src='https://www.youtube.com/iframe_api';s.onerror=()=>{ytPromise=null;reject(Error('YouTube에 연결하지 못했습니다. 아래 버튼으로 시청해 주세요.'))};document.head.append(s);setTimeout(()=>{if(!window.YT?.Player){ytPromise=null;reject(Error('YouTube 응답이 늦어지고 있습니다. 아래 버튼으로 시청해 주세요.'))}},15000)});return ytPromise}
function saveVideoProgress(){if(!currentPlayer?.getCurrentTime||!playerVideo||!isFamily())return;let position,duration;try{position=currentPlayer.getCurrentTime();duration=currentPlayer.getDuration()}catch{return}if(Number.isFinite(position)&&Number.isFinite(duration)&&duration>0)api('/api/video-progress',{method:'POST',body:{video_id:playerVideo.id,position_seconds:position,duration_seconds:duration}}).catch(()=>{})}
function stopPlayer(){clearInterval(playTimer);playTimer=null;saveVideoProgress();try{currentPlayer?.stopVideo?.();currentPlayer?.destroy?.()}catch{}currentPlayer=null;playerVideo=null}
const ytLogo='<svg width="27" height="20" viewBox="0 0 28 20" aria-label="YouTube"><path fill="#ff0033" d="M27.4 3.1C27.1 1.7 26.1.7 24.7.4 22.4 0 14 0 14 0S5.6 0 3.3.4C1.9.7.9 1.7.6 3.1 0 5.4 0 10 0 10s0 4.6.6 6.9c.3 1.4 1.3 2.4 2.7 2.7 2.3.4 10.7.4 10.7.4s8.4 0 10.7-.4c1.4-.3 2.4-1.3 2.7-2.7.6-2.3.6-6.9.6-6.9s0-4.6-.6-6.9Z"/><path fill="white" d="m11 5.7 7.3 4.3-7.3 4.3z"/></svg>';
async function playVideo(id){const v=S.data.videos.find(x=>x.id===id);if(!v)return;return MiraeWatch.open(v.watch_source==='lesson'?{source:'lesson',lesson_id:v.lesson_id,teacher_id:v.teacher_id,youtube_id:v.youtube_id}:{source:'legacy',video_id:v.id})}

document.addEventListener('visibilitychange',()=>{if(document.hidden){saveVideoProgress();try{currentPlayer?.pauseVideo?.()}catch{}}});

function trendChart(m){const ss=m.scored;if(!ss.length)return empty('시험 결과가 쌓이면 성적 변화를 볼 수 있습니다.');const w=850,h=220,p={l:38,r:20,t:15,b:35},x=i=>ss.length===1?w/2:p.l+i/(ss.length-1)*(w-p.l-p.r),y=n=>p.t+(100-Math.max(0,Math.min(100,n)))/100*(h-p.t-p.b);const points=ss.map((s,i)=>({x:x(i),y:y(s.pct),s})),means=ss.map((s,i)=>({x:x(i),value:S.data.exam_stats[s.exam_id]?.mean==null?null:Number(S.data.exam_stats[s.exam_id].mean)/s.exam.max_score*100}));return`<div class="chart-legend"><span><i></i>학생 성적</span><span><i class="secondary"></i>반 평균</span><small>100점 환산</small></div><svg viewBox="0 0 ${w} ${h}" class="trend-chart" role="img" aria-label="시험별 학생 성적과 반 평균"><title>시험별 학생 성적과 반 평균</title>${[0,25,50,75,100].map(n=>`<line x1="${p.l}" x2="${w-p.r}" y1="${y(n)}" y2="${y(n)}" stroke="#edf0f6"/><text x="${p.l-9}" y="${y(n)+4}" text-anchor="end" fill="#8b96a9" font-size="11">${n}</text>`).join('')}<path d="${means.filter(p=>p.value!==null&&Number.isFinite(p.value)).map((p,i)=>(i?'L':'M')+p.x+','+y(p.value)).join(' ')}" fill="none" stroke="#b7c2d3" stroke-width="2" stroke-dasharray="5 5"/><path d="${points.map((p,i)=>(i?'L':'M')+p.x+','+p.y).join(' ')}" fill="none" stroke="#5276e5" stroke-width="2.6"/>${points.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="#5276e5"><title>${esc(p.s.exam.title)}: ${fmt(p.s.pct)}점</title></circle>${(ss.length<=12||i%Math.ceil(ss.length/10)===0||i===ss.length-1)?`<text x="${p.x}" y="${h-10}" text-anchor="middle" fill="#7d889b" font-size="11">${p.s.exam.exam_date.slice(5).replace('-','/')}</text>`:''}`).join('')}</svg>`}
function studentReportHTML(id){const s=getStudent(id),m=studentMetrics(id),units={};m.scored.forEach(x=>{const k=x.exam.unit||x.exam.subject||'전체';(units[k]||=[]).push(x.pct)});const delta=m.delta===null?'—':`${m.delta>0?'+':''}${fmt(m.delta)}점`;return`<article class="report-paper" id="report-paper"><header class="report-header"><div><h2>${esc(s.name)} <span>학습 리포트</span></h2><p>${esc(s.school)} ${esc(s.grade)}</p></div><div class="report-period"><strong>${S.start} — ${S.end}</strong><small>${S.classId?esc(getClass(S.classId).name):'조회 가능한 전체 강좌'}</small></div></header>${!isFamily()?`<section class="report-school-summary"><strong>내신성적</strong>${MiraeGradeHistory.badge(id,gradeBasis())}<span>수학·과학 전체 기록 보기</span></section>`:''}${stats([['평균 성적',fmt(m.average),'점','100점 환산 · '+m.count+'회 응시'],['성적 변화',delta,'',m.count>=6?'직전 3회와 최근 3회 평균 비교':'첫 시험 대비 최근 시험'],['과제 제출',m.submitted+'/'+m.homework,'건','기한 초과 미제출 '+m.missing+'건'],['출석률',fmt(m.attendance),'%','출석 기록 기준 · 지각 포함']])}<section class="report-section"><h3>성적의 흐름</h3>${trendChart(m)}</section><section class="report-section"><h3>단원별 학습 결과</h3>${Object.keys(units).length?`<div class="unit-list">${Object.entries(units).sort((a,b)=>avg(a[1])-avg(b[1])).map(([k,v])=>`<div class="unit-row"><span>${esc(k)}</span><div class="unit-track"><i style="width:${avg(v)}%"></i></div><strong>${fmt(avg(v))}점</strong><small>${v.length}회</small></div>`).join('')}</div>`:empty('단원별 결과가 없습니다.')}</section><section class="report-section"><h3>시험별 상세 기록</h3>${simpleTable([{key:'date',label:'날짜',render:r=>dateText(r.exam.exam_date,true)},{key:'title',label:'시험',render:r=>esc(r.exam.title)},{key:'class',label:'강좌',render:r=>esc(getClass(r.exam.class_id).name)},{key:'score',label:'점수',render:r=>`<strong>${fmt(r.score)}</strong> / ${r.exam.max_score}`},{key:'homework_grade',label:'과제 검사',render:r=>r.exam.lesson_id?esc(gradeLabel((S.data.feedback||[]).find(f=>f.lesson_id===r.exam.lesson_id&&f.student_id===id)?.homework_grade,r.exam.class_id,r.exam.lesson_id)):'—'},{key:'mean',label:'반 평균',render:r=>fmt(S.data.exam_stats[r.exam_id]?.mean)},{key:'comment',label:'코멘트',render:r=>esc(r.comment)||'—'}],[...m.scored].reverse())}</section><section class="report-section"><h3>선생님의 코멘트</h3>${feedbackList(id)}</section><footer class="report-footer">${esc(loginDesign.academy_name||C.BRAND||'미래탐구')} · ${dateText(today(),true)} 발행</footer></article>`}
function renderReports(){const student=isFamily();$('#main').innerHTML=head('학습 리포트',student?'성적과 과제, 수업 태도로 확인하는 배움의 변화.':'선생님의 기준에 해당하는 학생을 놓치지 않도록.',student?btn('인쇄 · PDF 저장','print-report','','','print'):(btn('기준 저장','save-criteria','','','check')+btn('내신 성적 입력','navigate','data-view="school_grades"','grade-entry85','edit')))+context({view:!student})+reportScopeControls()+(student?studentReportHTML(childID()):`<section class="criteria-panel"><div class="criteria-title"><strong>${icon('filter',16)} 관리대상 기준</strong><select id="criteria-logic"><option value="any" ${S.criteria.logic==='any'?'selected':''}>한 가지라도 해당</option><option value="all" ${S.criteria.logic==='all'?'selected':''}>선택한 조건 모두 해당</option></select></div><div class="criteria-fields">${[['average','averageOn','평균','점 미만',S.criteria.average],['drop','dropOn','성적 하락','점 이상',S.criteria.drop],['missing','missingOn','기한 초과 미제출','건 이상',S.criteria.missing],['absence','absenceOn','결석','회 이상',S.criteria.absence]].map(([key,on,label,suffix,n])=>`<label class="criterion"><input type="checkbox" data-criterion="${on}" ${S.criteria[on]?'checked':''}><span>${label}</span><input type="number" min="0" step="1" data-criterion="${key}" value="${n}"><span>${suffix}</span></label>`).join('')}</div><div class="criteria-bottom"><label>성적 조건 최소 응시 <input type="number" min="1" max="100" data-criterion="minimum" value="${S.criteria.minimum}">회</label><label class="check-label"><input type="checkbox" data-criterion="currentOnly" ${S.criteria.currentOnly?'checked':''}>현재 재원만</label><label class="check-label"><input type="checkbox" data-criterion="only" ${S.criteria.only?'checked':''}>해당 학생만 보기</label><span role="button" tabindex="0" class="ui-help72" aria-label="도움말 설명 보기" data-help-title72="도움말" data-help72="성적 하락: 6회 이상은 최근 3회와 직전 3회 평균, 그 미만은 첫 시험과 최근 시험 비교">?</span></div></section><div id="grid-zone"></div>`);if(!student)renderGridZone()}
function studentReport(id){queueMicrotask(()=>MiraeGradeHistory.paint());modal(getStudent(id).name+' · 학습 리포트',studentReportHTML(id),btn('인쇄 · PDF 저장','print-report','','primary','print'),{wide:true})}
async function printReport(){const root=M?.node||$('#main');await MiraeMakeupStats.ready(root);if(!root?.isConnected)return;document.body.classList.toggle('print-modal',!!M);window.print();setTimeout(()=>document.body.classList.remove('print-modal'),300)}

function passwordModal(){modal('비밀번호 변경',`<form id="password-form">${fieldsHtml([{key:'current',label:'현재 비밀번호',type:'password',required:true,wide:true,maxlength:200},{key:'new',label:'새 비밀번호',type:'password',required:true,wide:true,maxlength:200},{key:'confirm',label:'새 비밀번호 확인',type:'password',required:true,wide:true,maxlength:200}])}</form>`,btn('취소','close-modal')+btn('비밀번호 변경','save-editor','','primary','check'));M.isPassword=true;$('#password-form [name=current]').autocomplete='current-password';$('#password-form').onsubmit=e=>{e.preventDefault();M?.save?.()};M.save=async()=>{if(!$('#password-form').reportValidity())return;const d=collect();if(d.new!==d.confirm)return errorBox('새 비밀번호가 서로 다릅니다.');try{const r=await api('/api/change-password',{method:'POST',body:{current:d.current,new:d.new,confirm:d.confirm}});clearClientCaches();S.token=r.token;S.user=r.user;store.set('mirae-v2-session',r.token);closeAll();await reload(true);toast('비밀번호를 변경했습니다.')}catch(e){errorBox(e.message)}}}

function legacyRegistrationRemoved(){modal('학생 등록',`<div class="line-list">${[['roster-picker','students','타임넷 학생 불러오기','연결된 PC에서 조회한 명단으로 등록합니다.'],['manual-student','edit','학생 직접 등록','이름 · 원생번호를 등록한 뒤 학부모 계정을 배정합니다.'],['import-students','grid','엑셀에서 한 번에 등록','열 순서에 관계없이 붙여넣고 연결합니다.']].map(([act,ic,t,s])=>`<button class="choice-row" data-action="${act}"><span class="avatar">${icon(ic,20)}</span><span><strong>${t}</strong><small>${s}</small></span>${icon('chevron')}</button>`).join('')}</div>`,btn('닫기','close-modal'))}
async function loadDirectory(){
 const token=S.token,stamp=S.base.timenet_meta?.updated_at||'';
 if(directoryCache?.token===token&&directoryCache.stamp===stamp)return directoryCache.promise;
 const entry={token,stamp,promise:null};entry.promise=api('/api/timenet/directory').then(result=>(result.rows||[]).map(row=>({...row,_search:[row.name,row.student_no,row.school,...(row.classes||[]).map(c=>c.name||'')].join(' ').normalize('NFKC').toLocaleLowerCase('ko-KR')})));
 directoryCache=entry;try{return await entry.promise}catch(error){if(directoryCache===entry)directoryCache=null;throw error}
}
function rosterPicker(){
 let rows=[],ready=false;modal('타임넷 학생 선택',`<div class="search-wrap roster-search">${icon('search')}<input class="input" id="roster-query" placeholder="학생명 · 원생번호 · 학교 · 반" autocomplete="off"></div><div class="directory-tools"><span>${btn('다시 불러오기','timenet-refresh','','ghost sm','refresh')}</span><small data-directory-age>${directoryAge()}</small></div><div id="roster-results">${empty('저장된 명단을 가져오고 있습니다.')}</div>`,'',{wide:true});
 const node=M.node;node.classList.add('roster-picker-modal');const refreshShared=()=>loadDirectory().then(data=>{if(node.isConnected){rows=data;ready=true;draw()}});window.addEventListener('mirae-directory-updated',refreshShared);M.cleanup=()=>window.removeEventListener('mirae-directory-updated',refreshShared);
 function draw(){if(!node.isConnected||!ready)return;const q=$('#roster-query',node).value.trim().normalize('NFKC').toLocaleLowerCase('ko-KR');
  if(!q){$('#roster-results',node).innerHTML=empty(rows.length?'학생명 또는 원생번호를 입력해 주세요.':'저장된 명단이 없습니다. 학생 목록을 먼저 불러와 주세요.');return}
  const matches=rows.filter(row=>row._search.includes(q));const shown=matches.slice(0,100);
  $('#roster-results',node).innerHTML=shown.length?`<small class="muted">${matches.length.toLocaleString()}명${matches.length>100?' · 앞 100명 표시':''}</small><div class="line-list">${shown.map(row=>`<button class="choice-row roster-one-line" data-roster="${esc(row.student_no)}"><strong>${esc(row.name)}</strong><span>${esc(row.school)}</span><span>${esc(row.grade)}</span><small title="${esc((row.classes||[]).map(c=>typeof c==='string'?c:c.name||c.class_name).join(' · '))}">${esc((row.classes||[]).map(c=>typeof c==='string'?c:c.name||c.class_name).join(' · '))}</small></button>`).join('')}</div>`:empty('일치하는 학생이 없습니다.');
  $$('[data-roster]',node).forEach(button=>button.onclick=()=>enrollRoster(shown.find(row=>row.student_no===button.dataset.roster)));
 }
 $('#roster-query',node).oninput=draw;
 loadDirectory().then(data=>{rows=data;ready=true;draw()}).catch(error=>{if(node.isConnected)$('#roster-results',node).innerHTML=`<div class="alert error">${esc(error.message)}</div>`});
}
function enrollRoster(s){modal(s.name+' · 학생 등록',`<div class="tagline"><span class="badge">원생번호 ${esc(s.student_no)}</span><span>${esc(s.school)} ${esc(s.grade)}</span></div><p class="muted">${esc((s.classes||[]).map(c=>typeof c==='string'?c:c.name||c.class_name).join(' · '))}</p><form id="roster-enroll">${fieldsHtml([{key:'class_id',label:'등록할 강좌',type:'select',options:classOptions(),default:currentClass(),wide:true,required:true},{key:'joined_on',label:'첫 수업일',type:'select',options:[],required:true}])}</form>`,btn('선택한 학생 등록','save-editor','','primary','check'));MiraeAttendanceCore.bindLessonSelect($('#roster-enroll'),S.base.classes,'class_id','joined_on');M.save=async()=>{if(!$('#roster-enroll').reportValidity())return;try{await api('/api/timenet/enroll',{method:'POST',body:{rows:[{student_no:s.student_no,...collect()}]}});closeAll();await reload(true);toast(s.name+' 학생을 등록했습니다.')}catch(e){errorBox(e.message)}}}
function commandPalette(){document.body.classList.remove('menu-open');$('.sidebar')?.classList.remove('open');modal('빠른 이동',`<input class="input" id="command-input" placeholder="화면 · 학생 · 강좌 검색" autocomplete="off" aria-label="빠른 이동 검색"><div id="command-results" aria-label="검색 결과"></div>`,'',{wide:false,readonly:true});const node=M.node;node.classList.add('command-palette');function draw(){const q=$('#command-input',node).value.trim().toLowerCase();let html=accessibleNav().filter(([,l])=>l.toLowerCase().includes(q)).map(([k,l,ic])=>`<button class="command-item" data-command-view="${k}">${icon(ic)}<strong>${esc(l)}</strong><span class="grow"></span><kbd>↵</kbd></button>`).join('');if(q&&!isFamily())html+=S.base.students.filter(s=>[s.name,s.school,s.student_no].join(' ').toLowerCase().includes(q)).slice(0,12).map(s=>`<button class="command-item" data-command-student="${s.id}">${icon('students')}<span>${esc(s.name)}<small>${esc(s.school)} ${esc(s.grade)}</small></span></button>`).join('');$('#command-results',node).innerHTML=html||'<div class="command-empty">검색 결과가 없습니다.</div>';$$('[data-command-view]',node).forEach(x=>x.onclick=()=>{closeModal(true);navigate(x.dataset.commandView)});$$('[data-command-student]',node).forEach(x=>x.onclick=()=>{closeModal(true);studentDetail(x.dataset.commandStudent)});const items=$$('#command-results button',node);items.forEach((b,i)=>b.onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const next=i+(e.key==='ArrowDown'?1:-1);(items[next]||$('#command-input',node)).focus();}if(e.key==='Home'){e.preventDefault();items[0]?.focus()}if(e.key==='End'){e.preventDefault();items.at(-1)?.focus()}})}$('#command-input',node).oninput=draw;$('#command-input',node).onkeydown=e=>{if(e.key==='Enter'){$('#command-results button',node)?.click();e.preventDefault()}if(e.key==='ArrowDown'){$('#command-results button',node)?.focus();e.preventDefault()}};draw()}
function consultUnreadCount(){return isFamily()?0:window.MiraePolish.unread(S.data.consultations)}
function paintConsultBadge(){const count=consultUnreadCount();$$('.nav-item[data-view="consultations"]').forEach(b=>{b.querySelector('.count')?.remove();if(count){const n=document.createElement('span');n.className='count';n.textContent=count;b.append(n)}})}
window.MiraePolish.configure({user:()=>S.user,isAdmin:isSuper,can,changed:paintConsultBadge,modal,editor:()=>M,close:()=>closeModal(true),toast});

function renderLogin(){MiraePlatform?.syncUser(null);MiraeMessenger.stop();MiraeExperience.forget();renderUnifiedLogin()}
function pushLanding(){const requested=new URL(location.href).searchParams.get('screen');return accessibleNav().some(([k])=>k===requested)?requested:defaultView()}
async function finishLogin(result){MiraeDrafts.clearSession();S.courseID='';S.studentId='';S.classId='';S.dashboardScope='homeroom';clearClientCaches();window.MiraePolish.reset();S.user=result.user;S.token=result.token;store.set('mirae-v2-session',S.token);S.view=pushLanding();S.classId='';S.q='';S.selected.clear();S.loading=true;document.body.classList.remove('at-login');render();$('#main').innerHTML=head('클래스룸')+'<div class="workspace-loading" role="status"><span class="activity-orb"></span><div class="skeleton-lines"><i></i><i></i><i></i></div></div>';await reload(true);const storageNotice=window.MiraePush?.takeStorageNotice?.();if(storageNotice)toast(storageNotice,true);void window.MiraePC?.claimLogin(true).catch(e=>window.MiraeStore.log('pc.login_wait',{message:e.message}));void window.MiraeRosterIntegrity?.start();window.MiraeFastReads?.start();window.MiraeSchoolGrades?.prefetch();void MiraeInbox.refresh();void window.MiraeMSCache?.start(true);void window.MiraePC?.auto();void window.MiraeTimeNetCounsel?.start().catch(()=>{});await applyReportLanding();await MiraeMessenger.launchFromURL();window.MiraePush?.startUser(S.user);window.MiraeMessenger?.start();window.MiraePolish.refreshConsultations();window.MiraeActivity.start(S.user,'login')}
function selectLoginStudent(result){modal('학생 선택',`<div class="line-list">${result.candidates.map(s=>`<button class="choice-row" data-login-student="${s.id}"><span class="avatar">${esc(s.name.slice(-2))}</span><span><strong>${esc(s.name)}</strong><small>${esc(s.school)} ${esc(s.grade)}</small><small>${esc((s.classes||[]).map(c=>typeof c==='string'?c:c.name).join(' · '))}</small></span>${icon('chevron')}</button>`).join('')}</div>`);$$('[data-login-student]',M.node).forEach(b=>b.onclick=async()=>{try{const r=await api('/api/select-student',{method:'POST',body:{challenge:result.challenge,id:b.dataset.loginStudent}});closeModal(true);await finishLogin(r)}catch(e){errorBox(e.message)}})}

