 'select-class':async b=>{S.classId=b.dataset.id;const c=getClass(S.classId);S.start=c.start_date;S.end=c.end_date;S.view='dashboard';await reload()},
 'exam-detail':b=>{const e=S.data.exams.find(e=>e.id===b.dataset.id),s=S.data.scores.find(s=>s.exam_id===e.id&&s.student_id===childID()),stats=S.data.exam_stats[e.id]||{};modal(e.title,`<div class="tagline">${dateText(e.exam_date,true)} · ${esc(e.unit)}</div><div class="exam-score">${s?.absent?'미응시':fmt(s?.score)}<small> / ${e.max_score}점</small></div>${e.lesson_id?`<div class="tagline"><span class="badge">과제 검사 · ${esc(gradeLabel(S.data.feedback.find(f=>f.lesson_id===e.lesson_id&&f.student_id===childID())?.homework_grade,e.class_id,e.lesson_id))}</span></div>`:''}<p>반 평균 ${fmt(stats.mean)}점 · 응시 ${stats.count||0}명${stats.rank?' · 공동 '+stats.rank+'등':''}</p>${s?.comment?`<p class="preline review-message">${esc(s.comment)}</p>`:''}`,btn('학습 리포트','student-report',`data-id="${childID()}"`,'primary','reports'))},
 'cancel-consult':async b=>{if(!(await MiraeDialog.confirm('상담 신청을 취소할까요?')))return;await api('/api/consultations/'+b.dataset.id+'/cancel',{method:'POST'});closeModal(true);await reload();toast('상담 신청을 취소했습니다.')},
 'duplicate-lessons':()=>{const rows=S.data.lessons.filter(x=>S.selected.has(x.id));if(!rows.length)return;modal('선택한 수업 복제',fieldsHtml([{key:'days',label:'원래 날짜에서 며칠 뒤로 복제할까요?',type:'number',default:7,required:true},{key:'class_id',label:'복제할 강좌',type:'select',options:[['','각 수업의 원래 반'],...classOptions()],wide:true}]),btn('복제','save-editor','','primary','copy'));M.save=async()=>{const d=collect(),days=Number(d.days);if(!Number.isInteger(days)||Math.abs(days)>3650)return errorBox('이동할 날짜를 정수로 입력해 주세요.');const items=rows.map(l=>({class_id:d.class_id||l.class_id,lesson_date:addDays(l.lesson_date,days),title:l.title,progress:l.progress,homework:l.homework,online_required:l.online_required,due_at:l.due_at?new Date(new Date(l.due_at).getTime()+days*86400000).toISOString():null,notice:l.notice,published:false}));try{await saveChunks('lessons',items);closeModal(true);S.selected.clear();await reload();toast('비공개 수업으로 복제했습니다.')}catch(e){errorBox(e.message)}}},
 refresh:async()=>{MiraeDrafts.capture();S.pending.clear();await reload(true)},
 'mobile-menu':()=>{const open=$('.sidebar')?.classList.toggle('open');document.body.classList.toggle('menu-open',!!open)}, 'login-tab':b=>renderLogin(b.dataset.tab),
 logout:async()=>{window.MiraePolish.reset();loginSnapshot=null;window.MiraePush?.logout();try{await api('/api/logout',{method:'POST'})}catch{}stopPlayer();clearClientCaches();S.generation++;S.token='';S.user=null;S.studentId='';S.parents=[];store.del('mirae-v2-session');S.base={students:[],classes:[],enrollments:[],teachers:[]};S.data={lessons:[],exams:[],scores:[],feedback:[],submissions:[],attachments:[],lesson_files:[],consultations:[],videos:[],video_progress:[],exam_stats:{}};window.dispatchEvent(new Event('mirae-logged-out'));S.accounts=[];S.pending.clear();S.selected.clear();S.undo=[];S.editing=false;closeAll();MiraeDrafts.clearSession();document.querySelectorAll('.modal-overlay,.mc-profile-overlay').forEach(n=>n.remove());renderLogin()},
