document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(b&&actions[b.dataset.action]){e.preventDefault();const mutating=['save-editor','save-grid','save-timenet','save-storage','save-criteria','cancel-consult'].includes(b.dataset.action),m=mutating?M:null;if(S.user&&actionCap(b.dataset.action)&&!can(actionCap(b.dataset.action))&&!(b.dataset.action==='mswitch-link'&&can('attendance_notify')))return;if(mutating&&b.disabled)return;if(mutating){b.disabled=true;if(m&&b.dataset.action!=='save-editor')m.busy=true}try{await actions[b.dataset.action](b)}catch(err){if(M)errorBox(err.message);else toast(err.message,true)}finally{if(mutating)b.disabled=false;if(m)m.busy=false}return}const th=e.target.closest('#data-grid th[data-sort]');if(th&&th.dataset.sort!=='_action'){const k=th.dataset.sort,old=S.sort.find(x=>x.key===k),d=old?.dir===1?-1:1;S.sort=e.shiftKey?S.sort.filter(x=>x.key!==k):[];S.sort.push({key:k,dir:d});drawGrid()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action=save-import],[data-action=submit-photos]');if(!b||b._saveWrapped||!b.onclick)return;b._saveWrapped=true;const original=b.onclick;b.onclick=async function(event){if(b._saving)return;b._saving=true;const m=M;if(m)m.busy=true;try{return await original.call(this,event)}catch(err){errorBox(err.message)}finally{b._saving=false;if(m)m.busy=false}}},true);
document.addEventListener('input',e=>{const t=e.target;if(t.id==='grid-search'){S.q=t.value;S.page=1;drawGrid()}if(t.matches('.cell-input')){const id=t.dataset.row,key=t.dataset.field,changes={...(S.pending.get(id)||{})};S.undo.push({id,key,previous:changes[key],had:Object.hasOwn(changes,key)});changes[key]=t.value;S.pending.set(id,changes);t.classList.add('dirty');let b=$('[data-action=save-grid]');if(!b){$('.tool-right')?.insertAdjacentHTML('afterbegin',btn('변경 저장','save-grid','','primary sm','check'));b=$('[data-action=save-grid]')}if(b)b.textContent=S.pending.size+'행 저장'}if(t.dataset.criterion){S.criteria[t.dataset.criterion]=t.type==='checkbox'?t.checked:Math.max(0,Number(t.value)||0);if(t.dataset.criterion==='minimum')S.criteria.minimum=Math.max(1,S.criteria.minimum);drawGrid()}});
