function safeUser(row,role){if(!row)throw Error('계정을 확인하세요.');const {password,...u}=row;return {...u,permissions:window.MiraeRoles.rank(row,D.settings?.role_policy).permissions,role:role||u.role||'parent',preferences:u.preferences||{},must_change:!!u.must_change}}
const rememberDefault=()=>pref.get('remember-login',window.MiraePush?.mobile()||false);
function tokenFor(){if(!db.auth?.session)throw Error('다시 로그인해 주세요.');return db.auth.session}
