function identify(){const row=db.identity;if(!row||db.auth?.session!==S.token)throw Error('로그인이 만료되었습니다. 다시 로그인해 주세요.');D.actorID=row.id;D.role=row.role;return safeUser(row,row.role)}
function accountRow(a){return(a.role==='student'?D.students:a.role==='parent'?D.parents:D.accounts).find(x=>x.id===a.id)}
function passwordOf(){return undefined}
function assertAdmin(a){if(a.role!=='admin')throw Error('최종관리자 메뉴입니다.')}
function assertStaff(a){if(['parent','student'].includes(a.role))throw Error('강사 메뉴입니다.')}
function normalizeID(s){const id=String(s||'').normalize('NFKC').trim().toLowerCase();if(!/^[a-z0-9가-힣._@-]{1,100}$/.test(id))throw Error('아이디 형식을 확인하세요.');return id}
function uniqueID(id,except){if([...D.accounts,...D.parents,...D.students.filter(s=>s.login_id&&!s.account_deleted)].some(x=>x.id!==except&&x.login_id===id))throw Error('이미 사용 중인 아이디입니다.')}
