  if(['students','classes','accounts'].includes(entity)&&!String(v.name||'').trim())throw Error('이름을 입력해 주세요.');
  if(entity==='accounts'){if(old&&!staffManageAllowed(a,old)||!window.MiraeRoles.manageable(a,{...v,role:v.role||'teacher',id:old?.id||'new'},D.settings.role_policy))throw Error('본인보다 낮은 직급의 강사만 변경할 수 있습니다.');if(Object.hasOwn(r,'login_history_scope')&&!['inherit','none','own','all'].includes(r.login_history_scope))throw Error('로그인 이력 권한을 확인하세요.');if(a.role!=='admin'&&r.login_history_scope==='all'&&!can('login_history_all',a))throw Error('모든 사용자 조회 권한은 부여할 수 없습니다.');const subject=window.MiraeSubject;if(Object.hasOwn(r,'subject_scope')&&!MiraeSubject.OPTIONS.some(x=>x[0]===r.subject_scope))throw Error('분류는 전체·수학·주말과학·영재·과고 중에서 선택하세요.');r.subject_scope=v.role==='admin'?'all':subject.normalize(v.subject_scope);r.subject_scope2=r.subject_scope==='all'?'':v.subject_scope2||'';if(r.subject_scope2&&(!subject.OPTIONS.some(x=>x[0]===r.subject_scope2)||r.subject_scope2==='all'||r.subject_scope2===r.subject_scope))throw Error('두 번째 분류를 확인하세요.');if(old&&!subject.staffAllowed(D,a,old)||!subject.contains(a,{...r,role:v.role}))throw Error('지정된 과목의 강사만 관리할 수 있습니다.');if(a.role!=='admin'&&(old?.role==='admin'||v.role==='admin'))throw Error('최고관리자 계정은 최고관리자만 변경할 수 있습니다.');if(v.rank_id&&!window.MiraeRoles.policy(D.settings.role_policy).ranks.some(x=>x.id===v.rank_id))throw Error('직급을 확인하세요.');r.login_id=normalizeID(v.login_id);uniqueID(r.login_id,old?.id);if(!old&&!r.password)throw Error('초기 비밀번호를 입력해 주세요.');if(r.password)r.auth_version=(old?.auth_version||0)+1;if(!old)r.must_change=false;if(!['admin','teacher'].includes(v.role))throw Error('권한을 확인해 주세요.');if(a.role==='admin'&&old?.id===a.id&&(v.role!=='admin'||v.status!=='active'))throw Error('로그인 중인 관리자 본인은 비활성화하거나 강사로 바꿀 수 없습니다.')}
  if(entity==='classes'){if(old&&v.name!==old.name&&!can('classes_all_edit',a))throw Error('강좌명 변경에는 모든 강좌 수정 권한이 필요합니다.');if(!window.MiraeSubject.classAllowed(D,a,v))throw Error('지정된 과목의 반만 등록·수정할 수 있습니다.');for(const id of MiraeTeam.members(v))if(id&&!window.MiraeSubject.staffAllowed(D,a,D.accounts.find(t=>t.id===id)))throw Error('지정된 과목의 강사를 선택하세요.');if(Object.hasOwn(r,'syllabus')){requireCap(a,'syllabus_edit');if(!old||JSON.stringify(r.syllabus)!==JSON.stringify(old.syllabus||[]))r.syllabus=window.MiraePlan.validate(v,r.syllabus)}if(a.role==='teacher'&&!can('all_classes',a)&&!can('classes_all_edit',a)&&v.teacher_id!==a.id&&!old)throw Error('본인 담당 강좌으로 등록하세요.');if(Object.hasOwn(r,'weekdays')||Object.hasOwn(r,'start_time')||Object.hasOwn(r,'end_time'))window.MiraeAttendanceCore.validateSchedule(v);}
