 if(/^\/api\/classes\/[^/]+\/homework-policy$/.test(route)&&!write){const auth=await MiraePush.ensureSession();return db.rpc('mirae_classroom_access',{p_session:auth.session,p_action:'homework-policy',p_data:{class_id:route.split('/')[3]}});}if(route==='/api/makeups/stats'){const auth=await MiraePush.ensureSession();return db.rpc('mirae_makeup_stats',{p_session:auth.session,p_data:body});}
 if(route.startsWith('/api/makeups/')){const auth=await MiraePush.ensureSession();return db.rpc('mirae_makeups',{p_session:auth.session,p_action:route.split('/').at(-1),p_data:body});}
 if(route==='/api/timenet/settings'){const auth=await MiraePush.ensureSession();return db.rpc('mirae_timenet_account',{p_session:auth.session,p_action:write?'save':'get',p_data:body});}if(route==='/api/timenet/pc-config'){await MiraePush.ensureSession();return{managed:true};}
 if(route==='/api/attendance/read'&&!write){const q=new URL(path,'https://browser.invalid').searchParams;const auth=await MiraePush.ensureSession();return db.rpc('mirae_registration_support',{p_session:auth.session,p_action:'book-read',p_data:{class_id:q.get('class_id'),month:q.get('month'),start:q.get('start'),end:q.get('end')}},{fresh:options.fresh===true});}if(route==='/api/registration/match-phones')return MiraeUpgrade.call('match-phones',body);if(route==='/api/attendance/save'&&write&&body.mode==='book'){const result=await MiraeUpgrade.call('book-save',body);await refreshPrivateState();inflightReads.clear();return result;}if(route==='/api/timenet/registration-identities')return MiraeStudentAccounts.call('identity_index');if(route==='/api/audit')return MiraeAudit.call('list');if(write&&route.startsWith('/api/attendance/'))await MiraeMessages.load();
