 if(/^\/api\/students\/[^/]+\/parent$/.test(route)){const result=await MiraeStudentAccounts.call(write?'parent_assign':'parent_context',{...body,student_id:route.split('/')[3]});if(write){db.lastRefresh=0;await refreshPrivateState();inflightReads.clear()}return result}
 if(route==='/api/parents/search')return MiraeStudentAccounts.call('parent_search',{student_id:url.searchParams.get('student_id'),query:url.searchParams.get('q')||'',recommend:url.searchParams.get('recommend')==='1'});
 if(route==='/api/timenet/enroll'||route==='/api/parents/create'){const result=await MiraeStudentAccounts.call(route.endsWith('enroll')?'enroll':'parent_create',body);await refreshPrivateState();inflightReads.clear();return result}
