 mountTimenetSettings();const relay=document.createElement('section');relay.className='section settings-section';$('#main').insertBefore(relay,$('#timenet-settings').closest('section'));window.MiraePC?.mountSettings(relay); $('#v2-backup')?.addEventListener('click',async()=>{try{const data=await api('/api/v2/backup');downloadBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'mirae-v2-backup-'+today()+'.json')}catch(e){toast(e.message,true)}});
