function canEditSyllabus(c){return !!c&&can('syllabus_edit')&&MiraeSubject.classAllowed(D,S.user,c)&&(can('all_classes')||can('classes_all_edit')||MiraeTeam.has(c,S.user.id))}function canManageClass(c){return !!c&&can('class_edit')&&MiraeSubject.classAllowed(D,S.user,c)&&(can('all_classes')||can('classes_all_edit')||MiraeTeam.has(c,S.user.id))}function attendanceClasses(){const a=localActor();return D.classes.filter(c=>MiraeSubject.classAllowed(D,a,c)&&(can('all_classes',a)||can('attendance_all_view',a)||MiraeTeam.has(c,a.id)))}
