function renderReconnect(error){
 $('#app').innerHTML='<main class="session-reconnect"><span class="reconnect-icon">'+icon('refresh',28)+'</span><h1>연결을 다시 확인해 주세요</h1><p>'+esc(error.code==='NETWORK_ERROR'?'인터넷 연결이 원활하지 않습니다. 연결 후 다시 시도해 주세요.':error.message||'인터넷 연결이 잠시 끊겼습니다.')+'</p><button class="btn primary" data-session-retry>다시 연결</button></main>';
 const retry=()=>{window.removeEventListener('online',retry);if($('#app [data-session-retry]'))void start()};$('#app [data-session-retry]').onclick=retry;window.addEventListener('online',retry,{once:true});
}
