function promotionMarkup(d){return d.buttons?.length?`<div class="promotion-links" data-count="${d.buttons.length}" aria-label="학원 안내 링크">${d.buttons.map((b,i)=>`<a class="promotion-link" href="${esc(b.url)}" target="_blank" rel="noopener noreferrer"><span class="promotion-index">${String(i+1).padStart(2,'0')}</span><strong>${esc(b.label)}</strong><span aria-hidden="true">↗</span></a>`).join('')}</div>`:''}
function loginMarkup(d=loginDesign,preview=false){return `<div class="login-layout ${preview?'design-preview':''}" data-layout="${d.layout}" data-align="${d.alignment}"><section class="login-brand"><div class="logo"><span class="academy-seal" aria-hidden="true">未</span><div><strong data-login-copy="academy_name">${esc(d.academy_name)}</strong></div></div><div class="login-story"><div class="eyebrow" data-login-copy="eyebrow">${esc(d.eyebrow)}</div><h1 data-login-copy="headline">${esc(d.headline)}</h1><p data-login-copy="description">${esc(d.description)}</p><div class="login-notice-rule"></div></div><div class="login-promotions">${promotionMarkup(d)}</div><div class="brand-bottom"><span>수업 · 기록 · 소통</span><span>${new Date().getFullYear()}</span></div></section><section class="login-side"><div class="login-form"><div class="mobile-logo"><span class="academy-seal">未</span><strong data-login-copy="academy_name">${esc(d.academy_name)}</strong></div><span class="login-form-number">CLASSROOM / 01</span><h2 data-login-copy="form_title">${esc(d.form_title)}</h2><p class="subtitle" data-login-copy="form_subtitle">${esc(d.form_subtitle)}</p><form ${preview?'class="preview-form"':'id="login-form"'}>${fieldsHtml([{key:'name',label:'아이디',placeholder:'아이디를 입력해 주세요',required:true,wide:true,maxlength:100},{key:'password',label:'비밀번호',type:'password',required:true,wide:true,maxlength:200}])}<div class="inline-error hidden" id="${preview?'preview-error':'login-error'}" role="alert"></div><button type="${preview?'button':'submit'}" class="btn primary login-submit"><span class="login-button-label">로그인</span><span class="login-button-icon">${icon('arrow')}</span></button><div class="login-activity" ${preview?'':'id="login-activity"'} role="status" aria-live="polite" hidden><span class="activity-orb"></span><div><strong>접속 정보를 확인하고 있습니다.</strong><small>잠시만 기다려 주세요.</small></div></div></form><small class="login-foot" data-login-copy="footer">${esc(d.footer)}</small></div></section></div>`}
