let timenetBusy=false,timenetPending=null;
async function refreshTimenet(mode='roster'){
 if(isFamily()||timenetBusy)return;const actorID=S.user?.id;
 if(timenetPending?.owner!==actorID)timenetPending=null;
 if(mode==='roster'){let meta;try{meta=await api('/api/timenet/meta');}catch(e){toast('명단 갱신 시각을 확인하지 못했습니다. '+e.message,true);return;}if(actorID!==S.user?.id)return;S.base.timenet_meta=meta;paintDirectoryAge();const stamp=meta.updated_at,updated=stamp&&!Number.isNaN(Date.parse(stamp))?new Date(stamp).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}):'아직 갱신된 명단이 없습니다.';if(!await MiraeUX85.confirmRoster(updated))return;}
 const op=mode==='roster'?window.MiraeProgress.begin('타임넷 전체 학생 명단'):null;
 if(mode==='roster'&&!op)return;
 timenetBusy=true;
 const current=()=>actorID===S.user?.id;
 async function saveReceived(){
  if(!current())throw Error('로그인 계정이 바뀌어 명단 저장을 중단했습니다.');
  const r=timenetPending?.result;if(!r)throw Error('저장할 명단이 없습니다.');
  op?.update({stage:5,label:'받은 명단 저장중',status_text:r.students.length.toLocaleString()+'명 · 사이트에 저장중',received:r.students.length});
  db.log('timenet.cache.start',{count:r.students.length});
  const saved=await api('/api/timenet/cache',{method:'POST',body:{...r,_site_owner:actorID}});
  db.log('timenet.cache.complete',{count:r.students.length});timenetPending=null;
  if(!current())return;directoryCache=null;op?.done(r.students.length+'명 저장 완료');
  try{S.base.timenet_meta={updated_at:saved.updated_at||r.fetched_at||new Date().toISOString()};paintDirectoryAge();if(current()){window.dispatchEvent(new Event('mirae-directory-updated'));toast('명단 불러오기 완료')}}catch(e){toast('명단 저장은 완료했습니다. 화면을 다시 열어 주세요. '+e.message,true)}
 }
 function failed(e){if(!current())return;if(['TIMENET_CACHE77_STALE','TIMENET_CACHE77_JOB'].includes(e.code))timenetPending=null;if(timenetPending&&!e.message.startsWith('명단 수신 완료'))e.message='명단 수신 완료 · 사이트 저장 실패: '+e.message;toast(e.message,true);const status=$('#timenet-result');if(status)status.textContent=e.message;db.log('timenet.failed',{message:e.message,received_retained:!!timenetPending});op?.fail(e.message,timenetPending?async()=>{if(timenetBusy)return;timenetBusy=true;op.resume();try{await saveReceived()}catch(e){failed(e)}finally{timenetBusy=false}}:null)}
 try{
  if(mode==='roster'&&timenetPending){await saveReceived();return}
  const config=await api('/api/timenet/pc-config');if(!current())throw Error('로그인 계정이 바뀌어 조회를 중단했습니다.');
  const r=await window.MiraePC.run(mode==='check_account'?'timenet.check':'timenet.roster',{config,_site_owner:actorID},{onProgress:p=>op?.update(p)});
  if(!current())throw Error('로그인 계정이 바뀌어 조회 결과를 저장하지 않았습니다.');
  if(mode==='check_account'){toast('연결 확인 완료');const status=$('#timenet-result');if(status)status.textContent='연결 확인 완료';return}
  timenetPending={owner:actorID,result:r};await saveReceived();
 }catch(e){failed(e)}finally{timenetBusy=false}
}
