// v2.4 UI and policy rules. Data access remains the existing simple RPC model.
function can(cap,a=S.user){if(['parent','student'].includes(a?.role)){if(cap==='makeups')return S.base?.makeup_summary?.assigned===true;return ['dashboard','classes','lessons','exams','consultations','videos','reports'].includes(cap)}return window.MiraeRoles.allows(a,cap,D.settings?.role_policy||S.base.role_policy)}
function requireCap(a,cap){if(!can(cap,a))throw Error('이 기능을 사용할 권한이 없습니다.')}
function isSuper(){return S.user?.role==='admin'}
const EDIT_CAP={students:'student_edit',parents:'parent_edit',classes:'class_edit',lessons:'lesson_edit',exams:'exam_edit',scores:'exam_edit',feedback:'lesson_edit',enrollments:'student_edit',consultations:'consultation_edit',videos:'video_edit',accounts:'staff_manage'};
function actionCap(act){if(act==='new'||act==='edit'||act==='import'||act==='save-grid'||act==='toggle-edit'||act==='bulk-status')return EDIT_CAP[S.view];return({'student-report':'reports','print-report':'reports','parent-detail':'parents','lesson-detail':'lessons','exam-detail':'exams','play-video':'videos','consult-detail':'consultations','syllabus-view':'classes','new-lesson-exam':'exam_edit','link-exam-lesson':'exam_edit','paste-scores':'exam_edit','apply-score-paste':'exam_edit','clear-class-grades':'lesson_edit','confirm-clear-grades':'lesson_edit','mark-roster-present':'lesson_edit','family-edit':'parent_edit','family-password':'parent_edit','new-lesson':'lesson_edit','edit-lesson':'lesson_edit','lesson-feedback':'lesson_edit','duplicate-lessons':'lesson_edit','edit-student':'student_edit','manual-student':'student_edit','import-students':'student_edit','add-enrollment':'student_edit','enrollment-edit':'student_edit','parent-for-student':can('parent_edit')?'parent_edit':'parents','family-create':'parent_edit','parent-edit':'parent_edit','parent-password':'parent_edit','edit-exam':'exam_edit','score-entry':'exam_edit','edit-video':'video_edit','timenet-refresh':'timenet','check-sheet':'timenet','roster-picker':'student_edit','export':'export','syllabus-edit':'syllabus_edit'})[act]}
function rankName(a){return window.MiraeRoles.rank(a,S.base.role_policy||D.settings?.role_policy).name}
function canEditDesign(a=S.user){return can('login_design',a)}
function accessibleNav(){if(isFamily())return NAV.filter(([k])=>(S.user.role!=='student'||k!=='consultations')&&(['dashboard','classes','lessons','exams','consultations','videos','reports'].includes(k)||k==='makeups'&&can('makeups')));return NAV.filter(([k])=>!['lessons','exams','videos','settings'].includes(k)).filter(([k])=>k==='student_accounts'?(can('students')||can('parents')):k==='student_search'?(can('students')||can('attendance_overview')||MiraeCounsel.context().counselor):k==='withdrawal_processing'?MiraeCounsel.context().counselor===true:['withdrawals','counsel_manage','counsel_calendar','withdrawal_lines','withdrawal_overview','withdrawal_cancel'].includes(k)?MiraeCounsel.allowed(k):k==='admissions'?MiraeAdmissions.allowed():k==='syllabus_library'?MiraeCounsel.context().counselor===true:k==='timenet_counsel'?can('consultations'):k==='school_grades'?['admin','teacher'].includes(S.user.role):k==='students'?true:k==='tasks'?true:k==='transfers'?true:k==='attendance_book'?can('attendance'):k==='login_history'?(can('login_history_all')||can('login_history_own')):k==='push'?true:k==='communications'?true:k==='push_status'?canViewAlarmStatus():k==='detail_settings'?(isSuper()||can('report_template')||can('pc_settings')):['student_reports','course_data','exam_papers','staff_resources','school_login','course_reports','messenger','updates'].includes(k)?true:['settings','ranks','timenet_account'].includes(k)?isSuper():can(({accounts:'staff_manage',appearance:'login_design',push:'push_send',parent_phones:'mswitch_contact',student_accounts:'students'})[k]||k))}
function mobileNavHTML(){if(!window.MiraePC?.isMobile||isFamily())return'';const permitted=accessibleNav();const picks=['attendance','students','classes'].filter(v=>permitted.some(([k])=>k===v));return'<nav class="mobile-app-nav" aria-label="빠른 메뉴">'+picks.map(v=>`<button data-action="navigate" data-view="${v}" class="${S.view===v?'active':''}">${icon(v==='attendance'?'calendar':v,18)}<span>${v==='attendance'?'출결':v==='students'?'학생':'강좌'}</span></button>`).join('')+'<button data-action="mobile-menu">'+icon('menu',18)+'<span>더보기</span></button></nav>'}
function guardRoute(a,route,write){if(route==='/api/contact/matched'||route==='/api/contact/matched-batch'){requireCap(a,'mswitch_contact');return}
 if(route==='/api/makeups/stats')return;
 if(route.startsWith('/api/makeups/')){if(a.role!=='parent'&&a.role!=='student')requireCap(a,write?'makeup_manage':'makeups');return}
 if(['parent','student'].includes(a.role)){if(!['/api/workspace','/api/bootstrap','/api/data','/api/me','/api/logout','/api/change-password','/api/change-login-id','/api/consultations','/api/video-progress'].includes(route)&&!/^\/api\/(classes\/[^/]+\/syllabus|consultations\/[^/]+\/cancel)$/.test(route))throw Error('조회할 수 없는 메뉴입니다.');return;}
 if(route==='/api/settings'||route.startsWith('/api/v2/')||route==='/api/ranks'){assertAdmin(a);return}
 if(route==='/api/accounts'){requireCap(a,'staff_manage');return}
 if(route==='/api/audit'){requireCap(a,'audit');return}
 if(route==='/api/oversight'){requireCap(a,'oversight');return}
 if(route==='/api/mswitch/credentials'){if(!can('sms',a)&&!can('attendance_notify',a)&&!can('mswitch_contact',a))throw Error('엠스위치를 사용할 권한이 없습니다.');return}
 if(route==='/api/mswitch/local-parents'){requireCap(a,'sms');return}
 if(route.startsWith('/api/timenet/')){if(['/api/timenet/cache','/api/timenet/pc-config'].includes(route))requireCap(a,'timenet');else if(!can('students',a)&&!can('timenet',a))throw Error('학생 명단 열람 권한이 없습니다.');return}
 if(route==='/api/attendance/overview'){requireCap(a,'attendance_overview');return}if(route.startsWith('/api/attendance/')){requireCap(a,'attendance');if(write)requireCap(a,['/claim','/retry','/report'].some(k=>route.endsWith(k))?'attendance_notify':route.endsWith('/link')?'attendance_notify':'attendance_edit');return}
 if(route.startsWith('/api/manage/')){requireCap(a,EDIT_CAP[route.split('/')[3]]||'student_edit');return}
 if(route==='/api/lesson-record'){requireCap(a,'lesson_edit');return}
 if(/^\/api\/exams\/.+\/results$/.test(route)){requireCap(a,'exam_edit');return}
 if(route.startsWith('/api/parents')||/^\/api\/students\/.+\/parent$/.test(route)){requireCap(a,write?'parent_edit':'parents');return}
 if(/^\/api\/classes\/.+\/syllabus$/.test(route)){requireCap(a,write?'syllabus_edit':'classes');return}
 if(route.endsWith('clear-homework-grades'))requireCap(a,'lesson_edit');
}
function guardSubject(a,route,body,path){const A=window.MiraeSubject;if(A.scope(a)==='all')return;const u=new URL(path,'https://browser.invalid'),visible=A.scoped(D,a);let cid=body.class_id||body.lesson?.class_id||u.searchParams.get('class_id');const parts=route.split('/');if(parts[2]==='classes'&&parts[3])cid=parts[3];if(parts[2]==='exams'&&parts[3])cid=D.exams.find(e=>e.id===parts[3])?.class_id;if(cid)A.assertClass(D,a,cid);const sid=body.student_id||(parts[2]==='students'?parts[3]:null);if(sid&&!visible.students.some(s=>s.id===sid))throw Error('지정된 과목의 학생만 관리할 수 있습니다.');if(parts[2]==='parents'&&parts[3]&&!['create','search'].includes(parts[3])&&!visible.parents.some(p=>p.id===parts[3]))throw Error('지정된 과목의 학부모만 열 수 있습니다.');}

function parentState(s){const p=(S.base.parents||[]).find(p=>p.id===s.parent_id);return !p?{label:'미배정',tone:'danger'}:p.status!=='active'?{label:'비활성 · '+p.name,tone:'warn'}:{label:'연결됨 · '+p.name,tone:'ok'}}
function parentConnection(s){const state=parentState(s);return'<span class="connection-state '+state.tone+'">'+esc(state.label)+'</span>'+(can('parent_edit')?btn('배정','parent-for-student',`data-id="${s.id}"`,'ghost sm'):'')}
function smsConnection(s){const A=window.MiraeAttendanceCore,r=window.MiraeSMS?.cachedRoster,source=A.sourceStudent(D,s,S.user),hasPhone=source.parent_phones.some(p=>String(p).replace(/\D/g,'').length>=9);let tone='warn',label='문자 연결 확인중';if(r){const m=A.matchStudent(source,r,D.studentLinks?.find(l=>l.owner_id===S.user.id&&l.student_id===s.id),r.account_username);if(['auto','manual'].includes(m.kind)){tone='ok';label='문자 연결됨'}else if(m.kind==='no_phone'||!hasPhone&&!(m.candidates||[]).some(t=>t.parent_phones.some(p=>p.length>=9))){tone='danger';label='학부모 번호 없음'}else label='문자 연결 필요'}else if(!hasPhone){tone='danger';label='학부모 번호 없음'}return'<span class="connection-state '+tone+'">'+esc(label)+'</span>'}
window.addEventListener('mirae-mswitch-roster',()=>{if(S.user&&S.view==='students')drawGrid()});
function sharedDirectory(rows){const map=new Map();for(const r of rows){const old=map.get(r.student_no);if(!old||String(r._cached_at||'')>=String(old._cached_at||''))map.set(r.student_no,r)}return [...map.values()]}
let directoryTimer=null,directoryPolling=false;
function directoryAge(){const stamp=S.base.timenet_meta?.updated_at;if(!stamp)return'아직 불러온 명단이 없습니다.';const seconds=Math.max(0,Math.floor(((window.MiraeServerClock?.now()??Date.now())-Date.parse(stamp))/1000));return(seconds<60?seconds+'초':seconds<3600?Math.floor(seconds/60)+'분':Math.floor(seconds/3600)+'시간')+' 전 명단'}
function paintDirectoryAge(){for(const node of document.querySelectorAll('[data-directory-age]'))node.textContent=directoryAge()}
function startDirectorySync(){if(directoryTimer||!S.user||isFamily()||!can('students')&&!can('timenet'))return;directoryTimer=setInterval(async()=>{paintDirectoryAge();if(directoryPolling||document.hidden||!S.user||isFamily())return;directoryPolling=true;const owner=S.user.id;try{const meta=await api('/api/timenet/meta');if(owner!==S.user?.id)return;if(meta.updated_at!==S.base.timenet_meta?.updated_at){S.base.timenet_meta=meta;directoryCache=null;paintDirectoryAge();window.dispatchEvent(new Event('mirae-directory-updated'))}}catch{}finally{directoryPolling=false}},5000)}
function stopDirectorySync(){clearInterval(directoryTimer);directoryTimer=null;directoryPolling=false}
function defaultView(){const views=accessibleNav();const last=window.MiraeServerPrefs?.last(S.user);if(last&&views.some(([k])=>k===last))return last;if(!MiraePC.isMobile)return views.some(([k])=>k==='dashboard')?'dashboard':views[0]?.[0]||'no-access';const preferred=S.user?.preferences?.start_view||(!isFamily()?'attendance':'dashboard');if(preferred==='attendance'&&views.some(([k])=>k==='attendance')){window.MiraeAttendance?.enter();return 'attendance'}return views.some(([k])=>k===preferred)?preferred:views[0]?.[0]||'no-access'}
async function openEditor(entity=S.view,id=null,override={}){if(!can(EDIT_CAP[entity]||'student_edit'))return toast('이 기능을 사용할 권한이 없습니다.',true);if(entity==='students'&&!id)return registration();if(entity!=='accounts')return baseOpenEditor(entity,id,override);return staffEditor(id)}
async function staffEditor(id){S.editorID=id||"new";if(!can('staff_manage'))return;const old=S.accounts.find(x=>x.id===id),p=window.MiraeRoles.policy(S.base.role_policy);if(id&&(!old||!staffManageAllowed(S.user,old)))return toast('변경할 수 없는 직급입니다.',true);const ranks=p.ranks.filter((r,i)=>isSuper()||i+1>window.MiraeRoles.level(S.user,p));if(!ranks.length)return toast('배정 가능한 하위 직급이 없습니다.',true);modal(old?'계정 수정':'강사 등록','<form id="edit-form">'+fieldsHtml([{key:'name',label:'이름',required:true},{key:'login_id',label:'아이디',required:true},{key:'password',label:old?'비밀번호 변경 · 선택':'초기 비밀번호',type:'password',required:!old},{key:'rank_id',label:'직급',type:'select',options:ranks.map(r=>[r.id,r.name]),default:old?.role==='admin'?'admin':old?.rank_id||'teacher'},{key:'login_history_scope',label:'로그인 이력 조회',type:'select',options:[['inherit','직급 설정 따름 · 기본 담당 학생·학부모'],['own','내 강좌 학생·학부모'],...(can('login_history_all')?[['all','모든 사용자']]:[])],default:old?.login_history_scope==='none'?'own':old?.login_history_scope||'inherit'},{key:'subject_scope',label:'첫 번째 분류',type:'select',options:window.MiraeSubject.OPTIONS.filter(x=>MiraeSubject.allows(S.user,x[0])),default:old?.subject_scope||window.MiraeSubject.scope(S.user)},{key:'subject_scope2',label:'두 번째 분류',type:'select',options:[['','선택 안 함'],...MiraeSubject.OPTIONS.filter(x=>x[0]!=='all'&&MiraeSubject.allows(S.user,x[0]))],default:old?.subject_scope2||''},{key:'status',label:'재직 상태',type:'select',options:[['active','재직'],['inactive','비활성'],['departed','퇴사']],default:'active'}],old||{})+'</form>',btn('취소','close-modal')+btn('저장','save-editor','','primary'));const editor=M,form=$('#edit-form',editor.node);const first=form.elements.subject_scope,second=form.elements.subject_scope2;if(first&&second){const update=()=>{second.disabled=first.value==='all';if(second.disabled||second.value===first.value)second.value='';[...second.options].forEach(x=>x.disabled=!!x.value&&x.value===first.value)};first.addEventListener('change',update);update()}editor.save=async()=>{if(!form.reportValidity()||editor.busy)return;const row=collect(form);row.role=row.rank_id==='admin'?'admin':'teacher';if(row.role==='admin')row.subject_scope='all';if(row.subject_scope==='all')row.subject_scope2='';if(old)Object.assign(row,{id:old.id,version:old.version});editor.busy=true;try{await api('/api/manage/accounts/bulk',{method:'POST',body:{rows:[row]}});closeModal(true);await reload(true);toast('저장완료')}catch(e){errorBox(e.message)}finally{editor.busy=false}};form.onsubmit=e=>{e.preventDefault();editor.save()}}
async function renderRanks(){const node=$('#main');node.innerHTML=head('직급 · 권한')+'<div class="workspace-loading" role="status">불러오는 중</div>';const loaded=await api('/api/ranks');if(!node.isConnected)return;let draft=clone(loaded.policy);let expected=loaded.revision;const draftKey='rank-policy|'+S.user.id,preserved=MiraeDrafts.getModel(draftKey);if(preserved?.revision===expected)draft=clone(preserved.policy);const remember=()=>MiraeDrafts.setModel(draftKey,{revision:expected,policy:clone(draft)});node.innerHTML=head('직급 · 권한')+'<div class="rank-count"><label>직급 개수 <select id="rank-count" data-draft-ignore>'+Array.from({length:19},(_,i)=>`<option value="${i+2}" ${draft.ranks.length===i+2?'selected':''}>${i+2}개</option>`).join('')+'</select></label><button class="btn" data-ranks-reload>새로고침</button><button class="btn primary" data-ranks-save>변경 저장</button></div><div data-ranks-list></div><p data-ranks-result role="status"></p>';
 const syncPermissionDependencies=()=>{for(const [edit,view]of [['admission_all','admission_receive'],['classes_all_edit','classes_all_view'],['attendance_override','attendance_all_view']])node.querySelectorAll(`[data-rank-permission="${edit}"]`).forEach(el=>{const r=draft.ranks[+el.dataset.rank],allowed=r.permissions.includes(view);el.disabled=!allowed;if(!allowed){el.checked=false;r.permissions=r.permissions.filter(k=>k!==edit)}el.closest('label').classList.toggle('permission-dependent-disabled',!allowed);el.closest('label').title=allowed?'':MiraeRoles.CAP[view]+' 권한을 먼저 선택하세요.'})};const draw=()=>{node.querySelector('[data-ranks-list]').innerHTML=draft.ranks.map((r,i)=>`<details class="rank-card" ${i===1?'open':''}><summary>${i+1}. ${esc(r.name)}${i===0?' · 최고관리자':''}</summary><label>직급 이름<input class="input" data-draft-ignore data-rank-name="${i}" value="${esc(r.name)}" maxlength="40"></label>${i===0?'<p>최고관리자는 모든 권한을 항상 가집니다. </p>':'<div class="permission-grid">'+Object.entries(window.MiraeRoles.CAP).filter(([k])=>!['login_history_own','login_history_all','push_send','push_status'].includes(k)).map(([k,l])=>`<label><input type="checkbox" data-draft-ignore data-rank-permission="${k}" data-rank="${i}" ${r.permissions.includes(k)?'checked':''} ${k==='timenet'?'disabled':''}>${l}${k==='timenet'?' · 임직원 공통':''}</label>`).join('')+'</div><label>직원·학부모 앱푸시 발송 범위<select class="input" data-draft-ignore data-push-rank="'+i+'">'+[['all','직원·학부모에게 가능'],['staff','직원에게만 가능'],['parents','학부모에게만 가능'],['none','직원·학부모 발송 불가']].map(([v,l])=>'<option value="'+v+'" '+(window.MiraeRoles.pushScope({role: "teacher",rank_id:r.id},{ranks:draft.ranks})===v?'selected':'')+'>'+l+'</option>').join('')+'</select></label><label>로그인 이력 조회<select class="input" data-draft-ignore data-history-rank="'+i+'"><option value="own" '+(!r.permissions.includes('login_history_all')?'selected':'')+'>내 강좌 학생·학부모</option><option value="all" '+(r.permissions.includes('login_history_all')?'selected':'')+'>모든 사용자</option></select></label>'}</details>`).join('');node.querySelectorAll('[data-push-rank]').forEach(e=>e.onchange=()=>{const r=draft.ranks[+e.dataset.pushRank];r.push_scope=e.value;r.permissions=r.permissions.filter(k=>k!=='push_send');if(e.value!=='none')r.permissions.push('push_send')});node.querySelectorAll('[data-history-rank]').forEach(e=>e.onchange=()=>{const r=draft.ranks[+e.dataset.historyRank];r.permissions=r.permissions.filter(k=>!['login_history_own','login_history_all'].includes(k));if(e.value!=='none')r.permissions.push('login_history_'+e.value)});node.querySelectorAll('[data-rank-name]').forEach(e=>e.oninput=()=>draft.ranks[+e.dataset.rankName].name=e.value);node.querySelectorAll('[data-rank-permission]').forEach(e=>e.onchange=()=>{const r=draft.ranks[+e.dataset.rank];r.permissions=r.permissions.filter(k=>k!==e.dataset.rankPermission);if(e.checked)r.permissions.push(e.dataset.rankPermission);syncPermissionDependencies()});syncPermissionDependencies();node.querySelectorAll('[data-rank-name],[data-rank-permission],[data-push-rank],[data-history-rank],[data-rank-nonteaching]').forEach(x=>{x.addEventListener(x.matches('[data-rank-name]')?'input':'change',remember)})};draw();node.querySelector('#rank-count').onchange=e=>{const count=+e.target.value;while(draft.ranks.length<count){let n=2;while(draft.ranks.some(r=>r.id==='rank_'+n))n++;draft.ranks.push({id:'rank_'+n,name:'직급 '+(draft.ranks.length+1),non_teaching:false,permissions:['dashboard','classes','student_push']})}draft.ranks=draft.ranks.slice(0,count);remember();draw()};node.querySelector('[data-ranks-reload]').onclick=async ()=>{if(MiraeDrafts.getModel(draftKey)&&!(await MiraeDialog.confirm('입력 중인 변경을 취소하고 최신 권한을 불러오시겠습니까?')))return;MiraeDrafts.clearModel(draftKey);renderRanks()};node.querySelector('[data-ranks-save]').onclick=async e=>{e.target.disabled=true;const controls=[...node.querySelectorAll('input,select,[data-ranks-reload]')].map(x=>[x,x.disabled]);controls.forEach(([x])=>x.disabled=true);try{const result=await api('/api/ranks',{method:'POST',body:{policy:clone(draft),expected_revision:expected}});expected=result.revision;draft=clone(result.policy);S.base.role_policy=result.policy;D.settings.role_policy=result.policy;D.settings.role_revision=result.revision;MiraeDrafts.setModel(draftKey,null);node.querySelector('#rank-count').value=String(draft.ranks.length);draw();toast('저장완료');node.querySelector('[data-ranks-result]').textContent='저장완료'}catch(error){node.querySelector('[data-ranks-result]').textContent=error.message}finally{controls.forEach(([x,disabled])=>{if(x.isConnected)x.disabled=disabled});e.target.disabled=false}};
}
