async function parentForStudent(sid){const r=await api('/api/students/'+sid+'/parent'),s=r.student,p=r.parent;if(!can('parent_edit')){modal(s.name+' · 학부모 정보',`<div class="family-subject">${studentCell(s)}</div><div class="family-kv"><span>학부모</span><b>${esc(p?.name||'미배정')}</b><span>아이디</span><b>${esc(p?.login_id||'—')}</b><span>연락처</span><b>${esc(p?.phone||'미입력')}</b></div>`,btn('닫기','close-modal'));return}modal(s.name+' · 학부모 배정',`<div class="family-subject">${studentCell(s)}</div><section class="family-existing"><strong>현재 배정 · ${esc(p?.name||'미배정')}</strong>${p?'<p>'+esc(p.login_id)+' · '+esc(p.phone||'번호 없음')+'</p>':''}</section><h3>추천 학부모</h3><div data-parent-recommend></div><form id="parent-search-form" class="family-search"><input class="input" name="query" placeholder="학부모 이름·아이디·전화번호" aria-label="학부모 계정 검색"><button class="btn" type="submit">검색</button></form><div id="parent-search-results"></div><div class="inline-error hidden"></div>`,btn('닫기','close-modal')+btn('새 학부모 만들기','family-create','','','plus'),{wide:true});const editor=M;editor.node.querySelector('[data-action=family-create]')?.addEventListener('click',()=>createParentModal(s,r));
 const draw=(box,rows)=>{box.innerHTML=rows.length?rows.map(y=>`<article class="parent-recommend"><div><strong>${esc(y.name)}</strong> ${y.id===p?.id?'<span class="connection-state ok">현재 배정</span>':''}<small>${esc(y.login_id)} · ${esc(y.phone||'번호 없음')}</small><small>${y.children?.length?'배정 학생: '+esc(y.children.map(x=>x.name).join(', ')):'아직 배정된 학생 없음'}</small></div>${btn(y.id===p?.id?'배정됨':'이 학부모에게 배정','family-assign',`data-parent="${y.id}" ${y.id===p?.id?'disabled':''}`,'sm primary')}</article>`).join(''):empty('추천할 학부모가 없습니다.');box.querySelectorAll('[data-parent]').forEach(b=>b.onclick=async()=>{if(!(await reassignConsent(s,b.dataset.parent,p?.id)))return;b.disabled=true;try{await api('/api/students/'+s.id+'/parent',{method:'POST',body:{parent_id:b.dataset.parent,expected_parent_id:p?.id||null,confirmed:!!p}});closeAll();await reload(true);toast('저장완료')}catch(e){errorBox(e.message);b.disabled=false}})};
 try{const suggested=await api('/api/parents/search?'+new URLSearchParams({student_id:s.id,recommend:'1'}));if(editor.node.isConnected)draw(editor.node.querySelector('[data-parent-recommend]'),suggested.rows)}catch(e){errorBox(e.message)}const form=$('#parent-search-form',editor.node);form.onsubmit=async e=>{e.preventDefault();try{const result=await api('/api/parents/search?'+new URLSearchParams({student_id:s.id,q:form.elements.query.value}));if(editor.node.isConnected)draw($('#parent-search-results',editor.node),result.rows)}catch(e){errorBox(e.message)}};
}
