actions['syllabus-view']=b=>syllabusModal(b.dataset.id);actions['syllabus-edit']=b=>{closeModal(true);return syllabusEditor(b.dataset.id)};
function platformLoginMarkup(d=loginDesign,preview=false,mobile=MiraePC.isMobile){return `<div class="login-layout ${mobile?'mobile-login':'desktop-login'} ${preview?'design-preview':''}" data-layout="center" data-align="center"><section class="digital-login-card">${mobile?'':`<svg class="digital-login-edge" viewBox="0 0 460 530" preserveAspectRatio="none" aria-hidden="true"><rect x="1" y="1" width="458" height="528" rx="28" pathLength="100"></rect><rect x="1" y="1" width="458" height="528" rx="28" pathLength="100"></rect></svg>`}<div class="login-form"><header class="digital-login-brand"><div class="digital-login-kicker">Time Education</div><h1 class="digital-login-title"><span class="digital-title-main">미래탐구</span><span class="digital-title-rest">클래스룸</span></h1></header><form ${preview?'class="preview-form"':'id="login-form"'}>${fieldsHtml([{key:'name',label:'아이디',placeholder:'아이디를 입력해 주세요',required:true,wide:true,maxlength:100},{key:'password',label:'비밀번호',type:'password',required:true,wide:true,maxlength:200}])}<label class="login-remember"><input type="checkbox" name="remember" ${rememberDefault()?'checked':''}>로그인 유지</label><div class="inline-error hidden" id="${preview?'preview-error':'login-error'}" role="alert"></div><button type="${preview?'button':'submit'}" class="btn primary login-submit"><span class="login-button-label">로그인</span><span class="login-button-icon">${icon('arrow')}</span></button></form><div class="login-promotions digital-login-promotions">${promotionMarkup(d)}</div><small class="login-foot" data-login-copy="footer">${esc(d.footer)}</small>${!preview&&DEMO?btn('예시 화면으로 돌아가기','demo-login','','ghost'):''}</div></section></div>`}
function loginMarkup(d=loginDesign,preview=false){return platformLoginMarkup(d,preview)}



function registration(){if(!can('student_edit'))return;modal('타임넷 학생 등록','<div data-enroll-sheet></div>',btn('닫기','close-modal'),{wide:true});const editor=M;editor.node.classList.add('enroll-sheet-modal');const header=editor.node.querySelector('.modal-head'),maximize=document.createElement('button');maximize.type='button';maximize.className='btn sm enroll-maximize';maximize.textContent='최대화';maximize.setAttribute('aria-label','학생 등록창 최대화');maximize.setAttribute('aria-pressed','false');header.insertBefore(maximize,header.lastElementChild);maximize.onclick=()=>{const full=editor.node.classList.toggle('enroll-maximized');maximize.textContent=full?'원래 크기':'최대화';maximize.setAttribute('aria-pressed',String(full))};const sheet=window.MiraeEnroll.mount(editor.node.querySelector('[data-enroll-sheet]'),{can,user:()=>S.user,base:()=>MiraeViewScope.base(S.base),refreshBase:async()=>{db.lastRefresh=0;return api('/api/bootstrap',{fresh:true})},classID:S.classId||S.courseID,today:today(),api,directory:loadDirectory,metadata:()=>S.base.timenet_meta,parse:parseDelimited,enrollment:async(action,data)=>{const auth=await MiraePush.ensureSession();const result=await db.rpc('mirae_enrollment',{p_session:auth.session,p_action:action,p_data:data});if(result.roster_issues?.length)MiraeFastReads.report('학생 중복 확인',Error(result.roster_issues.map(x=>x.name+' · '+x.reason).join('\n')));return result},invalidate:()=>{db.lastRefresh=0;loginSnapshot=null;inflightReads.clear();MiraeFastReads.invalidate();MiraeStudentRemoval.invalidate();MiraeAttendance.reset();MiraePhoneReview.invalidate();MiraeGradeHistory.invalidate()},refreshSaved:async()=>{db.lastRefresh=0;await refreshPrivateState();inflightReads.clear()},setBusy:v=>editor.busy=v,saved:async count=>{closeAll();await reload(true);toast(count+'명 등록완료');S.view='student_accounts';renderPage()}});editor.cleanup=()=>sheet.dispose()}
function smsConnection(s){const A=window.MiraeAttendanceCore,r=window.MiraeSMS?.cachedRoster,source=A.sourceStudent(D,s,S.user);let tone='checking',label=MiraeMSCache.collecting?'수신중':'명단 준비중',reason=MiraeMSCache.statusText();if(r){const m=A.matchStudent(source,r,D.studentLinks?.find(l=>l.owner_id===S.user.id&&l.student_id===s.id),r.account_username);if(['auto','manual'].includes(m.kind)){tone=MiraePC.state==='connected'?'ok':'warn';label=MiraePC.state==='connected'?'양호':'발송 대기';reason=MiraePC.state==='connected'?'문자 수신자가 연결되어 있습니다.':'수신자는 연결되어 있습니다. 발송에는 PC 연결이 필요합니다.'}else{tone='danger';label='수신자 확인';reason=m.kind==='no_phone'?'학부모 번호가 없습니다.':'학부모 수신자를 확인해 주세요.'}}else if(MiraePC.state==='update'){tone='warn';label='업데이트 필요'}else if(['offline','limited'].includes(MiraePC.state)){tone='muted';label='PC 연결 대기'}return'<span class="connection-state '+tone+'" title="'+esc(reason)+'">'+label+'</span>'}
