async function manageAccounts(action,kind,ids,status,onProgress){
 const auth=await MiraePush.ensureSession(),owner=S.user.id,targets=[...new Set(ids)],versions=Object.fromEntries(targets.map(id=>[id,(D[kind]||[]).find(x=>x.id===id)?.version||1]));let completed=0;
 try{for(let i=0;i<targets.length;i+=500){if(S.user?.id!==owner)throw Error('로그인 계정이 변경되었습니다.');const batch=targets.slice(i,i+500);
 const result=await db.rpc('mirae_management_bridge',{p_session:auth.session,p_action:action,p_data:{kind,ids:batch,status,versions}});if(!result.ok)throw Error(result.message||'처리하지 못했습니다.');
 completed+=result.count;batch.forEach(id=>S.selected.delete(id));db.lastRefresh=0;loginSnapshot=null;inflightReads.clear();MiraeFastReads.invalidate();MiraeStudentRemoval.invalidate();MiraeAttendance.reset();MiraePhoneReview.invalidate();MiraeGradeHistory.invalidate();onProgress?.(completed,targets.length);
 }await reload(true);return{ok:true,count:completed};
 }catch(e){db.lastRefresh=0;await reload(true);if(completed)e.message=completed+'명 처리 완료. 남은 '+(targets.length-completed)+'명: '+e.message;throw e;}
}

async function accountChangeModal(kind,ids,status){if(kind==='students'&&!status){if(ids.length!==1)return toast('학생별 원생 삭제 버튼에서 제거할 반을 선택하세요.',true);return MiraeStudentRemoval.open(ids[0],S.classId||S.courseID)}if(!ids.length)return toast('계정을 먼저 선택해 주세요.',true);const cap=status?'parent_status':kind==='students'?'student_delete':'parent_delete';requireCap(S.user,cap);if(kind==='students'&&!status){const check=await MiraeStudentRemoval.read(ids,true);const blocked=check.find(r=>!r.can_delete);if(blocked){MiraeStudentRemoval.paint();return toast(blocked.reason||'삭제할 수 없는 학생이 포함되어 있습니다.',true)}}const rows=ids.map(id=>(D[kind]||[]).find(x=>x.id===id)).filter(Boolean);const title=status?(status==='active'?'학부모 계정 활성화':'학부모 계정 비활성화'):kind==='students'?'원생 삭제':'계정 삭제';modal(title,'<p class="management-intro">'+(status?'선택한 학부모 '+rows.length+'명의 로그인 상태를 변경합니다. 연락처와 학생 기록은 유지됩니다.':'선택한 '+rows.length+'명의 계정을 삭제합니다. 학생 계정을 삭제하면 현재 수강 배정도 종료됩니다. 지난 출결·성적 기록은 보관합니다. 엠스위치와 타임넷 원본은 변경하지 않습니다.')+'</p><div class="management-targets">'+rows.map(r=>'<span>'+esc(r.name)+'</span>').join('')+'</div>'+(!status?'<label class="check-label"><input type="checkbox" id="confirm-account-removal" data-draft-ignore>선택한 계정을 확인했습니다.</label>':''),btn('취소','close-modal')+btn(status?'변경하기':'삭제하기','save-editor','',status?'primary':'danger'));const m=M;m.save=async()=>{if(m.busy)return;if(!status&&!$('#confirm-account-removal',m.node)?.checked)return errorBox('삭제할 계정을 확인해 주세요.');m.busy=true;const button=$('[data-action=save-editor]',m.node),label=button.textContent;button.disabled=true;button.textContent=status?'변경 중…':'삭제 중…';try{await manageAccounts(status?'parent_status':'delete',kind,ids,status,(done,total)=>{button.textContent=done+' / '+total+'명 처리'});closeAll();toast(status?'계정 상태를 변경했습니다.':'계정을 삭제했습니다.')}catch(e){errorBox(e.message)}finally{m.busy=false;button.disabled=false;button.textContent=label}}}
