function familyPresentationData(){
 const scoped=localScope(),sid=childID(),a=localIdentity(),classes=scoped.classes,cids=new Set(classes.map(c=>c.id));
 const lessons=D.lessons.filter(l=>cids.has(l.class_id)&&l.published!==false).map(l=>familyLesson(l,sid));
 const exams=D.exams.filter(e=>cids.has(e.class_id)&&e.published!==false&&MiraePublication.allows(a,D.classes.find(c=>c.id===e.class_id),D.lessons.find(l=>l.id===e.lesson_id),'exams'));
 const lids=new Set(lessons.map(l=>l.id)),eids=new Set(exams.map(e=>e.id)),stats={};
 for(const e of exams){const t=db.examStats?.[e.id];if(t)stats[e.id]={mean:t.mean,count:t.count,rank:t.ranks?.[sid]??null}}
 const feedback=D.feedback.filter(f=>f.student_id===sid&&lids.has(f.lesson_id)).map(f=>{const x={...f},l=D.lessons.find(l=>l.id===f.lesson_id),c=D.classes.find(c=>c.id===l?.class_id);delete x.private_note;if(!MiraePublication.allows(a,c,l,'feedback'))x.comment='';if(!MiraePublication.allows(a,c,l,'homework'))x.homework_grade=null;return x});
 return{sid,owner:S.user?.id,student:getStudent(sid),today:today(),classes,enrollments:scoped.enrollments,lessons,exams,scores:D.scores.filter(s=>s.student_id===sid&&eids.has(s.exam_id)),feedback,stats};
}
