/* mobile-flow.261027_2.js */
(()=>{'use strict';
const mobile=matchMedia('(max-width:760px)');let queued=false;
const excluded='.overview-table,.student-unified-results,.push-status-table,.login-history-table79,.usage-table,.attendance-book-table,.bulk-table75,.paper-catalog-table,.enroll-sheet,.tn-entry-table,[data-mobile-table-native]';
function adapt(table){
 if(table.matches(excluded)||table.closest('.fh-chart-scroll,.viewer,.photo-viewer'))return;
 const head=table.tHead?.rows[table.tHead.rows.length-1]||[...table.rows].find(r=>r.cells.length&&[...r.cells].every(c=>c.tagName==='TH'));if(!head||!table.tBodies.length)return;
 const headers=[...head.cells].map(c=>c.textContent.replace(/[↕↑↓]/g,'').trim().replace(/\s+/g,' '));
 // Use cards only for a wide table. Existing compact tables retain their layout.
 if(!table.classList.contains('mobile-cards78')&&table.scrollWidth<=table.parentElement.clientWidth+2&&headers.length<5)return;
 table.classList.add('mobile-cards78');head.classList.add('mobile-header78');
 for(const row of [...table.tBodies].flatMap(b=>[...b.rows])){
  if(row===head||row.querySelector('[data-mobile-details78]'))continue;
  const cells=[...row.cells];if(cells.length!==headers.length||cells.some(c=>c.colSpan>1)){row.classList.add('mobile-full-row78');continue}
  const candidates=cells.map((c,i)=>({c,i,h:headers[i]})).filter(x=>!/^([#№]|번호|순번)$/.test(x.h));
  const primary=new Set(candidates.slice(0,2).map(x=>x.i));candidates.forEach(x=>{if(/출결|수신 상태|점수|성적|^상태$/.test(x.h))primary.add(x.i)});
  candidates.forEach(x=>{if(/관리|작업|선택|수정|삭제/.test(x.h)||!x.h&&x.c.querySelector('button,a,input'))primary.add(x.i)});
  let extra=0;cells.forEach((c,i)=>{c.dataset.mobileLabel78=headers[i]||'';if(/^([#№]|번호|순번)$/.test(headers[i])){c.classList.add('mobile-index78');return}if(!primary.has(i)){c.classList.add('mobile-secondary78');extra++}});
  if(extra){const b=document.createElement('button');b.type='button';b.className='btn sm mobile-details78';b.dataset.mobileDetails78='';b.textContent='자세히';b.setAttribute('aria-expanded','false');b.onclick=e=>{e.preventDefault();e.stopPropagation();const open=row.classList.toggle('mobile-open78');b.textContent=open?'접기':'자세히';b.setAttribute('aria-expanded',String(open))};(cells[candidates[0]?.i]||cells[0]).append(b)}
 }
}
function scan(){queued=false;if(!mobile.matches)return;document.querySelectorAll('#main table,.modal table,dialog table').forEach(adapt);document.querySelectorAll('#main [class],.modal [class],dialog [class]').forEach(e=>{if(!/list|scroll|history|targets|directory|messages/.test(e.className)||e.closest('.fh-chart-scroll,.viewer,.photo-viewer,.mc-app.mobile,.student-unified-results,.work-ref-results15')||e.matches('dialog,.modal,.modal-body,textarea,input,select,[role=listbox]'))return;const s=getComputedStyle(e);if(e.clientHeight&&e.scrollHeight>e.clientHeight+2&&/auto|scroll/.test(s.overflowY))e.classList.add('mobile-flow-list78')})}
function schedule(){if(queued)return;queued=true;requestAnimationFrame(scan)}
new MutationObserver(schedule).observe(document.documentElement,{childList:true,subtree:true});mobile.addEventListener('change',schedule);window.addEventListener('resize',schedule);schedule();
window.MiraeMobileFlow78={scan};
})();
